const p = JSON.parse(fs.readFileSync('scratch/live_product.json', 'utf8'));
console.log('Sections details:');
for (const [key, section] of Object.entries(p.sections)) {
  console.log(`\nKey: ${key} | Type: ${section.type}`);
  console.log('Settings:', JSON.stringify(section.settings, null, 2));
  if (section.blocks) {
    console.log('Blocks count:', Object.keys(section.blocks).length);
  }
}

