import fs from 'fs';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || "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";

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      client_id: CLIENT_ID,
      client_secret: CLIENT_SECRET,
      grant_type: 'client_credentials'
    })
  });
  const data = await res.json();
  return data.access_token;
}

// Upload file to shopify using GraphQL stagedUploadsCreate
async function uploadFile(token, fileUrl, alt) {
  const stagedQuery = `
    mutation stagedUploadsCreate($input: [StagedUploadInput!]!) {
      stagedUploadsCreate(input: $input) {
        stagedTargets {
          url
          resourceUrl
          parameters {
            name
            value
          }
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  // First fetch the remote file buffer
  const fileRes = await fetch(fileUrl);
  const buffer = await fileRes.arrayBuffer();
  const filename = fileUrl.split('?')[0].split('/').pop();

  const stagedRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2025-01/graphql.json`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      query: stagedQuery,
      variables: {
        input: [
          {
            filename: filename,
            mimeType: fileRes.headers.get('content-type') || 'image/jpeg',
            resource: 'IMAGE',
            fileSize: buffer.byteLength.toString(),
            httpMethod: 'POST'
          }
        ]
      }
    })
  });

  const stagedData = await stagedRes.json();
  const target = stagedData.data?.stagedUploadsCreate?.stagedTargets?.[0];
  if (!target) {
    console.error('Failed staged upload:', JSON.stringify(stagedData));
    return fileUrl;
  }

  // Upload to S3/GCS staged target
  const formData = new FormData();
  target.parameters.forEach(p => formData.append(p.name, p.value));
  formData.append('file', new Blob([buffer]));

  const s3Res = await fetch(target.url, {
    method: 'POST',
    body: formData
  });

  // Create file in Shopify
  const createQuery = `
    mutation fileCreate($files: [FileCreateInput!]!) {
      fileCreate(files: $files) {
        files {
          id
          fileStatus
          alt
          ... on MediaImage {
            image {
              url
            }
          }
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  const createRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2025-01/graphql.json`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      query: createQuery,
      variables: {
        files: [
          {
            alt: alt,
            contentType: 'IMAGE',
            originalSource: target.resourceUrl
          }
        ]
      }
    })
  });

  const createData = await createRes.json();
  console.log(`Created file ${filename}:`, JSON.stringify(createData.data?.fileCreate?.files));
  return createData.data?.fileCreate?.files?.[0]?.image?.url || target.resourceUrl;
}

async function main() {
  const token = await getAccessToken();
  const kneepads = await uploadFile(token, 'https://babimate.com/cdn/shop/files/babi-knee-pads-5-pack-328199.jpg?v=1711047381', 'BabiGuard Anti-Slip Crawling Knee Pads');
  const socks = await uploadFile(token, 'https://babimate.com/cdn/shop/files/non-slip-socks-12-pack-130007.webp?v=1719841413', 'BabiGuard Non-Slip Grip Socks');
  console.log('Kneepads URL:', kneepads);
  console.log('Socks URL:', socks);
}

main().catch(console.error);

