import { spawn } from 'child_process';
import fs from 'fs';

const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const tempDir = 'C:\\Users\\Admin\\AppData\\Local\\Temp\\chrome_cdp_test';

if (!fs.existsSync(tempDir)) {
  fs.mkdirSync(tempDir, { recursive: true });
}

console.log('Launching headless Chrome...');
const chromeProc = spawn(chromePath, [
  '--headless=new',
  '--remote-debugging-port=9222',
  `--user-data-dir=${tempDir}`,
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check'
], { detached: false });

chromeProc.stderr.on('data', d => {
  // console.log('Chrome stderr:', d.toString());
});

async function main() {
  await new Promise(r => setTimeout(r, 2000));

  let tabs;
  for (let i = 0; i < 5; i++) {
    try {
      const res = await fetch('http://127.0.0.1:9222/json');
      tabs = await res.json();
      break;
    } catch (e) {
      await new Promise(r => setTimeout(r, 1000));
    }
  }

  if (!tabs || tabs.length === 0) {
    console.error('No tabs found!');
    chromeProc.kill();
    return;
  }

  console.log('Found tab:', tabs[0].id, tabs[0].webSocketDebuggerUrl);

  const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);
  let id = 1;
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const curId = id++;
      const handler = (evt) => {
        const msg = JSON.parse(evt.data.toString());
        if (msg.id === curId) {
          ws.removeEventListener('message', handler);
          if (msg.error) reject(msg.error);
          else resolve(msg.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id: curId, method, params }));
    });
  }

  ws.addEventListener('open', async () => {
    try {
      console.log('Navigating to https://tryzavelyn.com/products/babiguard-head-protector ...');
      await send('Page.enable');
      await send('DOM.enable');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 1280,
        height: 1400,
        deviceScaleFactor: 1,
        mobile: false
      });

      await send('Page.navigate', { url: 'https://tryzavelyn.com/products/babiguard-head-protector' });
      await new Promise(r => setTimeout(r, 4000));

      // Take screenshot of viewport
      console.log('Capturing viewport screenshot...');
      const ssResult = await send('Page.captureScreenshot', { format: 'png' });
      const buffer = Buffer.from(ssResult.data, 'base64');
      fs.writeFileSync('scratch/babiguard_lushroot_desktop.png', buffer);
      console.log('Saved screenshot to scratch/babiguard_lushroot_desktop.png (size:', buffer.length, ')');

      // Check DOM in browser
      const titleEval = await send('Runtime.evaluate', { expression: 'document.title' });
      console.log('Page Title in browser:', titleEval.result?.value);

      const headingEval = await send('Runtime.evaluate', { expression: 'document.querySelector("h1")?.innerText' });
      console.log('H1 in browser:', headingEval.result?.value);

      const hasLr = await send('Runtime.evaluate', { expression: '!!document.querySelector(".lr-pdp-wrapper")' });
      console.log('Has .lr-pdp-wrapper in browser DOM:', hasLr.result?.value);

      const hasZavelynMain = await send('Runtime.evaluate', { expression: '!!document.querySelector(".zv-pdp-section-wrap")' });
      console.log('Has .zv-pdp-section-wrap in browser DOM:', hasZavelynMain.result?.value);

    } catch (err) {
      console.error('Error during CDP operations:', err);
    } finally {
      ws.close();
      chromeProc.kill();
      console.log('Chrome closed.');
    }
  });
}

main().catch(console.error);

