import fs from 'fs';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || "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";

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const data = await res.json();
  return data.access_token;
}

async function uploadAsset(token, themeId, key, content) {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${themeId}/assets.json`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', 'X-Shopify-Access-Token': token },
    body: JSON.stringify({ asset: { key, value: content } })
  });
  return res.ok;
}

async function main() {
  const token = await getAccessToken();
  const themeRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes.json`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const { themes } = await themeRes.json();

  const lushrootMain = fs.readFileSync('sections/babiguard-pdp-lushroot.liquid', 'utf8');
  const lushrootBody = fs.readFileSync('sections/zavelyn-babiguard-body.liquid', 'utf8');
  const templateContent = fs.readFileSync('templates/product.babiguard.json', 'utf8');

  for (const t of themes) {
    console.log(`\nDeploying to theme ${t.id} (${t.name} [${t.role}])...`);
    const s1 = await uploadAsset(token, t.id, 'sections/babiguard-pdp-lushroot.liquid', lushrootMain);
    const s2 = await uploadAsset(token, t.id, 'sections/zavelyn-babiguard-body.liquid', lushrootBody);
    const s3 = await uploadAsset(token, t.id, 'templates/product.babiguard.json', templateContent);
    console.log(`  s1: ${s1 ? '✔' : '❌'}, s2: ${s2 ? '✔' : '❌'}, template: ${s3 ? '✔' : '❌'}`);
    await new Promise(r => setTimeout(r, 300));
  }

  console.log('\n🎉 Finished syncing to ALL themes!');
}

main().catch(console.error);

