import { spawn } from 'child_process';
import fs from 'fs';

const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const tempDir = 'C:\\Users\\Admin\\AppData\\Local\\Temp\\chrome_cdp_mobile';

if (!fs.existsSync(tempDir)) {
  fs.mkdirSync(tempDir, { recursive: true });
}

const chromeProc = spawn(chromePath, [
  '--headless=new',
  '--remote-debugging-port=9223',
  `--user-data-dir=${tempDir}`,
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check'
], { detached: false });

async function main() {
  await new Promise(r => setTimeout(r, 2000));

  let tabs;
  for (let i = 0; i < 5; i++) {
    try {
      const res = await fetch('http://127.0.0.1:9223/json');
      tabs = await res.json();
      break;
    } catch (e) {
      await new Promise(r => setTimeout(r, 1000));
    }
  }

  if (!tabs || tabs.length === 0) {
    console.error('No tabs found!');
    chromeProc.kill();
    return;
  }

  const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);
  let id = 1;
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const curId = id++;
      const handler = (evt) => {
        const msg = JSON.parse(evt.data.toString());
        if (msg.id === curId) {
          ws.removeEventListener('message', handler);
          if (msg.error) reject(msg.error);
          else resolve(msg.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id: curId, method, params }));
    });
  }

  ws.addEventListener('open', async () => {
    try {
      await send('Page.enable');
      await send('DOM.enable');

      // 1. Mobile Capture (iPhone 14/15: 390 x 844)
      console.log('Testing Mobile Viewport (390x844)...');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 390,
        height: 1200,
        deviceScaleFactor: 2,
        mobile: true
      });
      await send('Emulation.setUserAgentOverride', {
        userAgent: 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.6 Mobile/15E148 Safari/604.1'
      });

      await send('Page.navigate', { url: 'https://tryzavelyn.com/products/babiguard-head-protector?v=mobile_test' });
      await new Promise(r => setTimeout(r, 4000));

      const ssMob = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/babiguard_mobile.png', Buffer.from(ssMob.data, 'base64'));
      console.log('Saved scratch/babiguard_mobile.png');

      // Check horizontal overflow on mobile
      const scrollEval = await send('Runtime.evaluate', {
        expression: `({
          scrollWidth: document.documentElement.scrollWidth,
          clientWidth: document.documentElement.clientWidth,
          hasHorizontalScroll: document.documentElement.scrollWidth > document.documentElement.clientWidth
        })`,
        returnByValue: true
      });
      console.log('Mobile scroll metrics:', scrollEval.result.value);

      // 2. Desktop Capture (1440 x 1200)
      console.log('Testing Desktop Viewport (1440x1200)...');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 1440,
        height: 1200,
        deviceScaleFactor: 1,
        mobile: false
      });
      await send('Emulation.setUserAgentOverride', {
        userAgent: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36'
      });
      await new Promise(r => setTimeout(r, 1000));

      const ssDesk = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/babiguard_desktop_1440.png', Buffer.from(ssDesk.data, 'base64'));
      console.log('Saved scratch/babiguard_desktop_1440.png');

    } catch (err) {
      console.error('Error during test:', err);
    } finally {
      ws.close();
      chromeProc.kill();
      console.log('Chrome closed.');
    }
  });
}

main().catch(console.error);

import { spawn } from 'child_process';
import fs from 'fs';

const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const tempDir = 'C:\\Users\\Admin\\AppData\\Local\\Temp\\chrome_cdp_debug';

if (!fs.existsSync(tempDir)) {
  fs.mkdirSync(tempDir, { recursive: true });
}

const chromeProc = spawn(chromePath, [
  '--headless=new',
  '--remote-debugging-port=9224',
  `--user-data-dir=${tempDir}`,
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check'
], { detached: false });

async function main() {
  await new Promise(r => setTimeout(r, 2000));
  const res = await fetch('http://127.0.0.1:9224/json');
  const tabs = await res.json();
  const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);
  let id = 1;
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const curId = id++;
      const handler = (evt) => {
        const msg = JSON.parse(evt.data.toString());
        if (msg.id === curId) {
          ws.removeEventListener('message', handler);
          if (msg.error) reject(msg.error);
          else resolve(msg.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id: curId, method, params }));
    });
  }

  ws.addEventListener('open', async () => {
    try {
      await send('Page.enable');
      await send('DOM.enable');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 1440,
        height: 1200,
        deviceScaleFactor: 1,
        mobile: false
      });
      await send('Page.navigate', { url: 'https://tryzavelyn.com/products/babiguard-head-protector' });
      await new Promise(r => setTimeout(r, 4000));

      const debugInfo = await send('Runtime.evaluate', {
        expression: `(function() {
          const wrapper = document.querySelector('.lr-pdp-wrapper');
          const container = document.querySelector('.lr-container');
          const grid = document.querySelector('.lr-grid');
          const gallery = document.querySelector('.lr-gallery-wrap');
          const buybox = document.querySelector('.lr-buybox');
          const mainImgBox = document.querySelector('.lr-main-img-box');
          const mainImg = document.querySelector('.lr-main-img');

          return {
            wrapperWidth: wrapper ? wrapper.offsetWidth : null,
            containerWidth: container ? container.offsetWidth : null,
            containerMaxWidth: container ? getComputedStyle(container).maxWidth : null,
            gridWidth: grid ? grid.offsetWidth : null,
            gridComputedCols: grid ? getComputedStyle(grid).gridTemplateColumns : null,
            galleryWidth: gallery ? gallery.offsetWidth : null,
            mainImgBoxWidth: mainImgBox ? mainImgBox.offsetWidth : null,
            mainImgWidth: mainImg ? mainImg.offsetWidth : null,
            mainImgNaturalWidth: mainImg ? mainImg.naturalWidth : null,
            buyboxWidth: buybox ? buybox.offsetWidth : null,
            parentOfWrapper: wrapper && wrapper.parentElement ? {
              tag: wrapper.parentElement.tagName,
              className: wrapper.parentElement.className,
              offsetWidth: wrapper.parentElement.offsetWidth,
              display: getComputedStyle(wrapper.parentElement).display,
              flex: getComputedStyle(wrapper.parentElement).flex
            } : null
          };
        })()`,
        returnByValue: true
      });

      console.log('DEBUG INFO:', JSON.stringify(debugInfo.result.value, null, 2));

    } catch (err) {
      console.error(err);
    } finally {
      ws.close();
      chromeProc.kill();
    }
  });
}

main().catch(console.error);

