import { spawn } from 'child_process';
import fs from 'fs';

const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const tempDir = 'C:\\Users\\Admin\\AppData\\Local\\Temp\\chrome_cdp_verify';

if (!fs.existsSync(tempDir)) {
  fs.mkdirSync(tempDir, { recursive: true });
}

const chromeProc = spawn(chromePath, [
  '--headless=new',
  '--remote-debugging-port=9225',
  `--user-data-dir=${tempDir}`,
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check'
], { detached: false });

async function main() {
  await new Promise(r => setTimeout(r, 2000));
  const res = await fetch('http://127.0.0.1:9225/json');
  const tabs = await res.json();
  const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);
  let id = 1;

  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const curId = id++;
      const handler = (evt) => {
        const msg = JSON.parse(evt.data.toString());
        if (msg.id === curId) {
          ws.removeEventListener('message', handler);
          if (msg.error) reject(msg.error);
          else resolve(msg.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id: curId, method, params }));
    });
  }

  ws.addEventListener('open', async () => {
    try {
      await send('Page.enable');
      await send('DOM.enable');

      // 1. Desktop Screenshot (1300 x 1200)
      console.log('Capturing Desktop...');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 1300,
        height: 1100,
        deviceScaleFactor: 1,
        mobile: false
      });
      await send('Page.navigate', { url: 'https://tryzavelyn.com/products/babiguard-head-protector?nocache=' + Date.now() });
      await new Promise(r => setTimeout(r, 4500));

      const deskShot = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/desktop_fixed.png', Buffer.from(deskShot.data, 'base64'));
      console.log('Saved scratch/desktop_fixed.png');

      // 2. Mobile Screenshot (390 x 844)
      console.log('Capturing Mobile...');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 390,
        height: 844,
        deviceScaleFactor: 2,
        mobile: true
      });
      await new Promise(r => setTimeout(r, 2000));

      const mobShot = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/mobile_fixed.png', Buffer.from(mobShot.data, 'base64'));
      console.log('Saved scratch/mobile_fixed.png');

    } catch (err) {
      console.error('Error during capture:', err);
    } finally {
      ws.close();
      chromeProc.kill();
      console.log('Done.');
    }
  });
}

main().catch(console.error);

