import fs from 'fs';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || "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";

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      client_id: CLIENT_ID,
      client_secret: CLIENT_SECRET,
      grant_type: 'client_credentials'
    })
  });
  const data = await res.json();
  return data.access_token;
}

async function uploadLocalFile(token, filePath, filename, alt) {
  const buffer = fs.readFileSync(filePath);
  const stagedQuery = `
    mutation stagedUploadsCreate($input: [StagedUploadInput!]!) {
      stagedUploadsCreate(input: $input) {
        stagedTargets {
          url
          resourceUrl
          parameters {
            name
            value
          }
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  const stagedRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2025-01/graphql.json`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      query: stagedQuery,
      variables: {
        input: [
          {
            filename,
            mimeType: 'image/png',
            resource: 'IMAGE',
            fileSize: buffer.byteLength.toString(),
            httpMethod: 'POST'
          }
        ]
      }
    })
  });

  const stagedData = await stagedRes.json();
  const target = stagedData.data?.stagedUploadsCreate?.stagedTargets?.[0];
  if (!target) {
    console.error('Failed staged upload:', JSON.stringify(stagedData));
    return null;
  }

  const formData = new FormData();
  target.parameters.forEach(p => formData.append(p.name, p.value));
  formData.append('file', new Blob([buffer], { type: 'image/png' }), filename);

  const s3Res = await fetch(target.url, {
    method: 'POST',
    body: formData
  });

  const createQuery = `
    mutation fileCreate($files: [FileCreateInput!]!) {
      fileCreate(files: $files) {
        files {
          id
          fileStatus
          alt
          ... on MediaImage {
            image {
              url
            }
          }
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  const createRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2025-01/graphql.json`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      query: createQuery,
      variables: {
        files: [
          {
            alt,
            contentType: 'IMAGE',
            originalSource: target.resourceUrl
          }
        ]
      }
    })
  });

  const createData = await createRes.json();
  const fileId = createData.data?.fileCreate?.files?.[0]?.id;
  console.log(`Uploaded ${filename}, File ID: ${fileId}`);

  // Poll for ready URL
  for (let i = 0; i < 10; i++) {
    await new Promise(r => setTimeout(r, 1000));
    const pollQuery = `
      query getFile($id: ID!) {
        node(id: $id) {
          ... on MediaImage {
            image {
              url
            }
          }
        }
      }
    `;
    const pollRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2025-01/graphql.json`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Shopify-Access-Token': token
      },
      body: JSON.stringify({ query: pollQuery, variables: { id: fileId } })
    });
    const pollData = await pollRes.json();
    const url = pollData.data?.node?.image?.url;
    if (url) {
      console.log(`Ready URL for ${filename}:`, url);
      return url;
    }
  }

  return target.resourceUrl;
}

async function main() {
  const token = await getAccessToken();
  const hatUrl = await uploadLocalFile(token, 'scratch/thumb_knit_hat.png', 'baby-dino-knit-hat.png', 'Baby Dino Knit Hat');
  const nasalUrl = await uploadLocalFile(token, 'scratch/thumb_nasal_spray.png', 'baby-nasal-spray.png', 'Baby Nasal Spray');

  const result = { hatUrl, nasalUrl };
  fs.writeFileSync('scratch/uploaded_bundle_gifts.json', JSON.stringify(result, null, 2));
  console.log('Result:', result);
}

main().catch(console.error);

