import { spawn } from 'child_process';
import fs from 'fs';

const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const tempDir = 'C:\\Users\\Admin\\AppData\\Local\\Temp\\chrome_cdp_shot_' + Date.now();

fs.mkdirSync(tempDir, { recursive: true });

console.log('Launching headless Chrome...');
const chromeProc = spawn(chromePath, [
  '--headless=new',
  '--remote-debugging-port=9226',
  `--user-data-dir=${tempDir}`,
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check'
], { detached: false });

async function main() {
  await new Promise(r => setTimeout(r, 2000));

  let tabs;
  for (let i = 0; i < 6; i++) {
    try {
      const res = await fetch('http://127.0.0.1:9226/json');
      tabs = await res.json();
      break;
    } catch (e) {
      await new Promise(r => setTimeout(r, 800));
    }
  }

  if (!tabs || tabs.length === 0) {
    console.error('No tabs found!');
    chromeProc.kill();
    return;
  }

  console.log('Found tab:', tabs[0].id);

  const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);
  let id = 1;
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const curId = id++;
      const timer = setTimeout(() => {
        ws.removeEventListener('message', handler);
        reject(new Error(`Timeout on ${method}`));
      }, 10000);

      const handler = (evt) => {
        const msg = JSON.parse(evt.data.toString());
        if (msg.id === curId) {
          clearTimeout(timer);
          ws.removeEventListener('message', handler);
          if (msg.error) reject(msg.error);
          else resolve(msg.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id: curId, method, params }));
    });
  }

  ws.addEventListener('open', async () => {
    try {
      console.log('Enabling Page & DOM...');
      await send('Page.enable');
      await send('DOM.enable');

      // 1. Desktop Screenshot
      console.log('Setting Desktop viewport...');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 1280,
        height: 1200,
        deviceScaleFactor: 1,
        mobile: false
      });

      console.log('Navigating to product page...');
      await send('Page.navigate', { url: 'https://tryzavelyn.com/products/babiguard-head-protector' });
      await new Promise(r => setTimeout(r, 4500));

      console.log('Capturing Desktop screenshot...');
      const ssDesktop = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/bundle_new_desktop.png', Buffer.from(ssDesktop.data, 'base64'));
      console.log('Saved scratch/bundle_new_desktop.png');

      // 2. Mobile Screenshot
      console.log('Setting Mobile viewport...');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 390,
        height: 844,
        deviceScaleFactor: 2,
        mobile: true
      });
      await new Promise(r => setTimeout(r, 1500));

      // Scroll to bundle
      await send('Runtime.evaluate', { expression: 'window.scrollTo(0, 500)' });
      await new Promise(r => setTimeout(r, 1000));

      console.log('Capturing Mobile screenshot...');
      const ssMobile = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/bundle_new_mobile.png', Buffer.from(ssMobile.data, 'base64'));
      console.log('Saved scratch/bundle_new_mobile.png');

    } catch (err) {
      console.error('Error during CDP operations:', err);
    } finally {
      ws.close();
      chromeProc.kill();
      console.log('Chrome closed.');
    }
  });
}

main().catch(console.error);

