const fs = require('fs');
const http = require('http');

async function main() {
  const versionData = await new Promise((resolve, reject) => {
    http.get('http://127.0.0.1:9222/json/version', res => {
      let data = ''; res.on('data', c => data += c); res.on('end', () => resolve(JSON.parse(data)));
    }).on('error', reject);
  });
  const ws = new (require('ws'))(versionData.webSocketDebuggerUrl);
  await new Promise(r => ws.on('open', r));
  let id = 1;
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const curId = id++;
    const handler = msg => {
      const resp = JSON.parse(msg);
      if (resp.id === curId) {
        ws.off('message', handler);
        if (resp.error) reject(resp.error);
        else resolve(resp.result);
      }
    };
    ws.on('message', handler);
    ws.send(JSON.stringify({ id: curId, method, params }));
  });

  const { targetId } = await send('Target.createTarget', { url: 'https://tryzavelyn.com/products/babiguard-head-protector' });
  const { sessionId } = await send('Target.attachToTarget', { targetId, flatten: true });
  const sendSession = (method, params = {}) => send(method, { ...params, sessionId });

  await sendSession('Page.enable');
  await sendSession('Emulation.setDeviceMetricsOverride', {
    width: 1280, height: 900, deviceScaleFactor: 1.5, mobile: false
  });

  await new Promise(r => setTimeout(r, 2500));

  // Scroll to bundle
  await sendSession('Runtime.evaluate', {
    expression: 'window.scrollTo(0, 450);'
  });
  await new Promise(r => setTimeout(r, 600));

  let shot = await sendSession('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync('scratch/bundle_desktop_scrolled.png', Buffer.from(shot.data, 'base64'));

  // Scroll down to check if specifications is gone
  await sendSession('Runtime.evaluate', {
    expression: 'window.scrollTo(0, 1800);'
  });
  await new Promise(r => setTimeout(r, 600));
  shot = await sendSession('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync('scratch/body_scrolled_1800.png', Buffer.from(shot.data, 'base64'));

  // Mobile scrolled
  await sendSession('Emulation.setDeviceMetricsOverride', {
    width: 390, height: 844, deviceScaleFactor: 2, mobile: true
  });
  await sendSession('Runtime.evaluate', {
    expression: 'window.scrollTo(0, 850);'
  });
  await new Promise(r => setTimeout(r, 600));
  shot = await sendSession('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync('scratch/mobile_scrolled_850.png', Buffer.from(shot.data, 'base64'));

  await send('Target.closeTarget', { targetId });
  ws.close();
  console.log('Screenshots captured successfully!');
}
main().catch(console.error);
"

