import('child_process').then(({ spawn }) => {
  const fs = require('fs');
  const chromePath = 'C:\\\\Program Files\\\\Google\\\\Chrome\\\\Application\\\\chrome.exe';
  const tempDir = 'C:\\\\Users\\\\Admin\\\\AppData\\\\Local\\\\Temp\\\\chrome_cdp_test';
  const chromeProc = spawn(chromePath, [
    '--headless=new',
    '--remote-debugging-port=9222',
    \`--user-data-dir=\${tempDir}\`,
    '--disable-gpu',
    '--no-first-run',
    '--no-default-browser-check'
  ]);

  setTimeout(async () => {
    try {
      const res = await fetch('http://127.0.0.1:9222/json');
      const tabs = await res.json();
      const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);
      let id = 1;
      function send(method, params = {}) {
        return new Promise((resolve, reject) => {
          const curId = id++;
          const handler = (evt) => {
            const msg = JSON.parse(evt.data.toString());
            if (msg.id === curId) {
              ws.removeEventListener('message', handler);
              if (msg.error) reject(msg.error);
              else resolve(msg.result);
            }
          };
          ws.addEventListener('message', handler);
          ws.send(JSON.stringify({ id: curId, method, params }));
        });
      }

      ws.addEventListener('open', async () => {
        await send('Page.enable');
        await send('Emulation.setDeviceMetricsOverride', {
          width: 390,
          height: 844,
          deviceScaleFactor: 2,
          mobile: true
        });
        await send('Page.navigate', { url: 'https://tryzavelyn.com/products/babiguard-head-protector' });
        await new Promise(r => setTimeout(r, 4500));
        // Scroll to order bump and cta on mobile
        await send('Runtime.evaluate', { expression: 'window.scrollTo(0, 1600)' });
        await new Promise(r => setTimeout(r, 800));
        const shot = await send('Page.captureScreenshot', { format: 'png' });
        fs.writeFileSync('scratch/mobile_bottom_check.png', Buffer.from(shot.data, 'base64'));
        console.log('Saved mobile_bottom_check.png');
        ws.close();
        chromeProc.kill();
      });
    } catch (e) {
      console.error(e);
      chromeProc.kill();
    }
  }, 2000);
});
"

