import fs from 'fs';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || "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";

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      client_id: CLIENT_ID,
      client_secret: CLIENT_SECRET,
      grant_type: 'client_credentials'
    })
  });
  const data = await res.json();
  return data.access_token;
}

async function uploadLocalFile(token, filePath, filename, alt) {
  const buffer = fs.readFileSync(filePath);
  const stagedQuery = `
    mutation stagedUploadsCreate($input: [StagedUploadInput!]!) {
      stagedUploadsCreate(input: $input) {
        stagedTargets {
          url
          resourceUrl
          parameters {
            name
            value
          }
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  const stagedRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2025-01/graphql.json`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      query: stagedQuery,
      variables: {
        input: [{
          resource: "IMAGE",
          filename,
          mimeType: filename.endsWith('.jpg') ? 'image/jpeg' : (filename.endsWith('.gif') ? 'image/gif' : 'image/png'),
          fileSize: buffer.length.toString(),
          httpMethod: "POST"
        }]
      }
    })
  });

  const stagedData = await stagedRes.json();
  const target = stagedData.data.stagedUploadsCreate.stagedTargets[0];

  const formData = new FormData();
  target.parameters.forEach(param => {
    formData.append(param.name, param.value);
  });
  formData.append('file', new Blob([buffer]));

  const uploadRes = await fetch(target.url, {
    method: 'POST',
    body: formData
  });

  if (!uploadRes.ok && uploadRes.status !== 201 && uploadRes.status !== 204) {
    throw new Error(`Upload to staged target failed with status ${uploadRes.status}`);
  }

  const fileCreateQuery = `
    mutation fileCreate($files: [FileCreateInput!]!) {
      fileCreate(files: $files) {
        files {
          id
          fileStatus
          alt
          ... on GenericFile { url }
          ... on MediaImage {
            image {
              url
            }
          }
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  const fileCreateRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2025-01/graphql.json`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      query: fileCreateQuery,
      variables: {
        files: [{
          alt,
          contentType: "IMAGE",
          originalSource: target.resourceUrl
        }]
      }
    })
  });

  const fileCreateData = await fileCreateRes.json();
  const file = fileCreateData.data.fileCreate.files[0];
  console.log(`Created file ${filename}: ID=${file.id}, Status=${file.fileStatus}`);
  return file.id;
}

async function queryFileUrl(token, fileId) {
  const query = `
    query getFile($id: ID!) {
      node(id: $id) {
        ... on MediaImage {
          image {
            url
          }
        }
      }
    }
  `;
  for (let i = 0; i < 15; i++) {
    const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2025-01/graphql.json`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Shopify-Access-Token': token
      },
      body: JSON.stringify({
        query,
        variables: { id: fileId }
      })
    });
    const data = await res.json();
    const url = data.data?.node?.image?.url;
    if (url) return url;
    await new Promise(r => setTimeout(r, 1200));
  }
  return null;
}

async function main() {
  const token = await getAccessToken();
  const filesToUpload = [
    { path: 'assets/zavelyn-bundle-1.png', name: 'zavelyn-bundle-1.png', alt: '1 Zavelyn Rehabilitation Glove' },
    { path: 'assets/zavelyn-bundle-2.png', name: 'zavelyn-bundle-2.png', alt: '2 Zavelyn Rehabilitation Gloves' },
    { path: 'assets/zavelyn-upsell-heat.png', name: 'zavelyn-upsell-heat.png', alt: 'Zavelyn Heated Wrist Therapy Wrap' },
    { path: 'assets/zavelyn-size-chart.png', name: 'zavelyn-size-chart.png', alt: 'Zavelyn Glove Sizing Guide Chart' }
  ];

  const results = {};
  for (const item of filesToUpload) {
    if (fs.existsSync(item.path)) {
      console.log(`Uploading ${item.name}...`);
      const fileId = await uploadLocalFile(token, item.path, item.name, item.alt);
      const url = await queryFileUrl(token, fileId);
      console.log(`URL for ${item.name}: ${url}`);
      results[item.name] = url;
    }
  }

  fs.writeFileSync('scratch/uploaded_rehab_images.json', JSON.stringify(results, null, 2));
  console.log('Finished uploading all images!');
}

main().catch(console.error);

