import fs from 'fs';

async function fetchPage() {
  const url = 'https://houdiniholsters.com/products/breakout-2-0-holster-built-for-maximum-concealment-copy';
  const res = await fetch(url, {
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8',
      'Accept-Language': 'en-US,en;q=0.9'
    }
  });

  console.log('HTML Status:', res.status);
  const html = await res.text();
  fs.writeFileSync('scratch/houdini_pdp.html', html);
  console.log('Saved scratch/houdini_pdp.html, length:', html.length);

  // Check theme
  const themeMatch = html.match(/Shopify\.theme\s*=\s*({[^}]+})/);
  if (themeMatch) console.log('Shopify.theme:', themeMatch[1]);

  // Check review apps (judgeme, loox, yotpo, stamped, okendo)
  console.log('Has Loox?', html.includes('loox'));
  console.log('Has Judge.me?', html.includes('judge.me') || html.includes('jdgm'));
  console.log('Has Okendo?', html.includes('okendo'));
  console.log('Has Yotpo?', html.includes('yotpo'));

  // Check bundle apps
  console.log('Has Kaching?', html.includes('kaching'));
  console.log('Has WideBundle?', html.includes('widebundle') || html.includes('wide-bundle'));
  console.log('Has FastBundle?', html.includes('fastbundle'));
}

fetchPage().catch(console.error);

import { spawn } from 'child_process';
import fs from 'fs';

const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const tempDir = 'C:\\Users\\Admin\\AppData\\Local\\Temp\\chrome_cdp_test';

const chromeProc = spawn(chromePath, [
  '--headless=new',
  '--remote-debugging-port=9222',
  `--user-data-dir=${tempDir}`,
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check'
], { detached: false });

async function main() {
  await new Promise(r => setTimeout(r, 2000));

  let tabs;
  for (let i = 0; i < 5; i++) {
    try {
      const res = await fetch('http://127.0.0.1:9222/json');
      tabs = await res.json();
      break;
    } catch (e) {
      await new Promise(r => setTimeout(r, 1000));
    }
  }

  if (!tabs || tabs.length === 0) {
    chromeProc.kill();
    return;
  }

  const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);
  let id = 1;
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const curId = id++;
      const handler = (evt) => {
        const msg = JSON.parse(evt.data.toString());
        if (msg.id === curId) {
          ws.removeEventListener('message', handler);
          if (msg.error) reject(msg.error);
          else resolve(msg.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id: curId, method, params }));
    });
  }

  ws.addEventListener('open', async () => {
    try {
      console.log('Navigating to Houdini Holster...');
      await send('Page.enable');

      // 1. Desktop
      await send('Emulation.setDeviceMetricsOverride', {
        width: 1280,
        height: 1200,
        deviceScaleFactor: 1,
        mobile: false
      });

      await send('Page.navigate', { url: 'https://houdiniholsters.com/products/breakout-2-0-holster-built-for-maximum-concealment-copy' });
      await new Promise(r => setTimeout(r, 5000));

      console.log('Capturing Desktop screenshot...');
      const ssDesktop = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/houdini_desktop.png', Buffer.from(ssDesktop.data, 'base64'));
      console.log('Saved scratch/houdini_desktop.png');

      // Scroll to buy box / middle
      await send('Runtime.evaluate', { expression: 'window.scrollTo(0, 700)' });
      await new Promise(r => setTimeout(r, 1000));
      const ssScrolled = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/houdini_desktop_scrolled.png', Buffer.from(ssScrolled.data, 'base64'));

      // 2. Mobile
      console.log('Emulating Mobile (390x844)...');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 390,
        height: 844,
        deviceScaleFactor: 2,
        mobile: true
