import { spawn } from 'child_process';

const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const tempDir = 'C:\\Users\\Admin\\AppData\\Local\\Temp\\chrome_cdp_test';

const chromeProc = spawn(chromePath, [
  '--headless=new',
  '--remote-debugging-port=9222',
  `--user-data-dir=${tempDir}`,
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check'
], { detached: false });

async function main() {
  await new Promise(r => setTimeout(r, 2000));
  const res = await fetch('http://127.0.0.1:9222/json');
  const tabs = await res.json();
  const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);

  let id = 1;
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const curId = id++;
      const handler = (evt) => {
        const msg = JSON.parse(evt.data.toString());
        if (msg.id === curId) {
          ws.removeEventListener('message', handler);
          if (msg.error) reject(msg.error);
          else resolve(msg.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id: curId, method, params }));
    });
  }

  ws.addEventListener('open', async () => {
    try {
      await send('Page.enable');
      await send('Page.navigate', { url: 'https://houdiniholsters.com/products/breakout-2-0-holster-built-for-maximum-concealment-copy' });
      await new Promise(r => setTimeout(r, 6000));

      const evalRes = await send('Runtime.evaluate', {
        expression: `
          (() => {
            const selects = Array.from(document.querySelectorAll('select'));
            const selectData = selects.map(s => {
              const label = s.closest('.gpo-element, .gpo-option, div')?.querySelector('label, .gpo-label')?.innerText || '';
              const opts = Array.from(s.options).map(o => o.text.trim());
              return { label, options: opts };
            });

            const labels = Array.from(document.querySelectorAll('.gpo-label, .gpo-element-label, label')).map(l => l.innerText.trim());

            return {
              selectData,
              labels: labels.filter(Boolean),
              gpoConfigs: typeof window.GPOConfigs !== 'undefined' ? Object.keys(window.GPOConfigs) : null
            };
          })()
        `,
        returnByValue: true
      });

      console.log('DOM Evaluation Result:');
      console.log(JSON.stringify(evalRes.result.value, null, 2));

    } catch (e) {
      console.error(e);
    } finally {
      ws.close();
      chromeProc.kill();
    }
  });
}

main().catch(console.error);

