import { spawn } from 'child_process';
import fs from 'fs';

const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const tempDir = 'C:\\Users\\Admin\\AppData\\Local\\Temp\\chrome_cdp_houdini';
if (!fs.existsSync(tempDir)) fs.mkdirSync(tempDir, { recursive: true });

const chromeProc = spawn(chromePath, [
  '--headless=new',
  '--remote-debugging-port=9225',
  `--user-data-dir=${tempDir}`,
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check'
], { detached: false });

async function main() {
  await new Promise(r => setTimeout(r, 2000));
  const res = await fetch('http://127.0.0.1:9225/json');
  const tabs = await res.json();
  const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);
  let id = 1;
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const curId = id++;
    const handler = (evt) => {
      const msg = JSON.parse(evt.data.toString());
      if (msg.id === curId) {
        ws.removeEventListener('message', handler);
        if (msg.error) reject(msg.error);
        else resolve(msg.result);
      }
    };
    ws.addEventListener('message', handler);
    ws.send(JSON.stringify({ id: curId, method, params }));
  });

  ws.addEventListener('open', async () => {
    try {
      await send('Page.enable');
      await send('DOM.enable');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 1280,
        height: 1600,
        deviceScaleFactor: 1,
        mobile: false
      });

      console.log('Navigating to Houdini Holsters...');
      await send('Page.navigate', { url: 'https://houdiniholsters.com/products/breakout-2-0-holster-built-for-maximum-concealment-copy' });
      await new Promise(r => setTimeout(r, 7000)); // wait for Globo Product Options to load

      // Extract all form options
      const evalRes = await send('Runtime.evaluate', {
        expression: `(() => {
          const form = document.querySelector('form[action*="/cart/add"]') || document.querySelector('.product-form') || document.body;

          // Get all option containers
          const optionElements = [];
          document.querySelectorAll('.gpo-container, .globo-form-control, [class*="option"], [class*="variant"], .product-form__input').forEach(el => {
            const label = el.querySelector('label, .header, .title')?.innerText?.trim();
            const text = el.innerText?.trim();
            if (label || text) {
              optionElements.push({ tag: el.tagName, class: el.className, label, text: text?.slice(0, 200) });
            }
          });

          // Also get all inputs/selects inside product area
          const inputs = [];
          document.querySelectorAll('form select, form input, .gpo-container select, .gpo-container input').forEach(inp => {
            inputs.push({
              name: inp.name,
              type: inp.type,
              value: inp.value,
              placeholder: inp.placeholder,
              checked: inp.checked,
              optionsCount: inp.options ? inp.options.length : 0
            });
          });

          // Also capture all headings & section texts in the body
          const bodySections = [];
          document.querySelectorAll('h1, h2, h3, h4').forEach(h => {
            bodySections.push({ tag: h.tagName, text: h.innerText?.trim() });
          });

          return { optionElements: optionElements.slice(0, 30), inputs, bodySections };
        })()`,
        returnByValue: true
      });

      fs.writeFileSync('scratch/houdini_live_dom_info.json', JSON.stringify(evalRes.result.value, null, 2));
      console.log('Saved scratch/houdini_live_dom_info.json');

      // Take desktop screenshot of buybox and body
      const ss = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/houdini_full_desktop.png', Buffer.from(ss.data, 'base64'));
      console.log('Saved scratch/houdini_full_desktop.png');

      // Scroll to body section and take screenshot
      await send('Runtime.evaluate', { expression: 'window.scrollTo(0, 1800)' });
      await new Promise(r => setTimeout(r, 1000));
      const ssBody = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/houdini_body_desktop.png', Buffer.from(ssBody.data, 'base64'));
      console.log('Saved scratch/houdini_body_desktop.png');

    } catch (e) {
      console.error('Error:', e);
    } finally {
      ws.close();
      chromeProc.kill();
    }
  });
}
main().catch(console.error);

