import fs from 'fs';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || "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";

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      client_id: CLIENT_ID,
      client_secret: CLIENT_SECRET,
      grant_type: 'client_credentials'
    })
  });
  const data = await res.json();
  return data.access_token;
}

async function uploadLocalFile(token, filePath, filename, alt) {
  const buffer = fs.readFileSync(filePath);
  const stagedQuery = `
    mutation stagedUploadsCreate($input: [StagedUploadInput!]!) {
      stagedUploadsCreate(input: $input) {
        stagedTargets {
          url
          resourceUrl
          parameters {
            name
            value
          }
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  const stagedRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2025-01/graphql.json`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      query: stagedQuery,
      variables: {
        input: [
          {
            filename,
            mimeType: 'image/webp',
            resource: 'IMAGE',
            fileSize: buffer.byteLength.toString(),
            httpMethod: 'POST'
          }
        ]
      }
    })
  });

  const stagedData = await stagedRes.json();
  const target = stagedData.data?.stagedUploadsCreate?.stagedTargets?.[0];
  if (!target) {
    console.error('Failed staged upload:', JSON.stringify(stagedData));
    return null;
  }

  const formData = new FormData();
  target.parameters.forEach(p => formData.append(p.name, p.value));
  formData.append('file', new Blob([buffer], { type: 'image/webp' }), filename);

  const uploadRes = await fetch(target.url, { method: 'POST', body: formData });
  if (!uploadRes.ok) {
    console.error('Failed upload to target URL:', uploadRes.statusText);
    return null;
  }

  const createQuery = `
    mutation fileCreate($files: [FileCreateInput!]!) {
      fileCreate(files: $files) {
        files {
          id
          fileStatus
          alt
          ... on MediaImage {
            image {
              url
            }
          }
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  const createRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2025-01/graphql.json`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      query: createQuery,
      variables: {
        files: [
          {
            originalSource: target.resourceUrl,
            alt: alt
          }
        ]
      }
    })
  });

  const createData = await createRes.json();
  const fileId = createData.data?.fileCreate?.files?.[0]?.id;
  console.log(`Uploaded ${filename} -> File ID: ${fileId}`);
  return fileId;
}

async function queryFileUrl(token, fileId) {
  const query = `
    query getFile($id: ID!) {
      node(id: $id) {
        ... on MediaImage {
          image {
            url
          }
        }
      }
    }
  `;

  for (let i = 0; i < 10; i++) {
    await new Promise(r => setTimeout(r, 1500));
    const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2025-01/graphql.json`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Shopify-Access-Token': token
      },
      body: JSON.stringify({ query, variables: { id: fileId } })
    });
    const data = await res.json();
    const url = data.data?.node?.image?.url;
    if (url) return url;
  }
  return null;
}

async function main() {
  const token = await getAccessToken();
  console.log('Got access token');

  const items = JSON.parse(fs.readFileSync('scratch/breakthrough_items.json', 'utf8'));
  const uploaded = [];

  for (let i = 0; i < items.length; i++) {
    const filePath = `scratch/breakthrough_imgs/item_${i + 1}.webp`;
    const filename = `bh-breakthrough-${i + 1}.webp`;
    const alt = items[i].title;

    console.log(`Uploading ${filename}...`);
    const fileId = await uploadLocalFile(token, filePath, filename, alt);
    if (fileId) {
      const cdnUrl = await queryFileUrl(token, fileId);
      console.log(`CDN URL for ${items[i].title}: ${cdnUrl}`);
      uploaded.push({
        ...items[i],
        cdnUrl: cdnUrl || items[i].image
      });
    } else {
      uploaded.push(items[i]);
    }
  }

  fs.writeFileSync('scratch/uploaded_breakthrough.json', JSON.stringify(uploaded, null, 2));
  console.log('Saved scratch/uploaded_breakthrough.json');
}

main().catch(console.error);

