import fs from 'fs';

// 1. Load Gun Models
const data = JSON.parse(fs.readFileSync('scratch/houdini_options.json', 'utf8'));
const gun1List = data.selectData[0].options;
const gun2List = data.selectData[1].options;

console.log('Gun 1 list size:', gun1List.length);
console.log('Gun 2 list size:', gun2List.length);

// Generate options HTML for Gun 1
const gun1OptionsHtml = gun1List.map(item => {
  const isSelected = item === 'Glock 19-19X-45-23-32' ? ' selected' : '';
  const val = item.replace(/"/g, '&quot;');
  return `              <option value="${val}"${isSelected}>${item}</option>`;
}).join('\n');

// Generate options HTML for Gun 2
const gun2OptionsHtml = gun2List.map(item => {
  const isSelected = item === 'Sig Sauer P365 - P365X - P365 SAS' ? ' selected' : '';
  const val = item.replace(/"/g, '&quot;');
  return `              <option value="${val}"${isSelected}>${item}</option>`;
}).join('\n');

// 2. Read sections/breakout-holster-pdp.liquid
let pdp = fs.readFileSync('sections/breakout-holster-pdp.liquid', 'utf8');

// Replace Gun 1 dropdown options
const gun1SelectRegex = /<select class="bh-dropdown" id="bh-gun-1" aria-label="Gun 1 Model">[\s\S]*?<\/select>/;
const newGun1Select = `<select class="bh-dropdown" id="bh-gun-1" aria-label="Gun 1 Model">\n${gun1OptionsHtml}\n            </select>`;
pdp = pdp.replace(gun1SelectRegex, newGun1Select);

// Replace Gun 2 dropdown options
const gun2SelectRegex = /<select class="bh-dropdown" id="bh-gun-2" aria-label="Gun 2 Model">[\s\S]*?<\/select>/;
const newGun2Select = `<select class="bh-dropdown" id="bh-gun-2" aria-label="Gun 2 Model">\n${gun2OptionsHtml}\n            </select>`;
pdp = pdp.replace(gun2SelectRegex, newGun2Select);

// Update Material Swatches markup
const matSwatchesRegex = /<!-- MATERIAL OPTIONS -->[\s\S]*?<!-- ORDER BUMP -->/;
const newMatSwatches = `<!-- MATERIAL OPTIONS -->
          <div class="bh-material-row">
            <label class="bh-select-label">Material Options *</label>
            <div class="bh-swatches">
              <button type="button" class="bh-swatch-btn active" data-mat="Flat Black" data-price="0">
                <span class="bh-swatch-thumb matte"></span>
                <span class="bh-swatch-name">Flat Black (Included)</span>
              </button>
              <button type="button" class="bh-swatch-btn" data-mat="Carbon Fiber Upgrade" data-price="19.99">
                <span class="bh-swatch-thumb carbon"></span>
                <span class="bh-swatch-name">Carbon Fiber Upgrade (+ $19.99)</span>
              </button>
            </div>
            <input type="hidden" id="bh-material-val" value="Flat Black">
          </div>
        </div>

        <!-- ORDER BUMP -->`;

pdp = pdp.replace(matSwatchesRegex, newMatSwatches);

// Update JS for dynamic price calculation including Carbon Fiber upgrade
const jsTargetRegex = /const updatePrice = \(\) => {[\s\S]*?};/;
const newUpdatePrice = `const updatePrice = () => {
        let total = BASE_PRICE;
        let savings = 100.01;
        let extras = [];

        // Check material
        const activeSwatch = document.querySelector('#Section-{{ section.id }} .bh-swatch-btn.active');
        const matPrice = activeSwatch ? parseFloat(activeSwatch.getAttribute('data-price') || '0') : 0;
        total += matPrice;
        if (matPrice > 0) extras.push('Carbon Fiber Upgrade');

        // Check order bump
        if (bumpCheckbox && bumpCheckbox.checked) {
          total += BUMP_PRICE;
          extras.push('Magnetic Pocket Clip');
        }

        const totalFormatted = '$' + total.toFixed(2);
        if (priceDisplay) priceDisplay.textContent = totalFormatted;
        if (ctaText) ctaText.textContent = 'ADD TO CART – ' + totalFormatted;
        if (mobilePrice) mobilePrice.textContent = totalFormatted;

        if (savingsDisplay) {
          savingsDisplay.textContent = '⇘ 🏷️ You save $' + savings.toFixed(2) + ' on this order + FREE 2nd Holster included ⇙';
        }
      };`;

pdp = pdp.replace(jsTargetRegex, newUpdatePrice);

// Also update swatch click listener in JS
const swatchClickRegex = /swatchBtns\.forEach\(btn => {[\s\S]*?\}\);/;
const newSwatchClick = `swatchBtns.forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.preventDefault();
          swatchBtns.forEach(b => b.classList.remove('active'));
          btn.classList.add('active');
          const mat = btn.getAttribute('data-mat');
          const matInp = document.getElementById('bh-material-val');
          if (matInp) matInp.value = mat;
          updatePrice();
        });
      });`;

pdp = pdp.replace(swatchClickRegex, newSwatchClick);

fs.writeFileSync('sections/breakout-holster-pdp.liquid', pdp, 'utf8');
console.log('Successfully updated sections/breakout-holster-pdp.liquid!');

// 3. Update sections/breakout-holster-body.liquid
let body = fs.readFileSync('sections/breakout-holster-body.liquid', 'utf8');

// Add Breakthrough CSS
const styleEndIdx = body.indexOf('</style>');
const breakthroughCss = `
    /* BREAKTHROUGH DESIGN & UNMATCHED PERFORMANCE */
    #Section-{{ section.id }} .bh-breakthrough-card {
      background: #FFFFFF;
      border: 1px solid var(--bh-border);
      border-radius: 18px;
      padding: 40px 36px;
      margin-bottom: 30px;
