import { spawn } from 'child_process';
import fs from 'fs';

const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const tempDir = 'C:\\Users\\Admin\\AppData\\Local\\Temp\\chrome_cdp_test';

const chromeProc = spawn(chromePath, [
  '--headless=new',
  '--remote-debugging-port=9222',
  `--user-data-dir=${tempDir}`,
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check'
], { detached: false });

async function main() {
  await new Promise(r => setTimeout(r, 1500));
  const res = await fetch('http://127.0.0.1:9222/json');
  const tabs = await res.json();
  const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);
  let id = 1;
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const curId = id++;
    const handler = (evt) => {
      const msg = JSON.parse(evt.data.toString());
      if (msg.id === curId) {
        ws.removeEventListener('message', handler);
        if (msg.error) reject(msg.error);
        else resolve(msg.result);
      }
    };
    ws.addEventListener('message', handler);
    ws.send(JSON.stringify({ id: curId, method, params }));
  });

  ws.addEventListener('open', async () => {
    try {
      await send('Page.enable');

      // 1. Desktop - Buybox
      await send('Emulation.setDeviceMetricsOverride', {
        width: 1280,
        height: 1400,
        deviceScaleFactor: 1,
        mobile: false
      });
      await send('Page.navigate', { url: 'https://tryzavelyn.com/products/breakout-2-0-holster-built-for-maximum-concealment-copy' });
      await new Promise(r => setTimeout(r, 4000));

      const ssBuybox = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/updated_desktop_buybox.png', Buffer.from(ssBuybox.data, 'base64'));

      // 2. Desktop - Breakthrough Design section
      await send('Runtime.evaluate', {
        expression: `(() => {
          const el = document.querySelector('.bh-breakthrough-card');
          if (el) el.scrollIntoView({ behavior: 'instant', block: 'start' });
        })()`
      });
      await new Promise(r => setTimeout(r, 1000));
      const ssBreakthrough = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/updated_desktop_breakthrough.png', Buffer.from(ssBreakthrough.data, 'base64'));

      // 3. Mobile - Breakthrough Design section
      await send('Emulation.setDeviceMetricsOverride', {
        width: 390,
        height: 844,
        deviceScaleFactor: 2,
        mobile: true
      });
      await send('Page.reload');
      await new Promise(r => setTimeout(r, 3500));
      await send('Runtime.evaluate', {
        expression: `(() => {
          const el = document.querySelector('.bh-breakthrough-card');
          if (el) el.scrollIntoView({ behavior: 'instant', block: 'start' });
        })()`
      });
      await new Promise(r => setTimeout(r, 1000));
      const ssMobileBreakthrough = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/updated_mobile_breakthrough.png', Buffer.from(ssMobileBreakthrough.data, 'base64'));

      console.log('All updated screenshots captured successfully!');
    } catch (e) {
      console.error(e);
    } finally {
      ws.close();
      chromeProc.kill();
    }
  });
}
main().catch(console.error);

