          saveAmt += (29.00 - bumpPrice);
        }

        const priceStr = '$' + finalPrice.toFixed(2);
        if (priceDisplay) priceDisplay.textContent = priceStr;
        if (ctaText) ctaText.textContent = 'ADD TO CART – ' + priceStr;
        if (mobilePrice) mobilePrice.textContent = priceStr;

        if (savingsDisplay) {
          savingsDisplay.textContent = '⇘ 🏷️ You save $' + saveAmt.toFixed(2) + ' on this order + FREE 2nd Holster included ⇙';
        }
      }`;

const newBlock = `      // Material Swatches
      document.querySelectorAll('#Section-{{ section.id }} .bh-swatch-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          document.querySelectorAll('#Section-{{ section.id }} .bh-swatch-btn').forEach(b => b.classList.remove('active'));
          btn.classList.add('active');
          const mat = btn.getAttribute('data-mat');
          const matInp = document.getElementById('bh-material-val');
          if (matInp) matInp.value = mat;
          updatePricing();
        });
