import { spawn } from 'child_process';
import fs from 'fs';

const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const tempDir = 'C:\\Users\\Admin\\AppData\\Local\\Temp\\chrome_cdp_test';

const chromeProc = spawn(chromePath, [
  '--headless=new',
  '--remote-debugging-port=9222',
  `--user-data-dir=${tempDir}`,
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check'
], { detached: false });

async function main() {
  await new Promise(r => setTimeout(r, 1500));
  const res = await fetch('http://127.0.0.1:9222/json');
  const tabs = await res.json();
  const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);
  let id = 1;
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const curId = id++;
    const handler = (evt) => {
      const msg = JSON.parse(evt.data.toString());
      if (msg.id === curId) {
        ws.removeEventListener('message', handler);
        if (msg.error) reject(msg.error);
        else resolve(msg.result);
      }
    };
    ws.addEventListener('message', handler);
    ws.send(JSON.stringify({ id: curId, method, params }));
  });

  ws.addEventListener('open', async () => {
    try {
      await send('Page.enable');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 1280,
        height: 1400,
        deviceScaleFactor: 1,
        mobile: false
      });
      await send('Page.navigate', { url: 'https://tryzavelyn.com/products/breakout-2-0-holster-built-for-maximum-concealment-copy' });
      await new Promise(r => setTimeout(r, 4000));

      // 1. Capture Flat Black (default: $99.99, was $200.00, no bump)
      const ssFlat = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/final_flat_black.png', Buffer.from(ssFlat.data, 'base64'));
      console.log('Saved scratch/final_flat_black.png');

      // 2. Click Carbon Fiber Upgrade
      await send('Runtime.evaluate', {
        expression: `(() => {
          const carbonBtn = document.querySelectorAll('.bh-swatch-btn')[1];
          if (carbonBtn) carbonBtn.click();
        })()`
      });
      await new Promise(r => setTimeout(r, 800));

      const priceText = await send('Runtime.evaluate', {
        expression: `document.getElementById('bh-price-val').innerText`,
        returnByValue: true
      });
      const compareText = await send('Runtime.evaluate', {
        expression: `document.getElementById('bh-compare-val').innerText`,
        returnByValue: true
      });
      const ctaText = await send('Runtime.evaluate', {
        expression: `document.getElementById('bh-cta-btn-text').innerText`,
        returnByValue: true
      });

      console.log('Carbon Fiber Price:', priceText.result.value);
      console.log('Carbon Fiber Compare At:', compareText.result.value);
      console.log('Carbon Fiber CTA:', ctaText.result.value);

      const ssCarbon = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/final_carbon_129.png', Buffer.from(ssCarbon.data, 'base64'));
      console.log('Saved scratch/final_carbon_129.png');

      // 3. Mobile View with Carbon Fiber
      await send('Emulation.setDeviceMetricsOverride', {
        width: 390,
        height: 844,
        deviceScaleFactor: 2,
        mobile: true
      });
      await send('Page.reload');
      await new Promise(r => setTimeout(r, 3500));
      await send('Runtime.evaluate', {
        expression: `(() => {
          const carbonBtn = document.querySelectorAll('.bh-swatch-btn')[1];
          if (carbonBtn) carbonBtn.click();
          window.scrollTo(0, 600);
        })()`
      });
      await new Promise(r => setTimeout(r, 800));
      const ssMobile = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/final_mobile_carbon_129.png', Buffer.from(ssMobile.data, 'base64'));
      console.log('Saved scratch/final_mobile_carbon_129.png');

    } catch (e) {
      console.error(e);
    } finally {
      ws.close();
      chromeProc.kill();
    }
  });
}
main().catch(console.error);

