async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      client_id: CLIENT_ID,
      client_secret: CLIENT_SECRET,
      grant_type: 'client_credentials'
    })
  });
  const data = await res.json();
  return data.access_token;
}

async function uploadFile(filePath, filename) {
  const token = await getAccessToken();
  const fileStats = fs.statSync(filePath);
  const fileSize = fileStats.size.toString();

  // 1. StagedUploadsCreate
  const stagedQuery = `
    mutation stagedUploadsCreate($input: [StagedUploadInput!]!) {
      stagedUploadsCreate(input: $input) {
        stagedTargets {
          url
          resourceUrl
          parameters {
            name
            value
          }
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  const stagedRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/graphql.json`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      query: stagedQuery,
      variables: {
        input: [
          {
            filename,
            mimeType: 'image/png',
            resource: 'IMAGE',
            fileSize
          }
        ]
      }
    })
  });

  const stagedData = await stagedRes.json();
  const target = stagedData.data.stagedUploadsCreate.stagedTargets[0];
  const uploadUrl = target.url;
  const resourceUrl = target.resourceUrl;
  const params = target.parameters;

  // 2. Post file to target.url
  const formData = new FormData();
  params.forEach(p => formData.append(p.name, p.value));
  const fileBuffer = fs.readFileSync(filePath);
  const blob = new Blob([fileBuffer], { type: 'image/png' });
  formData.append('file', blob, filename);

  const postRes = await fetch(uploadUrl, {
    method: 'POST',
    body: formData
  });

  if (!postRes.ok) {
    throw new Error(`Upload failed with status: ${postRes.statusText}`);
  }

  // 3. fileCreate mutation
  const fileCreateQuery = `
    mutation fileCreate($files: [FileCreateInput!]!) {
      fileCreate(files: $files) {
        files {
          ... on MediaImage {
            id
            image {
              url
            }
          }
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  const fileRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/graphql.json`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      query: fileCreateQuery,
      variables: {
        files: [
          {
            originalSource: resourceUrl,
            contentType: 'IMAGE'
          }
        ]
      }
    })
  });

  const fileData = await fileRes.json();
  const mediaImage = fileData.data.fileCreate.files[0];
  console.log('File created:', mediaImage);
  return mediaImage;
}

