      client_id: CLIENT_ID,
      client_secret: CLIENT_SECRET,
      grant_type: 'client_credentials'
    })
  });
  const data = await res.json();
  return data.access_token;
}

async function uploadLocalFile(token, filePath, filename, alt) {
  const buffer = fs.readFileSync(filePath);
  const stagedQuery = `
    mutation stagedUploadsCreate($input: [StagedUploadInput!]!) {
      stagedUploadsCreate(input: $input) {
        stagedTargets {
          url
          resourceUrl
          parameters {
            name
            value
          }
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  const stagedRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2025-01/graphql.json`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      query: stagedQuery,
      variables: {
        input: [{
          resource: "IMAGE",
          filename,
          mimeType: "image/png",
          fileSize: buffer.length.toString(),
          httpMethod: "POST"
        }]
      }
    })
  });

  const stagedData = await stagedRes.json();
  const target = stagedData.data.stagedUploadsCreate.stagedTargets[0];

  const formData = new FormData();
  target.parameters.forEach(param => {
    formData.append(param.name, param.value);
  });
  formData.append('file', new Blob([buffer]));

  const uploadRes = await fetch(target.url, {
    method: 'POST',
    body: formData
  });

  if (!uploadRes.ok && uploadRes.status !== 201 && uploadRes.status !== 204) {
    throw new Error(`Upload to staged target failed with status ${uploadRes.status}`);
  }

  const fileCreateQuery = `
    mutation fileCreate($files: [FileCreateInput!]!) {
      fileCreate(files: $files) {
        files {
          id
          fileStatus
          alt
          ... on GenericFile { url }
          ... on MediaImage {
            image {
              url
            }
          }
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  const fileCreateRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2025-01/graphql.json`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      query: fileCreateQuery,
      variables: {
        files: [{
          alt,
          contentType: "IMAGE",
          originalSource: target.resourceUrl
        }]
      }
    })
  });

  const fileCreateData = await fileCreateRes.json();
  const file = fileCreateData.data.fileCreate.files[0];
  console.log(`Created file ${filename}: ID=${file.id}, Status=${file.fileStatus}`);

  // Poll for ready
  const query = `
    query getFile($id: ID!) {
      node(id: $id) {
        ... on MediaImage {
          image {
            url
          }
        }
      }
    }
  `;
  for (let i = 0; i < 15; i++) {
    await new Promise(r => setTimeout(r, 1000));
    const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2025-01/graphql.json`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Shopify-Access-Token': token
      },
      body: JSON.stringify({ query, variables: { id: file.id } })
    });
    const d = await res.json();
    const url = d.data?.node?.image?.url;
    if (url) {
      console.log(`URL ready for ${filename}:`, url);
      return url;
    }
  }
}

async function run() {
  const token = await getAccessToken();
  const url = await uploadLocalFile(token, 'scratch/thumb1_clean.png', 'zavelyn-rehab-box-thumb.png', 'Rehabilitation Glove Box');
  fs.writeFileSync('scratch/rehab_thumb_url.json', JSON.stringify({ url }, null, 2));
}

run().catch(console.error);

