import fs from 'fs';

const THUMB_URL = 'https://cdn.shopify.com/s/files/1/0826/2483/9865/files/zavelyn-rehab-box-thumb.png?v=1794152773';

let content = fs.readFileSync('sections/rehab-glove-pdp-lushroot.liquid', 'utf8');

// 1. Update CSS around size guide and selectors
const oldCSSPattern = /\/\* SIZING GUIDE BUTTON \*\/[\s\S]*?(?=\/\* SIZING GUIDE MODAL \*\/)/;

const newCSS = `/* SIZING GUIDE BUTTON */
    #Section-{{ section.id }} .lr-size-guide-trigger {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 14px;
      font-weight: 700;
      color: var(--lr-wine);
      cursor: pointer;
      margin-bottom: 16px;
      text-decoration: underline;
      text-underline-offset: 3px;
      background: none;
      border: none;
      padding: 0;
      width: fit-content;
      transition: opacity 0.2s ease;
    }
    #Section-{{ section.id }} .lr-size-guide-trigger:hover {
      opacity: 0.85;
    }
    #Section-{{ section.id }} .lr-size-guide-icon {
      flex-shrink: 0;
      stroke: var(--lr-wine);
    }

    /* BUNDLE STACK */
    #Section-{{ section.id }} .lr-bundle-stack {
      display: flex;
      flex-direction: column;
      gap: 16px;
      margin-bottom: 16px;
    }

    /* BUNDLE CARD COMMON */
    #Section-{{ section.id }} .lr-bcard {
      position: relative;
      background: #FFFFFF;
      border: 1.5px solid #F0E6EC;
      border-radius: 18px;
      padding: 16px 18px;
      cursor: pointer;
      transition: all 0.2s ease;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    #Section-{{ section.id }} .lr-bcard:hover {
      border-color: rgba(106, 27, 54, 0.4);
    }

    #Section-{{ section.id }} .lr-bcard.active {
      border: 2px solid var(--lr-wine);
      box-shadow: 0 4px 18px rgba(106, 27, 54, 0.08);
    }

    #Section-{{ section.id }} .lr-bcard.has-badge {
      padding-top: 22px;
    }

    #Section-{{ section.id }} .lr-bcard-corner-badge {
      position: absolute;
      top: -1px;
      right: -1px;
      background: var(--lr-wine);
      color: #FFFFFF;
      font-size: 11px;
      font-weight: 800;
      letter-spacing: 0.8px;
      padding: 5px 14px;
      border-radius: 0 16px 0 10px;
      text-transform: uppercase;
      z-index: 2;
      display: flex;
      align-items: center;
      gap: 5px;
    }

    /* TOP ROW: RADIO + THUMBNAILS + TITLE + PRICE */
    #Section-{{ section.id }} .lr-bcard-top {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 12px;
    }

    #Section-{{ section.id }} .lr-bcard-top-left {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      flex: 1;
      min-width: 0;
    }

    /* CUSTOM RADIO BUTTON */
    #Section-{{ section.id }} .lr-bcard-radio {
      width: 22px;
      height: 22px;
      border-radius: 50%;
      border: 2px solid #C4B5BD;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-top: 3px;
      flex-shrink: 0;
      transition: all 0.2s ease;
      background: #FFFFFF;
    }

    #Section-{{ section.id }} .lr-bcard.active .lr-bcard-radio {
      border-color: var(--lr-wine);
    }

    #Section-{{ section.id }} .lr-bcard-radio-dot {
      width: 12px;
      height: 12px;
      border-radius: 50%;
      background: var(--lr-wine);
      opacity: 0;
      transform: scale(0.3);
      transition: all 0.2s ease;
    }

    #Section-{{ section.id }} .lr-bcard.active .lr-bcard-radio-dot {
      opacity: 1;
      transform: scale(1);
    }

    /* CARD LEFT THUMBNAIL */
    #Section-{{ section.id }} .lr-bcard-thumb {
      width: 65px;
      height: 65px;
      border-radius: 12px;
      object-fit: cover;
      background: #FFFFFF;
      border: 1px solid rgba(106, 27, 54, 0.12);
      flex-shrink: 0;
      display: block;
    }

    /* TITLE CONTENT */
    #Section-{{ section.id }} .lr-bcard-info {
      display: flex;
      flex-direction: column;
      gap: 2px;
      flex: 1;
      min-width: 0;
    }

    #Section-{{ section.id }} .lr-bcard-title-row {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-wrap: wrap;
    }

    #Section-{{ section.id }} .lr-bcard-title {
      font-size: 17px;
      font-weight: 800;
      color: var(--lr-plum-dark);
      letter-spacing: -0.2px;
      line-height: 1.25;
    }

    #Section-{{ section.id }} .lr-bcard-tag-pink {
      background: #FFEBF0;
      color: var(--lr-wine);
      font-size: 12px;
      font-weight: 700;
      padding: 3px 8px;
      border-radius: 6px;
      white-space: nowrap;
    }

    #Section-{{ section.id }} .lr-bcard-desc {
      font-size: 13px;
      color: #6C5B64;
      line-height: 1.4;
      margin: 2px 0 0 0;
    }

    #Section-{{ section.id }} .lr-bcard-shipping-note {
      font-size: 12.5px;
      font-weight: 700;
      color: #1F7A37;
      display: flex;
      align-items: center;
      gap: 5px;
      margin-top: 4px;
    }

    /* RIGHT PRICING IN CARD */
    #Section-{{ section.id }} .lr-bcard-pricing {
      text-align: right;
      flex-shrink: 0;
      display: flex;
      flex-direction: column;
      align-items: flex-end;
    }

    #Section-{{ section.id }} .lr-bcard-price {
      font-size: 21px;
      font-weight: 800;
      color: var(--lr-plum-dark);
      line-height: 1.1;
    }

    #Section-{{ section.id }} .lr-bcard-compare {
      font-size: 13.5px;
      color: #998891;
      text-decoration: line-through;
      margin-top: 2px;
    }

    #Section-{{ section.id }} .lr-bcard-each {
      font-size: 12px;
      color: var(--lr-text-muted);
      margin-top: 2px;
    }

    /* SELECTORS LAYOUT */
    #Section-{{ section.id }} .lr-selectors-single,
    #Section-{{ section.id }} .lr-selectors-dual {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
      padding-top: 4px;
    }

    #Section-{{ section.id }} .lr-pill-pair {
      display: flex;
      gap: 6px;
      width: 100%;
    }

    #Section-{{ section.id }} .lr-selector-group {
      display: flex;
      flex-direction: column;
      gap: 4px;
      min-width: 0;
    }

    #Section-{{ section.id }} .lr-selector-label {
      font-size: 12.5px;
      font-weight: 750;
      color: var(--lr-plum-dark);
      margin-bottom: 2px;
    }

    #Section-{{ section.id }} .lr-select-pill {
      position: relative;
      background: #FFFFFF;
      border: 1.5px solid var(--lr-wine);
      border-radius: 20px;
      height: 38px;
      display: flex;
      align-items: center;
      padding: 0 24px 0 10px;
      cursor: pointer;
      transition: all 0.15s ease;
      width: 100%;
      box-sizing: border-box;
      min-width: 0;
    }

    #Section-{{ section.id }} .lr-select-pill select {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      opacity: 0;
      cursor: pointer;
      z-index: 2;
    }

    #Section-{{ section.id }} .lr-select-pill-text {
      font-size: 13px;
      font-weight: 650;
      color: var(--lr-plum-dark);
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      pointer-events: none;
    }

    #Section-{{ section.id }} .lr-select-pill-arrow {
      position: absolute;
      right: 9px;
      top: 50%;
      transform: translateY(-50%);
      width: 10px;
      height: 6px;
      pointer-events: none;
      color: var(--lr-wine);
    }

    @media (max-width: 540px) {
      #Section-{{ section.id }} .lr-selectors-single,
      #Section-{{ section.id }} .lr-selectors-dual {
        gap: 8px;
      }
      #Section-{{ section.id }} .lr-pill-pair {
        gap: 4px;
      }
      #Section-{{ section.id }} .lr-select-pill {
        padding: 0 18px 0 8px;
        height: 36px;
      }
      #Section-{{ section.id }} .lr-select-pill-text {
        font-size: 11.5px;
      }
      #Section-{{ section.id }} .lr-select-pill-arrow {
        right: 6px;
        width: 8px;
      }
      #Section-{{ section.id }} .lr-selector-label {
        font-size: 11px;
      }
    }

    /* MINT SAVINGS ACCENT BANNER */
    #Section-{{ section.id }} .lr-savings-banner {
      background: #EBF6EE;
      border-radius: 12px;
      padding: 12px 18px;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      margin-bottom: 14px;
      text-align: center;
    }

    #Section-{{ section.id }} .lr-savings-tag-icon {
      flex-shrink: 0;
      stroke: var(--lr-wine);
    }

    #Section-{{ section.id }} .lr-savings-text {
      font-size: 15px;
      font-weight: 750;
      color: var(--lr-wine);
      line-height: 1.25;
    }

    /* PRIMARY CTA BUTTON */
    #Section-{{ section.id }} .lr-cta-btn {
      width: 100%;
      background: var(--lr-wine);
      color: #FFFFFF;
      border: none;
      border-radius: 14px;
      padding: 16px 20px;
      font-size: 18px;
      font-weight: 800;
      letter-spacing: 0.3px;
      cursor: pointer;
      box-shadow: 0 6px 20px rgba(106, 27, 54, 0.28);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 4px;
      transition: all 0.2s ease;
      text-decoration: none;
    }

    #Section-{{ section.id }} .lr-cta-btn:hover {
      background: var(--lr-wine-hover);
      transform: translateY(-1px);
      box-shadow: 0 8px 24px rgba(106, 27, 54, 0.35);
    }

    #Section-{{ section.id }} .lr-cta-main-row {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
    }

    #Section-{{ section.id }} .lr-cta-cart-svg {
      width: 20px;
      height: 20px;
      fill: currentColor;
      flex-shrink: 0;
    }

    #Section-{{ section.id }} .lr-cta-subtext {
      font-size: 12.5px;
      font-weight: 650;
      color: rgba(255, 255, 255, 0.9);
      letter-spacing: 0.4px;
      display: flex;
      align-items: center;
      gap: 6px;
    }

    #Section-{{ section.id }} .lr-safe-row {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 12px;
      margin-top: 14px;
      font-size: 12px;
      color: var(--lr-text-muted);
      font-weight: 550;
      flex-wrap: wrap;
    }

    #Section-{{ section.id }} .lr-safe-divider {
      color: #D9CCD3;
    }

    `;

