import { spawn } from 'child_process';
import fs from 'fs';

const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const tempDir = 'C:\\Users\\Admin\\AppData\\Local\\Temp\\chrome_cdp_test';

const chromeProc = spawn(chromePath, [
  '--headless=new',
  '--remote-debugging-port=9222',
  `--user-data-dir=${tempDir}`,
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check'
], { detached: false });

async function main() {
  await new Promise(r => setTimeout(r, 1500));
  const res = await fetch('http://127.0.0.1:9222/json');
  const tabs = await res.json();
  const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);
  let id = 1;
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const curId = id++;
    const handler = (evt) => {
      const msg = JSON.parse(evt.data.toString());
      if (msg.id === curId) {
        ws.removeEventListener('message', handler);
        if (msg.error) reject(msg.error);
        else resolve(msg.result);
      }
    };
    ws.addEventListener('message', handler);
    ws.send(JSON.stringify({ id: curId, method, params }));
  });

  ws.addEventListener('open', async () => {
    try {
      await send('Page.enable');

      // 1. Desktop View
      await send('Emulation.setDeviceMetricsOverride', {
        width: 1280,
        height: 1200,
        deviceScaleFactor: 1,
        mobile: false
      });
      await send('Page.navigate', { url: 'https://tryzavelyn.com/products/zavelyn-rehabilitation-glove' });
      await new Promise(r => setTimeout(r, 4000));

      // Scroll to buybox bundle
      await send('Runtime.evaluate', {
        expression: `(() => {
          const el = document.querySelector('.lr-bundle-stack');
          if (el) el.scrollIntoView({ behavior: 'instant', block: 'center' });
        })()`
      });
      await new Promise(r => setTimeout(r, 500));

      const ssDesktop = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/rehab_bundle_desktop.png', Buffer.from(ssDesktop.data, 'base64'));
      console.log('Saved scratch/rehab_bundle_desktop.png');

      // 2. Click Card 1 (1 Glove)
      await send('Runtime.evaluate', {
        expression: `(() => {
          const card1 = document.querySelectorAll('.lr-bcard')[0];
          if (card1) card1.click();
        })()`
      });
      await new Promise(r => setTimeout(r, 500));

      const ssCard1 = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/rehab_card1_clicked.png', Buffer.from(ssCard1.data, 'base64'));
      console.log('Saved scratch/rehab_card1_clicked.png');

      // 3. Mobile View (iPhone 12/13/14: 390x844)
      await send('Emulation.setDeviceMetricsOverride', {
        width: 390,
        height: 844,
        deviceScaleFactor: 2,
        mobile: true
      });
      await send('Page.reload');
      await new Promise(r => setTimeout(r, 3500));

      await send('Runtime.evaluate', {
        expression: `(() => {
          const el = document.querySelector('.lr-size-guide-trigger');
          if (el) el.scrollIntoView({ behavior: 'instant', block: 'start' });
        })()`
      });
      await new Promise(r => setTimeout(r, 500));

      const ssMobile = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/rehab_bundle_mobile.png', Buffer.from(ssMobile.data, 'base64'));
      console.log('Saved scratch/rehab_bundle_mobile.png');

      // 4. Test Sizing Guide Modal click
      await send('Runtime.evaluate', {
        expression: `(() => {
          const btn = document.getElementById('lr-open-size-modal');
          if (btn) btn.click();
        })()`
      });
      await new Promise(r => setTimeout(r, 500));

      const ssModal = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/rehab_modal_mobile.png', Buffer.from(ssModal.data, 'base64'));
      console.log('Saved scratch/rehab_modal_mobile.png');

      console.log('All screenshots captured successfully!');
      chromeProc.kill();
      process.exit(0);
    } catch (err) {
      console.error(err);
      chromeProc.kill();
      process.exit(1);
    }
  });
}

main().catch(console.error);

