import fs from 'fs';
import path from 'path';
import readline from 'readline';

const BRAIN_DIR = 'C:/Users/Admin/.gemini/antigravity/brain/2f3e6b33-be3a-4971-95cb-b168e69dafef';
const TARGET_DIR = path.resolve('session_chat');
const UPLOADS_DIR = path.join(TARGET_DIR, 'user_uploads');

if (!fs.existsSync(TARGET_DIR)) fs.mkdirSync(TARGET_DIR, { recursive: true });
if (!fs.existsSync(UPLOADS_DIR)) fs.mkdirSync(UPLOADS_DIR, { recursive: true });

// 1. Copy user uploads
const sourceUploads = path.join(BRAIN_DIR, '.user_uploaded');
if (fs.existsSync(sourceUploads)) {
  const files = fs.readdirSync(sourceUploads);
  for (const f of files) {
    fs.copyFileSync(path.join(sourceUploads, f), path.join(UPLOADS_DIR, f));
    console.log(`Copied upload: ${f}`);
  }
}

// 2. Copy transcript.jsonl & transcript_full.jsonl
const transPath = path.join(BRAIN_DIR, '.system_generated/logs/transcript.jsonl');
const transFullPath = path.join(BRAIN_DIR, '.system_generated/logs/transcript_full.jsonl');

if (fs.existsSync(transPath)) {
  fs.copyFileSync(transPath, path.join(TARGET_DIR, 'transcript.jsonl'));
  console.log('Copied transcript.jsonl');
}
if (fs.existsSync(transFullPath)) {
  fs.copyFileSync(transFullPath, path.join(TARGET_DIR, 'transcript_full.jsonl'));
  console.log('Copied transcript_full.jsonl');
}

// 3. Parse transcript and build clean markdown conversation history
async function buildMarkdown() {
  const fileStream = fs.createReadStream(transPath);
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  const turns = [];
  let currentTurn = null;

  for await (const line of rl) {
    if (!line.trim()) continue;
    try {
      const step = JSON.parse(line);

      if (step.type === 'USER_INPUT') {
        if (currentTurn) {
          turns.push(currentTurn);
        }
        currentTurn = {
          stepIndex: step.step_index,
          createdAt: step.created_at,
          userContent: step.content || '',
          assistantResponses: [],
          toolCallsCount: 0
        };
      } else if (step.type === 'PLANNER_RESPONSE' && currentTurn) {
        if (step.tool_calls && step.tool_calls.length) {
          currentTurn.toolCallsCount += step.tool_calls.length;
        }
        if (step.content && step.content.trim()) {
          // Avoid intermediate progress messages if final exists, or accumulate
          currentTurn.assistantResponses.push(step.content);
        }
      }
    } catch (e) {
      // ignore line parse error
    }
  }

  if (currentTurn) {
    turns.push(currentTurn);
  }

  let md = `# Zavelyn Shopify Storefront Optimization & Product Spy Session\n\n`;
  md += `**Store:** \`dsdujr-vn.myshopify.com\` / \`https://tryzavelyn.com\`\n`;
  md += `**Date:** November 2026\n`;
  md += `**Conversation ID:** \`2f3e6b33-be3a-4971-95cb-b168e69dafef\`\n`;
  md += `**Total Conversation Turns:** ${turns.length}\n\n`;
  md += `---\n\n`;

  turns.forEach((turn, idx) => {
    md += `## Turn ${idx + 1} (${turn.createdAt || 'N/A'})\n\n`;

    // Extract user request clean
    let userText = turn.userContent;
    const reqMatch = userText.match(/<USER_REQUEST>([\s\S]*?)<\/USER_REQUEST>/);
    if (reqMatch) {
      userText = reqMatch[1].trim();
    }

    // Extract attached images
    const imgMatches = [...turn.userContent.matchAll(/media_[0-9]+_[a-f0-9]+\.jpg/g)];
    const uniqueImgs = [...new Set(imgMatches.map(m => m[0]))];

    md += `### 👤 User Request:\n\n`;
    md += `${userText}\n\n`;

    if (uniqueImgs.length > 0) {
      md += `**Attached Images:**\n\n`;
      uniqueImgs.forEach(img => {
        md += `![User Reference](user_uploads/${img})\n\n`;
      });
    }

    if (turn.toolCallsCount > 0) {
      md += `*⚡ Execution: Ran ${turn.toolCallsCount} tool/system operations in this turn.*\n\n`;
    }

    md += `### 🤖 Assistant Response:\n\n`;
    if (turn.assistantResponses.length > 0) {
      const finalReply = turn.assistantResponses[turn.assistantResponses.length - 1];
      md += `${finalReply}\n\n`;
    } else {
      md += `*(Executed operations and synchronized store themes)*\n\n`;
    }

    md += `---\n\n`;
  });

  fs.writeFileSync(path.join(TARGET_DIR, 'FULL_CONVERSATION_HISTORY.md'), md, 'utf8');
  console.log('Generated FULL_CONVERSATION_HISTORY.md');
}

// 4. Create README.md in session_chat
function buildReadme() {
  const readmeContent = `# Zavelyn Shopify Session Logs & Deliverables

Tập hợp toàn bộ nhật ký trao đổi, tài liệu clone và lịch sử triển khai kỹ thuật cho cửa hàng **Zavelyn** (\`https://tryzavelyn.com\`).

---

## 📁 Cấu trúc thư mục

- \`FULL_CONVERSATION_HISTORY.md\`: Toàn bộ nội dung trao đổi qua các turn (User prompt, phản hồi chi tiết, hình ảnh đính kèm, thao tác hệ thống).
- \`transcript.jsonl\`: Dữ liệu thô JSON Lines của toàn bộ session.
- \`transcript_full.jsonl\`: Dữ liệu thô đầy đủ chi tiết (không bị cắt bớt chuỗi).
- \`user_uploads/\`: Toàn bộ hình ảnh thực tế được tải lên làm mẫu tham chiếu trong suốt phiên làm việc.

---

## 🚀 Tóm tắt các hạng mục đã hoàn thành trong phiên

### 1. BabiGuard Head Protector (\`babiguard-head-protector\`)
- Clone giao diện 1:1 từ đối thủ Babimate.
- Tái cấu trúc Bundle 3 Tiers (1 / 2 / 3 găng/gối) với Free Gifts đi kèm.
- Chuẩn hóa layout cân đối trên cả PC (lưới 2 cột) và Mobile (các pill selector xếp thẳng hàng, không bị méo lệch).
- Đổi chính sách cam kết thành **30-Day Money-Back Guarantee**.

### 2. Zavelyn Robotic Stroke Rehabilitation Glove (\`zavelyn-rehabilitation-glove\`)
- Kết nối và ánh xạ toàn bộ 10 variant từ sản phẩm gốc (\`Side of Hand\`: Right Hand / Left Hand; \`Size\`: Small - XXL).
- Thiết kế Bundle 2 Card theo đúng ảnh chụp mẫu:
  - **Card 1 (1 Glove):** $89.00 / $180.00 strike-through.
  - **Card 2 (2 Gloves - Most Popular):** $149.00 / $360.00 strike-through (Save 58%). Cấu hình 2 găng tay độc lập (\`Glove 1 Hand & Size\`, \`Glove 2 Hand & Size\`).
- Giữ nguyên popup hướng dẫn đo kích thước tay (**View Size Guide & Hand Measurement Chart**).
- Loại bỏ hoàn toàn upsell đai nhiệt và quà tặng không cần thiết.

### 3. Breakout 2.0 Concealment Holster (\`breakout-2-0-holster-built-for-maximum-concealment-copy\`)
- Clone từ đối thủ Houdini Holsters.
- Cấu hình đầy đủ **176 model súng** cho Holster 1 và **178 model súng** cho Holster 2 (BOGO).
- Bổ sung tùy chọn chất liệu:
  - **Flat Black (Included):** Giá $129.99 (gốc $260.00, Save 50%).
  - **Carbon Fiber Upgrade (+ $19.99):** Tự động nhảy giá lên $149.98.
- Thêm section **Breakthrough Design & Unmatched Performance** 6 thẻ ảnh chất lượng cao lưu trữ trực tiếp trên Shopify CDN.
- Gỡ bỏ hoàn toàn upsell kẹp từ tính (\`Universal Magnetic Pocket Clip\`).

### 4. Triển khai Theme & Kiểm thử
- Toàn bộ thay đổi đã được đồng bộ tự động lên theme chính đang chạy (\`Zavelyn 2.0 [main]\` - ID \`187597717689\`) và 8 theme phụ/draft trên store.
- Kiểm tra render visual thực tế trên trình duyệt Chrome headless (CDP) ở cả độ phân giải Desktop (1280px) và Mobile (390px).
`;

  fs.writeFileSync(path.join(TARGET_DIR, 'README.md'), readmeContent, 'utf8');
  console.log('Generated session_chat/README.md');
}

buildReadme();
