import fs from 'fs';
import path from 'path';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || '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';

const LIVE_THEME_ID = 187597717689;
const DRAFT_THEME_ID = 189127983289;
const BACKUP_DIR = path.resolve('backup_live_187597717689');

if (!fs.existsSync(BACKUP_DIR)) fs.mkdirSync(BACKUP_DIR, { recursive: true });

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      client_id: CLIENT_ID,
      client_secret: CLIENT_SECRET,
      grant_type: 'client_credentials'
    })
  });
  const data = await res.json();
  return data.access_token;
}

async function getAsset(token, themeId, key) {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${themeId}/assets.json?asset[key]=${encodeURIComponent(key)}`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  if (res.status === 429) {
    const retryAfter = parseFloat(res.headers.get('Retry-After') || '2');
    console.log(`Rate limited on GET ${key}, waiting ${retryAfter}s...`);
    await new Promise(r => setTimeout(r, retryAfter * 1000 + 500));
    return getAsset(token, themeId, key);
  }
  const data = await res.json();
  return data.asset;
}

async function putAsset(token, themeId, asset) {
  const payload = { asset: { key: asset.key } };
  if (asset.value !== undefined) {
    payload.asset.value = asset.value;
  } else if (asset.attachment !== undefined) {
    payload.asset.attachment = asset.attachment;
  }
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${themeId}/assets.json`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify(payload)
  });
  if (res.status === 429) {
    const retryAfter = parseFloat(res.headers.get('Retry-After') || '2');
    console.log(`Rate limited on PUT ${asset.key}, waiting ${retryAfter}s...`);
    await new Promise(r => setTimeout(r, retryAfter * 1000 + 500));
    return putAsset(token, themeId, asset);
  }
  return res.ok;
}

async function main() {
  const token = await getAccessToken();
  console.log('Got access token');

  // Load assets list
  const allAssets = JSON.parse(fs.readFileSync('scratch/live_assets_list.json', 'utf8'));

  // Query already present in draft theme
  const draftRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${DRAFT_THEME_ID}/assets.json`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const draftData = await draftRes.json();
  const existingInDraft = new Set((draftData.assets || []).map(a => a.key));
  console.log(`Draft already has ${existingInDraft.size} assets.`);

  // Sort by priority:
  // 1: config, locales, layout
  // 2: templates
  // 3: sections
  // 4: snippets
  // 5: assets/*.css, *.js, *.json
  // 6: remaining
  function getScore(key) {
    if (key.startsWith('config/') || key.startsWith('locales/') || key.startsWith('layout/')) return 1;
    if (key.startsWith('templates/')) return 2;
    if (key.startsWith('sections/')) return 3;
    if (key.startsWith('snippets/')) return 4;
    if (key.startsWith('assets/') && (key.endsWith('.css') || key.endsWith('.js') || key.endsWith('.json'))) return 5;
    return 6;
  }

  const pending = allAssets
    .filter(a => !existingInDraft.has(a.key))
    .sort((a, b) => getScore(a.key) - getScore(b.key));

  console.log(`Pending assets to copy: ${pending.length} (total: ${allAssets.length})`);

  let completed = 0;
  let errors = 0;

  // Process with concurrency of 2 (conservative & stable against 40-bucket rate limit)
  const CONCURRENCY = 2;
  let idx = 0;

  async function worker() {
    while (idx < pending.length) {
      const myIdx = idx++;
      const item = pending[myIdx];
      const key = item.key;
      const localPath = path.join(BACKUP_DIR, key);
      const localDir = path.dirname(localPath);
      if (!fs.existsSync(localDir)) fs.mkdirSync(localDir, { recursive: true });

      try {
        let assetData;
        // Check if already saved locally
        if (fs.existsSync(localPath)) {
          const isText = key.endsWith('.liquid') || key.endsWith('.json') || key.endsWith('.css') || key.endsWith('.js');
          if (isText) {
            assetData = { key, value: fs.readFileSync(localPath, 'utf8') };
          } else {
            assetData = { key, attachment: fs.readFileSync(localPath).toString('base64') };
          }
        } else {
          assetData = await getAsset(token, LIVE_THEME_ID, key);
          if (assetData.value !== undefined) {
            fs.writeFileSync(localPath, assetData.value, 'utf8');
          } else if (assetData.attachment !== undefined) {
            fs.writeFileSync(localPath, Buffer.from(assetData.attachment, 'base64'));
          }
        }

        const ok = await putAsset(token, DRAFT_THEME_ID, assetData);
        if (ok) {
          completed++;
        } else {
          console.error(`Failed PUT: ${key}`);
          errors++;
        }

        if (completed % 15 === 0 || myIdx === pending.length - 1) {
          console.log(`[Priority ${getScore(key)}] Progress: ${completed}/${pending.length} (Errors: ${errors}) - Last: ${key}`);
        }
      } catch (e) {
        console.error(`Error on ${key}:`, e.message);
        errors++;
      }
      await new Promise(r => setTimeout(r, 200));
    }
  }

  await Promise.all(Array.from({ length: CONCURRENCY }, () => worker()));
  console.log(`\n🎉 Complete! Successfully copied ${completed} assets to Draft Theme ${DRAFT_THEME_ID}.`);
}

main().catch(console.error);

