    if (key.startsWith('snippets/')) return 4;
    if (key.startsWith('sections/')) return 5;
    if (key.startsWith('layout/')) return 6;
    if (key.startsWith('templates/')) return 7;
    return 8;
  }

  const sortedAssets = [...allAssets].sort((a, b) => getStage(a.key) - getStage(b.key));

  let downloadedCount = 0;
  let uploadedCount = 0;
  let skippedCount = 0;

  for (let i = 0; i < sortedAssets.length; i++) {
    const item = sortedAssets[i];
    const key = item.key;
    const stage = getStage(key);
    const localPath = path.join(BACKUP_DIR, key);
