        }
        downloadedCount++;
      }
      await new Promise(r => setTimeout(r, 120));
    }

    // Step B: upload to draft theme if missing
    if (!existingInDraft.has(key)) {
      try {
        await putAsset(token, DRAFT_THEME_ID, assetData);
        uploadedCount++;
        existingInDraft.add(key);
      } catch (err) {
        console.error(`Error uploading [Stage ${stage}] ${key}:`, err.message);
      }
      await new Promise(r => setTimeout(r, 150));
    } else {
      skippedCount++;
    }

