/**
 * ZAVELYN HAIR CARE — Core Theme Stylesheet (v1.0)
 * Scoped under .zvhc-root and zvhc- namespace
 * Target: dsdujr-vn.myshopify.com (Zavelyn Hair Care)
 */

:root {
  --zvhc-bg: #FAF7F2;
  --zvhc-bg-alt: #F4ECE1;
  --zvhc-card-bg: #FFFFFF;
  --zvhc-espresso: #221610;
  --zvhc-cocoa: #3A271E;
  --zvhc-muted: #735F54;
  --zvhc-border: #E8DDD2;
  --zvhc-border-light: #F0E8DF;

  --zvhc-copper: #B87333;
  --zvhc-copper-dark: #975B24;
  --zvhc-copper-light: #FDF6EE;
  --zvhc-gold: #C28D58;

  --zvhc-botanical: #2A5A43;
  --zvhc-botanical-light: #EDF5F0;
  --zvhc-burgundy-cta: #3B1B15;
  --zvhc-burgundy-cta-hover: #26100B;

  --zvhc-font-serif: "Playfair Display", "Cormorant Garamond", Georgia, serif;
  --zvhc-font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  --zvhc-radius-sm: 6px;
  --zvhc-radius-md: 10px;
  --zvhc-radius-lg: 16px;
  --zvhc-radius-full: 9999px;

  --zvhc-shadow-sm: 0 2px 8px rgba(34, 22, 16, 0.04);
  --zvhc-shadow-md: 0 8px 24px rgba(34, 22, 16, 0.08);
  --zvhc-shadow-lg: 0 16px 40px rgba(34, 22, 16, 0.12);
}

/* ==========================================================================
   GLOBAL HAIR CARE SCOPED BASE
   ========================================================================== */
.zvhc-wrapper {
  background-color: var(--zvhc-bg);
  color: var(--zvhc-espresso);
  font-family: var(--zvhc-font-sans);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.zvhc-container {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 20px;
}

@media (min-width: 768px) {
  .zvhc-container {
    padding: 0 32px;
  }
}

/* Typography Helpers */
.zvhc-serif {
  font-family: var(--zvhc-font-serif);
}

.zvhc-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--zvhc-copper);
}

.zvhc-heading-lg {
  font-family: var(--zvhc-font-serif);
  font-size: clamp(2rem, 4vw, 3.25rem);
  font-weight: 600;
  line-height: 1.15;
  color: var(--zvhc-espresso);
  letter-spacing: -0.01em;
}

.zvhc-heading-md {
  font-family: var(--zvhc-font-serif);
  font-size: clamp(1.5rem, 2.5vw, 2.25rem);
  font-weight: 600;
  line-height: 1.25;
  color: var(--zvhc-espresso);
}

.zvhc-heading-sm {
  font-family: var(--zvhc-font-serif);
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.35;
  color: var(--zvhc-espresso);
}

/* Button & Pill Styles */
.zvhc-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--zvhc-font-sans);
  font-weight: 600;
  font-size: 0.95rem;
  letter-spacing: 0.04em;
  padding: 14px 28px;
  border-radius: var(--zvhc-radius-md);
  text-decoration: none;
  cursor: pointer;
  transition: all 0.25s ease;
  border: 1px solid transparent;
}

.zvhc-btn-primary {
  background: var(--zvhc-burgundy-cta);
  color: #FFFFFF !important;
  box-shadow: 0 4px 14px rgba(59, 27, 21, 0.25);
}

.zvhc-btn-primary:hover {
  background: var(--zvhc-burgundy-cta-hover);
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(59, 27, 21, 0.35);
}

.zvhc-btn-secondary {
  background: transparent;
  color: var(--zvhc-espresso) !important;
  border: 1.5px solid var(--zvhc-espresso);
}

.zvhc-btn-secondary:hover {
  background: var(--zvhc-espresso);
  color: #FFFFFF !important;
}

/* ==========================================================================
   ANNOUNCEMENT BAR
   ========================================================================== */
.zvhc-announcement {
  background-color: var(--zvhc-cocoa);
  color: #FAF7F2;
  padding: 9px 16px;
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-align: center;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.zvhc-announcement a {
  color: #FAF7F2;
  text-decoration: underline;
  margin-left: 6px;
}

/* ==========================================================================
   HEADER & NAVIGATION
   ========================================================================== */
.zvhc-header {
  background: #FFFFFF;
  border-bottom: 1px solid var(--zvhc-border-light);
  position: sticky;
  top: 0;
  z-index: 100;
  transition: box-shadow 0.2s ease;
}

.zvhc-header.is-scrolled {
  box-shadow: var(--zvhc-shadow-sm);
}

.zvhc-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.zvhc-logo {
  text-decoration: none;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.zvhc-logo-title {
  font-family: var(--zvhc-font-serif);
  font-size: 1.65rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--zvhc-espresso);
  line-height: 1;
}

.zvhc-logo-sub {
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.28em;
  color: var(--zvhc-copper);
  text-transform: uppercase;
  margin-top: 2px;
}

.zvhc-nav {
  display: none;
}

@media (min-width: 992px) {
  .zvhc-nav {
    display: flex;
    align-items: center;
    gap: 28px;
  }
}

.zvhc-nav-link {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--zvhc-espresso);
  text-decoration: none;
  letter-spacing: 0.02em;
  position: relative;
  transition: color 0.2s ease;
}

.zvhc-nav-link:hover,
.zvhc-nav-link.active {
  color: var(--zvhc-copper);
}

.zvhc-header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.zvhc-bag-btn {
  background: transparent;
  border: none;
  cursor: pointer;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--zvhc-espresso);
  padding: 6px;
  border-radius: var(--zvhc-radius-sm);
}

.zvhc-bag-count {
  position: absolute;
  top: 0;
  right: 0;
  background: var(--zvhc-copper);
  color: #FFFFFF;
  font-size: 0.7rem;
  font-weight: 700;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.zvhc-mobile-menu-toggle {
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--zvhc-espresso);
  padding: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
}

@media (min-width: 992px) {
  .zvhc-mobile-menu-toggle {
    display: none;
  }
}

/* ==========================================================================
   HERO EDITORIAL SECTION
   ========================================================================== */
.zvhc-hero {
  padding: 48px 0 64px;
  background: linear-gradient(180deg, #FFFFFF 0%, var(--zvhc-bg) 100%);
  position: relative;
  overflow: hidden;
}

@media (min-width: 992px) {
  .zvhc-hero {
    padding: 72px 0 88px;
  }
}

.zvhc-hero-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 40px;
  align-items: center;
}

@media (min-width: 992px) {
  .zvhc-hero-grid {
    grid-template-columns: 1.1fr 0.9fr;
    gap: 64px;
  }
}

.zvhc-hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--zvhc-botanical-light);
  color: var(--zvhc-botanical);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 6px 14px;
  border-radius: var(--zvhc-radius-full);
  margin-bottom: 20px;
}

.zvhc-hero-title {
  margin-bottom: 20px;
}

.zvhc-hero-title span {
  color: var(--zvhc-copper);
  font-style: italic;
}

.zvhc-hero-subtitle {
  font-size: 1.1rem;
  color: var(--zvhc-muted);
  line-height: 1.65;
  margin-bottom: 32px;
  max-width: 540px;
}

.zvhc-hero-cta-group {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 36px;
}

.zvhc-hero-proof {
  display: flex;
  align-items: center;
  gap: 16px;
  padding-top: 24px;
  border-top: 1px solid var(--zvhc-border);
}

.zvhc-hero-avatars {
  display: flex;
  align-items: center;
}

.zvhc-hero-avatars img {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 2px solid #FFFFFF;
  margin-left: -10px;
  object-fit: cover;
}

.zvhc-hero-avatars img:first-child {
  margin-left: 0;
}

.zvhc-hero-proof-text {
  font-size: 0.85rem;
  color: var(--zvhc-espresso);
  font-weight: 600;
}

.zvhc-hero-proof-text span {
  display: block;
  font-size: 0.78rem;
  font-weight: 400;
  color: var(--zvhc-muted);
}

.zvhc-hero-media {
  position: relative;
}

.zvhc-hero-img-wrap {
  position: relative;
  border-radius: var(--zvhc-radius-lg);
  overflow: hidden;
  box-shadow: var(--zvhc-shadow-lg);
  aspect-ratio: 4/5;
  background: var(--zvhc-border-light);
}

.zvhc-hero-img-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.zvhc-hero-floating-card {
  position: absolute;
  bottom: 24px;
  left: -20px;
  background: #FFFFFF;
  padding: 14px 18px;
  border-radius: var(--zvhc-radius-md);
  box-shadow: var(--zvhc-shadow-md);
  border: 1px solid var(--zvhc-border-light);
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: 240px;
}

@media (max-width: 600px) {
  .zvhc-hero-floating-card {
    left: 12px;
