import fs from 'fs';
import path from 'path';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || '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';
const DRAFT_THEME_ID = 189127983289;

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const data = await res.json();
  return data.access_token;
}

async function putAsset(token, key, content) {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${DRAFT_THEME_ID}/assets.json`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({ asset: { key, value: content } })
  });
  if (!res.ok) {
    const text = await res.text();
    console.error(`❌ Failed ${key} (${res.status}): ${text}`);
    return false;
  }
  console.log(`✅ Uploaded: ${key}`);
  return true;
}

async function main() {
  const token = await getAccessToken();
  console.log('Access token acquired. Deploying Zavelyn Hair Care files to Draft Theme:', DRAFT_THEME_ID);

  const files = [
    // 1. Assets
    { key: 'assets/zvhc-haircare.css', file: 'assets/zvhc-haircare.css' },
    { key: 'assets/zvhc-pdp.css', file: 'assets/zvhc-pdp.css' },
    { key: 'assets/zvhc-pdp.js', file: 'assets/zvhc-pdp.js' },

    // 2. Sections
    { key: 'sections/zvhc-announcement-bar.liquid', file: 'sections/zvhc-announcement-bar.liquid' },
    { key: 'sections/zvhc-header.liquid', file: 'sections/zvhc-header.liquid' },
    { key: 'sections/zvhc-hero.liquid', file: 'sections/zvhc-hero.liquid' },
    { key: 'sections/zvhc-marquee.liquid', file: 'sections/zvhc-marquee.liquid' },
    { key: 'sections/zvhc-shop-by-concern.liquid', file: 'sections/zvhc-shop-by-concern.liquid' },
    { key: 'sections/zvhc-pdp-main.liquid', file: 'sections/zvhc-pdp-main.liquid' },
    { key: 'sections/zvhc-pdp-marquee.liquid', file: 'sections/zvhc-pdp-marquee.liquid' },
    { key: 'sections/zvhc-pdp-how-it-works.liquid', file: 'sections/zvhc-pdp-how-it-works.liquid' },
    { key: 'sections/zvhc-pdp-package.liquid', file: 'sections/zvhc-pdp-package.liquid' },
    { key: 'sections/zvhc-pdp-faq.liquid', file: 'sections/zvhc-pdp-faq.liquid' },
    { key: 'sections/zvhc-pdp-reviews.liquid', file: 'sections/zvhc-pdp-reviews.liquid' },
    { key: 'sections/zvhc-cart-drawer.liquid', file: 'sections/zvhc-cart-drawer.liquid' },
    { key: 'sections/zvhc-footer.liquid', file: 'sections/zvhc-footer.liquid' },

    // 3. Templates (after sections)
    { key: 'templates/product.zvhc-batana.json', file: 'templates/product.zvhc-batana.json' },
    { key: 'templates/product.zvhc-fibers.json', file: 'templates/product.zvhc-fibers.json' },
    { key: 'templates/index.json', file: 'templates/index.zvhc.json' },

    // 4. Layout
    { key: 'layout/theme.liquid', file: 'layout/theme.liquid' }
  ];

  for (const item of files) {
    if (!fs.existsSync(item.file)) {
      console.error(`File missing locally: ${item.file}`);
      continue;
    }
    const content = fs.readFileSync(item.file, 'utf8');
    await putAsset(token, item.key, content);
    await new Promise(r => setTimeout(r, 150));
  }

  console.log('\n🎉 Zavelyn Hair Care storefront deployment to Draft Theme complete!');
}

main().catch(console.error);

