import fs from 'fs';

async function checkUrl(url, label) {
  try {
    const res = await fetch(url, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
      }
    });
    const text = await res.text();
    console.log(`\n=================== [${label}] ===================`);
    console.log(`URL: ${url}`);
    console.log(`Status: ${res.status} ${res.statusText}`);
    console.log(`Content-Length: ${text.length}`);

    // Check key elements
    const hasHaircareCss = text.includes('zvhc-haircare.css');
    const hasZvhcHeader = text.includes('zvhc-header');
    const hasZvhcHero = text.includes('zvhc-hero');
    const hasZvhcBuybox = text.includes('zvhc-pdp-section') || text.includes('zvhcBuyBoxSection');
    const hasLegacyHeaderGroup = text.includes('header-group');
    const hasHolsterSection = text.includes('breakout-holster') || text.includes('Minimal Printing') || text.includes('Carbon Fiber');
    const hasRehabSection = text.includes('rehab-glove') || text.includes('Rehabilitation Glove') || text.includes('Side of Hand');
    const hasBabiSection = text.includes('babiguard') || text.includes('BabiGuard');

    console.log(`Checks:`);
    console.log(` - hasHaircareCss: ${hasHaircareCss}`);
    console.log(` - hasZvhcHeader: ${hasZvhcHeader}`);
    console.log(` - hasZvhcHero: ${hasZvhcHero}`);
    console.log(` - hasZvhcBuybox: ${hasZvhcBuybox}`);
    console.log(` - hasLegacyHeaderGroup: ${hasLegacyHeaderGroup}`);
    console.log(` - hasHolsterSection: ${hasHolsterSection}`);
    console.log(` - hasRehabSection: ${hasRehabSection}`);
    console.log(` - hasBabiSection: ${hasBabiSection}`);

    // Check title tag
    const titleMatch = text.match(/<title>([^<]+)<\/title>/i);
    if (titleMatch) {
      console.log(` - Title: "${titleMatch[1].trim()}"`);
    }
  } catch (err) {
    console.error(`Error fetching ${url}:`, err.message);
  }
}

async function main() {
  const THEME_PARAM = '?preview_theme_id=189127983289';

  // 1. Homepage
  await checkUrl(`https://tryzavelyn.com/${THEME_PARAM}`, 'NEW HAIR CARE HOMEPAGE');

  // 2. Batana PDP
  await checkUrl(`https://tryzavelyn.com/products/zavelyn-botanaroots-organic-batana-hair-growth-oil${THEME_PARAM}`, 'BATANA HAIR CARE PDP');

