  { id: '3256807671072569', label: 'PRODUCT 05' },
  { id: '3256811372233630', label: 'PRODUCT 06' },
  { id: '3256811903160451', label: 'PRODUCT 07' }
];

async function checkItem(item) {
  const url = `https://www.aliexpress.com/item/${item.id}.html`;
  try {
    const res = await fetch(url, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36',
        'Accept-Language': 'en-US,en;q=0.9',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'
      }
    });

    const html = await res.text();
    let ogTitle = '';
    const ogTitleMatch = html.match(/<meta\s+(?:property|name)="og:title"\s+content="([^"]+)"/i) || html.match(/<title>([^<]+)<\/title>/i);
    if (ogTitleMatch) ogTitle = ogTitleMatch[1];

    let ogImage = '';
    const ogImageMatch = html.match(/<meta\s+(?:property|name)="og:image"\s+content="([^"]+)"/i);
    if (ogImageMatch) ogImage = ogImageMatch[1];

    let images = [];
    const imgListMatch = html.match(/"imagePathList":\s*(\[[^\]]+\])/);
    if (imgListMatch) {
      try {
        images = JSON.parse(imgListMatch[1]);
      } catch (e) {}
    }

    // Save html for deeper inspection
    fs.writeFileSync(`scratch/raw_${item.id}.html`, html, 'utf8');

    return {
      id: item.id,
      label: item.label,
      status: res.status,
      title: ogTitle,
      mainImage: ogImage,
      galleryCount: images.length,
      images: images
    };
  } catch (err) {
    return {
      id: item.id,
      label: item.label,
      status: 'ERROR',
      error: err.message
    };
  }
}

async function main() {
  console.log('Fetching all 7 AliExpress items...');
  const results = [];
  for (const item of items) {
    const r = await checkItem(item);
    results.push(r);
    console.log(`[${r.label}] ID: ${r.id} | Status: ${r.status} | Images: ${r.galleryCount || 0}`);
    console.log(`  Title: ${r.title}`);
    console.log(`  MainImg: ${r.mainImage}`);
    await new Promise(res => setTimeout(res, 500));
  }

  fs.writeFileSync('scratch/all_7_initial.json', JSON.stringify(results, null, 2), 'utf8');
}

main().catch(console.error);

