import fs from 'fs';

const items = ['3256807907799249', '3256811885406846', '3256810605010511', '3256808781854155', '3256807671072569', '3256811372233630', '3256811903160451'];
for (const id of items) {
  const path = `scratch/raw_${id}.html`;
  if (!fs.existsSync(path)) continue;
  const html = fs.readFileSync(path, 'utf8');
  console.log(`--- ${id} ---`);
  const ldJson = html.match(/<script\s+type="application\/ld\+json">([\s\S]*?)<\/script>/gi);
  if (ldJson) {
    ldJson.forEach(l => console.log('LD+JSON:', l.replace(/\n/g, '').slice(0, 300)));
  } else {
    console.log('No ld+json');
  }

  // Look for meta description and keywords
  const descMatch = html.match(/<meta\s+name="description"\s+content="([^"]+)"/i);
  if (descMatch) console.log('Description:', descMatch[1].slice(0, 200));

  const kwMatch = html.match(/<meta\s+name="keywords"\s+content="([^"]+)"/i);
  if (kwMatch) console.log('Keywords:', kwMatch[1].slice(0, 200));
}

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';

const MEDIA_DIR = path.resolve('data/haircare_media');
if (!fs.existsSync(MEDIA_DIR)) fs.mkdirSync(MEDIA_DIR, { recursive: true });

const CONTACT_DIR = path.resolve('docs/haircare/aliexpress_import/04_PRODUCT_IMAGE_CONTACT_SHEETS');
if (!fs.existsSync(CONTACT_DIR)) fs.mkdirSync(CONTACT_DIR, { recursive: true });

const manifest = [];
const allData = JSON.parse(fs.readFileSync('scratch/all_7_initial.json', 'utf8'));

async function downloadImage(url, destPath) {
  const res = await fetch(url, {
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36',
      'Referer': 'https://www.aliexpress.com/'
    }
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const buffer = Buffer.from(await res.arrayBuffer());
  fs.writeFileSync(destPath, buffer);
  const hash = crypto.createHash('md5').update(buffer).digest('hex');
  return { size: buffer.length, hash };
}

async function main() {
  console.log('Downloading and cataloging product images...');

  for (const prod of allData) {
    const prodId = prod.id;
    const prodFolder = path.join(MEDIA_DIR, prodId);
    if (!fs.existsSync(prodFolder)) fs.mkdirSync(prodFolder, { recursive: true });

    console.log(`\nProcessing ${prod.label} (${prodId}): ${prod.images.length} images`);

    let imgIdx = 1;
    const contactSheetEntries = [];

    for (const imgUrl of prod.images) {
      const isHero = (imgIdx === 1);
      const role = isHero ? 'HERO' : (imgIdx === 2 ? 'LIFESTYLE / DETAIL' : (imgIdx === 3 ? 'BENEFITS / SPECS' : 'GALLERY'));
      const ext = path.extname(new URL(imgUrl).pathname) || '.jpg';
      const filename = isHero 
        ? `zvhc-${prodId}-hero${ext}` 
        : `zvhc-${prodId}-gallery-${String(imgIdx).padStart(2, '0')}${ext}`;

      const localPath = path.join(prodFolder, filename);

      try {
        let stats = null;
        if (fs.existsSync(localPath)) {
          const buf = fs.readFileSync(localPath);
          stats = { size: buf.length, hash: crypto.createHash('md5').update(buf).digest('hex') };
        } else {
          stats = await downloadImage(imgUrl, localPath);
          await new Promise(r => setTimeout(r, 200));
        }

        const entry = {
          item_id: prodId,
          product_label: prod.label,
          product_title: prod.title,
          filename: filename,
          local_path: localPath.replace(/\\/g, '/'),
          source_url: imgUrl,
          image_role: role,
          size_bytes: stats.size,
          md5_hash: stats.hash,
          rights_status: 'SUPPLIER_CATALOG_CANDIDATE',
          quality_status: stats.size > 20000 ? 'HIGH_RES_PASS' : 'REVIEW_REQUIRED'
        };

        manifest.push(entry);
        contactSheetEntries.push(entry);
        console.log(`  ✔ [${role}] ${filename} (${(stats.size / 1024).toFixed(1)} KB) - Hash: ${stats.hash.slice(0, 8)}`);
      } catch (err) {
        console.error(`  ❌ Failed to download ${imgUrl}:`, err.message);
      }
      imgIdx++;
    }

    // Generate Markdown Contact Sheet for this product
    let md = `# Visual Contact Sheet: ${prod.label} (${prodId})\n\n`;
    md += `**Source Title:** ${prod.title}\n`;
    md += `**Canonical URL:** https://www.aliexpress.us/item/${prodId}.html\n`;
    md += `**Total Verified Images:** ${contactSheetEntries.length}\n\n`;
    md += `| Index | Preview | Filename | Role | Size | MD5 Hash | Quality Status |\n`;
    md += `|---|---|---|---|---|---|---|\n`;
    contactSheetEntries.forEach((c, idx) => {
      md += `| ${idx + 1} | <img src="${c.source_url}" width="120" /> | \`${c.filename}\` | **${c.image_role}** | ${(c.size_bytes / 1024).toFixed(1)} KB | \`${c.md5_hash.slice(0, 8)}\` | ${c.quality_status} |\n`;
    });

    fs.writeFileSync(path.join(CONTACT_DIR, `${prodId}_CONTACT_SHEET.md`), md, 'utf8');
  }

  // Write 03_MEDIA_MANIFEST.csv
  let csv = `item_id,product_label,product_title,filename,local_path,source_url,image_role,size_bytes,md5_hash,rights_status,quality_status\n`;
  for (const m of manifest) {
    const escapedTitle = `"${m.product_title.replace(/"/g, '""')}"`;
    csv += `${m.item_id},${m.product_label},${escapedTitle},${m.filename},${m.local_path},${m.source_url},${m.image_role},${m.size_bytes},${m.md5_hash},${m.rights_status},${m.quality_status}\n`;
  }
  fs.writeFileSync('docs/haircare/aliexpress_import/03_MEDIA_MANIFEST.csv', csv, 'utf8');
  console.log(`\n🎉 Saved 03_MEDIA_MANIFEST.csv with ${manifest.length} verified media entries!`);
}

main().catch(console.error);

import fs from 'fs';

const items = [
  '3256807907799249',
  '3256811885406846',
  '3256810605010511',
  '3256808781854155',
  '3256807671072569',
  '3256811372233630',
  '3256811903160451'
];

for (const id of items) {
  const file = `scratch/raw_${id}.html`;
  if (!fs.existsSync(file)) continue;
  const html = fs.readFileSync(file, 'utf8');
  console.log(`\n=================== ITEM: ${id} ===================`);

  // 1. Look for DCData
  const dcMatch = html.match(/window\._d_c_\.DCData\s*=\s*(\{.+?\});/s);
  if (dcMatch) {
    try {
      const dcData = JSON.parse(dcMatch[1]);
      console.log('DCData keys:', Object.keys(dcData));
      console.log('Images:', dcData.imagePathList ? dcData.imagePathList.length : 0);
    } catch(e) {
      console.log('DCData match found but parse error:', e.message);
    }
  }

  // 2. Look for any data objects in script tags
  const scripts = html.match(/<script\b[^>]*>([\s\S]*?)<\/script>/gi) || [];
  for (const s of scripts) {
    if (s.includes('actionModule') || s.includes('titleModule') || s.includes('skuModule') || s.includes('specsModule')) {
      console.log('Found full detail module script! Length:', s.length);
    }
    // Search for store name
    const storeMatch = s.match(/"storeName":"([^"]+)"/) || s.match(/"shopName":"([^"]+)"/);
    if (storeMatch) {
      console.log('Store Name:', storeMatch[1]);
    }
    // Search for price
    const priceMatch = s.match(/"formattedPrice":"([^"]+)"/) || s.match(/"actMinPrice":"([^"]+)"/);
    if (priceMatch) {
      console.log('Price:', priceMatch[1]);
    }
  }

  // 3. Look for canonical link or meta
  const titleMatch = html.match(/<title>([^<]+)<\/title>/i);
  if (titleMatch) console.log('Title:', titleMatch[1]);
}

