import fetch from 'node-fetch';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || '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';

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const data = await res.json();
  return data.access_token;
}

async function main() {
  const token = await getAccessToken();
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/products.json?limit=100`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const data = await res.json();
  console.log(`Found ${data.products.length} products:`);
  for (const p of data.products) {
    console.log(`ID: ${p.id} | Status: ${p.status} | Template: ${p.template_suffix || 'default'} | Handle: ${p.handle}`);
    console.log(`   Title: ${p.title}`);
    console.log(`   Variants (${p.variants.length}):`, p.variants.map(v => `${v.title} ($${v.price})`).join(' | '));
  }
}

