      if (!variant || !variant.id) {
        alert('Please select an available product option.');
        return;
      }

      const ctaBtn = document.getElementById('zvhcMainCta');
      if (ctaBtn) {
        ctaBtn.disabled = true;
        ctaBtn.style.opacity = '0.7';
      }

      const payload = {
        id: variant.id,
        quantity: 1
      };

      fetch('/cart/add.js', {
