async function main() {
  const token = await getAccessToken();
  console.log('✅ Access Token acquired for store dsdujr-vn.myshopify.com');

  // Check existing products to avoid duplicating
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/products.json?limit=100`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const data = await res.json();
  const existingHandles = new Map(data.products.map(p => [p.handle, p]));

  for (const p of PRODUCTS_DATA) {
    console.log(`\nProcessing: ${p.title} (${p.handle})...`);

    // Prepare images from data/haircare_media/{itemId}
    const mediaDir = path.join(process.cwd(), 'data', 'haircare_media', p.itemId);
    let images = [];
    if (fs.existsSync(mediaDir)) {
      const files = fs.readdirSync(mediaDir).filter(f => f.endsWith('.jpg') || f.endsWith('.png') || f.endsWith('.webp'));
      // Sort so hero is first
      files.sort((a, b) => {
        if (a.includes('hero')) return -1;
        if (b.includes('hero')) return 1;
        return a.localeCompare(b);
      });
      // Attach top 3 images to avoid payload size limit
      for (const f of files.slice(0, 3)) {
        const filePath = path.join(mediaDir, f);
        const b64 = fs.readFileSync(filePath).toString('base64');
        images.push({
          attachment: b64,
          filename: f
        });
      }
    }

    const payload = {
      product: {
        title: p.title,
        handle: p.handle,
        body_html: p.body_html.trim(),
        vendor: p.vendor,
        product_type: p.product_type,
        template_suffix: p.template_suffix,
        status: 'draft', // STRICTLY DRAFT - NEVER PUBLISHED
        tags: p.tags,
        variants: p.variants.map((v, idx) => ({
          title: v.title,
          price: v.price,
          compare_at_price: v.compare_at_price,
          sku: v.sku,
          position: idx + 1,
          inventory_policy: 'continue',
          requires_shipping: true
        })),
        images: images
      }
    };

    if (existingHandles.has(p.handle)) {
      const existing = existingHandles.get(p.handle);
      console.log(`   Product already exists (ID: ${existing.id}). Updating to draft & ensuring template_suffix...`);
      const updateRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/products/${existing.id}.json`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'X-Shopify-Access-Token': token
        },
        body: JSON.stringify({
          product: {
            id: existing.id,
            status: 'draft',
            template_suffix: p.template_suffix,
            body_html: p.body_html.trim()
          }
        })
      });
      if (updateRes.ok) {
        console.log(`   ✅ Updated Product ID: ${existing.id} (Status: draft, Template: ${p.template_suffix})`);
      } else {
        console.error(`   ❌ Failed update (${updateRes.status}):`, await updateRes.text());
      }
    } else {
      console.log(`   Creating new DRAFT product in Shopify Admin...`);
      const createRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/products.json`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Shopify-Access-Token': token
        },
        body: JSON.stringify(payload)
      });
      if (createRes.ok) {
        const createdData = await createRes.json();
        console.log(`   🎉 Created Product ID: ${createdData.product.id} | Status: ${createdData.product.status} | Template: ${createdData.product.template_suffix}`);
      } else {
        console.error(`   ❌ Failed create (${createRes.status}):`, await createRes.text());
      }
    }

    await new Promise(r => setTimeout(r, 600)); // Respect Shopify rate limits
  }

  console.log('\n🌟 All 7 Zavelyn Hair Care draft products verified and created in Shopify Admin API.');
}

main().catch(console.error);

