import fs from 'fs';

const BASE_URL = 'https://tryzavelyn.com';
const DRAFT_THEME_ID = 189127983289;

async function checkRoute(pathName, expectedHaircare) {
  const url = `${BASE_URL}${pathName}?preview_theme_id=${DRAFT_THEME_ID}`;
  console.log(`\n========================================================`);
  console.log(`Testing Route: ${pathName}`);
  console.log(`URL: ${url}`);
  try {
    const res = await fetch(url, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
      }
    });

    console.log(`HTTP Status: ${res.status}`);
    const html = await res.text();

    const isHaircare = html.includes('zvhc-wrapper') || html.includes('zvhc-header');
    const hasDoubleAnnouncement = (html.match(/zvhc-announcement/g) || []).length > 1;
    const has45kClaim = html.includes('45,000+');
    const hasFakeViewers = html.includes('viewing right now');
    const has60DayClaim = html.includes('60-DAY') || html.includes('60-Day');

    console.log(`- Expected Haircare Route: ${expectedHaircare}`);
    console.log(`- Actual Haircare Rendered: ${isHaircare} -> ${isHaircare === expectedHaircare ? '✅ PASS' : '❌ MISMATCH'}`);
    console.log(`- Double Announcement Bar: ${hasDoubleAnnouncement ? '❌ FAIL (Double)' : '✅ PASS (Single/None)'}`);
    console.log(`- 45,000+ Claim Present: ${has45kClaim ? '❌ FAIL' : '✅ CLEAN'}`);
    console.log(`- Fake Viewer Counter Present: ${hasFakeViewers ? '❌ FAIL' : '✅ CLEAN'}`);
    console.log(`- 60-Day Claim Present: ${has60DayClaim ? '⚠️ (Check)' : '✅ CLEAN (30-day policy applied)'}`);

    return {
      path: pathName,
      status: res.status,
      isHaircare,
      pass: isHaircare === expectedHaircare && !has45kClaim && !hasFakeViewers
    };
  } catch (err) {
    console.error(`❌ Request Error: ${err.message}`);
    return { path: pathName, error: err.message, pass: false };
  }
}

async function main() {
  console.log(`🚀 Starting Comprehensive Storefront QA on Draft Theme ${DRAFT_THEME_ID}...`);

  const tests = [
    // 1. Root homepage (must be Hair Care on draft theme)
    { path: '/', expectedHaircare: true },

    // 2. New Hair Care PDP
    { path: '/products/zvhc-batana-hair-growth-oil', expectedHaircare: true },
    { path: '/products/zvhc-keratin-hair-building-fibers', expectedHaircare: true },

    // 3. Protected Legacy Funnels (MUST NOT be Hair Care!)
    { path: '/products/zavelyn-botanaroots-organic-batana-hair-growth-oil', expectedHaircare: false },
    { path: '/products/breakout-2-0-holster-built-for-maximum-concealment-copy', expectedHaircare: false },
    { path: '/products/zavelyn-rehabilitation-glove', expectedHaircare: false },
    { path: '/products/babiguard-head-protector', expectedHaircare: false },
    { path: '/products/the-yeoman-sweep', expectedHaircare: false }
  ];

  const results = [];
  for (const t of tests) {
    const res = await checkRoute(t.path, t.expectedHaircare);
    results.push(res);
  }

  console.log(`\n========================================================`);
  console.log(`🏁 FINAL SUMMARY:`);
  let allPass = true;
  for (const r of results) {
    console.log(`- [${r.pass ? 'PASS ✅' : 'FAIL ❌'}] ${r.path} (HTTP ${r.status})`);
    if (!r.pass) allPass = false;
  }
  console.log(`Overall Result: ${allPass ? 'ALL TESTS PASSED WITH ZERO REGRESSIONS 🎉' : 'ISSUES DETECTED'}`);
}

main().catch(console.error);

