const DRAFT_THEME_ID = '189127983289';

class CookieJar {
  constructor() {
    this.cookies = new Map();
  }
  setFromHeaders(headers) {
    let raw = [];
    if (typeof headers.getSetCookie === 'function') {
      raw = headers.getSetCookie();
    } else {
      const h = headers.get('set-cookie');
      if (h) raw = [h];
    }
    for (const cookieStr of raw) {
      const parts = cookieStr.split(';');
      const [nameVal] = parts;
      const eqIdx = nameVal.indexOf('=');
      if (eqIdx !== -1) {
        const k = nameVal.slice(0, eqIdx).trim();
        const v = nameVal.slice(eqIdx + 1).trim();
        this.cookies.set(k, v);
      }
    }
  }
  getCookieHeader() {
    return Array.from(this.cookies.entries()).map(([k, v]) => `${k}=${v}`).join('; ');
  }
}

async function fetchWithCookies(url, jar, options = {}) {
  const headers = { ...(options.headers || {}) };
  const cookieHeader = jar.getCookieHeader();
  if (cookieHeader) headers['Cookie'] = cookieHeader;

  const res = await fetch(url, {
    ...options,
    headers,
    redirect: 'manual'
  });

  jar.setFromHeaders(res.headers);

  if (res.status >= 300 && res.status < 400 && res.headers.get('location')) {
    const loc = new URL(res.headers.get('location'), url).toString();
    return fetchWithCookies(loc, jar, options);
  }

  return res;
}

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
