import fs from 'fs';
import path from 'path';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || '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';

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const data = await res.json();
  return data.access_token;
}

const PRODUCTS_MAP = [
  { itemId: '3256807907799249', shopifyId: 15542795731129, title: 'Product 01: Batana Hair Oil' },
  { itemId: '3256811885406846', shopifyId: 15542795763897, title: 'Product 02: Hair Building Fibers' },
  { itemId: '3256810605010511', shopifyId: 15542795796665, title: 'Product 03: Styling Texture Powder' },
  { itemId: '3256808781854155', shopifyId: 15542795862201, title: 'Product 04: Hairline Shadow Compact' },
  { itemId: '3256807671072569', shopifyId: 15542795894969, title: 'Product 05: Raw Batana Scalp Balm' },
  { itemId: '3256811372233630', shopifyId: 15542795927737, title: 'Product 06: Curl Defining Cream' },
  { itemId: '3256811903160451', shopifyId: 15542795960505, title: 'Product 07: 7-in-1 Botanical Oil' }
];

async function main() {
  const token = await getAccessToken();
  console.log('✅ Access Token acquired for store dsdujr-vn.myshopify.com');
  console.log('Syncing all 42 local images (6 per product) to Shopify draft products...\n');

  for (const item of PRODUCTS_MAP) {
    console.log(`Checking ${item.title} (Shopify ID: ${item.shopifyId})...`);

    // Get current images on Shopify
    const pRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/products/${item.shopifyId}/images.json`, {
      headers: { 'X-Shopify-Access-Token': token }
    });
    const pData = await pRes.json();
    const currentImages = pData.images || [];
    console.log(`   Currently attached on Shopify: ${currentImages.length} images`);

    // Read all 6 files from local directory
    const dir = path.join(process.cwd(), 'data', 'haircare_media', item.itemId);
    if (!fs.existsSync(dir)) {
      console.error(`   ❌ Directory missing: ${dir}`);
      continue;
    }

    const files = fs.readdirSync(dir).filter(f => f.endsWith('.jpg') || f.endsWith('.png') || f.endsWith('.webp'));
    // Sort so hero is first, then gallery-02 through 06
    files.sort((a, b) => {
      if (a.includes('hero')) return -1;
      if (b.includes('hero')) return 1;
      return a.localeCompare(b);
    });

    console.log(`   Found ${files.length} local images in ${dir}`);

    // If already 6 images attached, skip or verify
    if (currentImages.length >= 6) {
      console.log(`   ✅ Already has 6 images attached. Skipping upload.`);
      continue;
    }

    // Identify which images are missing
    // We can upload the missing images
    const existingFileNames = currentImages.map(img => {
      // img.src contains filename
      return img.alt || path.basename(img.src.split('?')[0]);
    });

    for (let i = currentImages.length; i < files.length; i++) {
      const filename = files[i];
      const filePath = path.join(dir, filename);
      const b64 = fs.readFileSync(filePath).toString('base64');
      console.log(`   Uploading image [${i + 1}/${files.length}]: ${filename}...`);

      const uploadRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/products/${item.shopifyId}/images.json`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Shopify-Access-Token': token
        },
        body: JSON.stringify({
          image: {
            attachment: b64,
            filename: filename,
            position: i + 1,
            alt: `${item.title} - ${filename}`
          }
        })
      });

      if (uploadRes.ok) {
        const uData = await uploadRes.json();
        console.log(`   ✅ Uploaded image ID: ${uData.image.id}`);
      } else {
        console.error(`   ❌ Failed to upload ${filename} (${uploadRes.status}):`, await uploadRes.text());
      }
      await new Promise(r => setTimeout(r, 600)); // Respect Shopify rate limits
    }
  }

  console.log('\n🎉 Finished syncing media. Checking final image count on all 7 products:');
  for (const item of PRODUCTS_MAP) {
    const pRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/products/${item.shopifyId}/images.json`, {
      headers: { 'X-Shopify-Access-Token': token }
    });
    const pData = await pRes.json();
    console.log(`- ${item.title}: ${pData.images?.length} images attached on Shopify`);
  }
}

main().catch(console.error);

