import fs from 'fs';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || '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';

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const data = await res.json();
  return data.access_token;
}

async function updateProductVariants(token, productId, options, variants) {
  console.log(`Updating Product ID: ${productId}...`);
  // Update options and variants
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/products/${productId}.json`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      product: {
        id: productId,
        options: options,
        variants: variants
      }
    })
  });
  if (!res.ok) {
    console.error(`❌ Failed (${res.status}):`, await res.text());
    return false;
  }
  const data = await res.json();
  console.log(`✅ Successfully updated ${productId} with ${data.product.variants.length} variants!`);
  return true;
}

async function main() {
  const token = await getAccessToken();

  // 1. Product 01: Batana Hair Oil (15542795731129)
  // Single formula: 100% Pure Raw Batana Oil (60ml)
  await updateProductVariants(token, 15542795731129, [
    { name: "Treatment Course" }
  ], [
    {
      option1: "Buy 1 (1x 60ml Bottle - Starter Supply)",
      price: "39.99",
      compare_at_price: "49.99",
      sku: "ZVHC-BAT-60-1",
      inventory_policy: "continue"
    },
    {
      option1: "Buy 2 (2x 60ml Bottles - Duo Care Course - Save 30%)",
      price: "69.99",
      compare_at_price: "99.98",
      sku: "ZVHC-BAT-60-2",
      inventory_policy: "continue"
    },
    {
      option1: "Buy 3 (3x 60ml Bottles - Trio Restoration Course - Save 40%)",
      price: "89.99",
      compare_at_price: "149.97",
      sku: "ZVHC-BAT-60-3",
      inventory_policy: "continue"
    }
  ]);
  await new Promise(r => setTimeout(r, 600));

  // 2. Product 02: Hair Building Fibers 100g (15542795763897)
  // Shades: Black, Dark Brown, Medium Brown
  const fiberShades = ["Black", "Dark Brown", "Medium Brown"];
  const fiberTiers = [
    { name: "1x 100g Pouch (Starter)", price: "34.99", compare: "44.99" },
    { name: "2x 100g Pouches (Duo Pack - Save 30%)", price: "59.99", compare: "89.98" },
    { name: "3x 100g Pouches (Trio Bundle - Save 40%)", price: "79.99", compare: "134.97" }
  ];
  const fiberVariants = [];
  for (const s of fiberShades) {
    for (const t of fiberTiers) {
      fiberVariants.push({
        option1: s,
        option2: t.name,
        price: t.price,
        compare_at_price: t.compare,
        sku: `ZVHC-FIB-${s.substring(0, 2).toUpperCase()}-${t.name.substring(0, 2)}`,
        inventory_policy: "continue"
      });
    }
  }
  await updateProductVariants(token, 15542795763897, [
    { name: "Shade" },
    { name: "Treatment Course" }
  ], fiberVariants);
  await new Promise(r => setTimeout(r, 600));

  // 3. Product 04: Hairline Shadow Compact 4g (15542795862201)
  // Shades: #01 Black, #02 Dark Brown, #03 Medium Brown
  const hairlineShades = ["#01 Black", "#02 Dark Brown", "#03 Medium Brown"];
  const hairlineTiers = [
    { name: "1x 4g Compact (Starter Supply)", price: "24.99", compare: "32.00" },
    { name: "2x 4g Compacts (Duo Set - Save 30%)", price: "42.99", compare: "64.00" },
    { name: "3x 4g Compacts (Trio Set - Save 40%)", price: "54.99", compare: "96.00" }
  ];
  const hairlineVariants = [];
  for (const s of hairlineShades) {
    for (const t of hairlineTiers) {
      hairlineVariants.push({
        option1: s,
        option2: t.name,
        price: t.price,
        compare_at_price: t.compare,
        sku: `ZVHC-HLP-${s.substring(1, 3).toUpperCase()}-${t.name.substring(0, 2)}`,
        inventory_policy: "continue"
      });
    }
  }
  await updateProductVariants(token, 15542795862201, [
    { name: "Shade" },
    { name: "Treatment Course" }
  ], hairlineVariants);
  await new Promise(r => setTimeout(r, 600));

  console.log('\n🌟 Product variants and shade architectures updated cleanly!');
}

