import fs from 'fs';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || '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';

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const data = await res.json();
  return data.access_token;
}

const COLLECTIONS = [
  {
    title: 'Shop All Hair Care',
    handle: 'zvhc-all',
    body_html: '<p>Discover the complete Zavelyn Hair Care botanical ritual for curls, coils, scalp health, and instant cosmetic density.</p>',
    productIds: [15542795731129, 15542795763897, 15542795796665, 15542795862201, 15542795894969, 15542795927737, 15542795960505]
  },
  {
    title: 'Batana Scalp & Strand Ritual',
    handle: 'zvhc-batana',
    body_html: '<p>Pure unrefined cold-pressed Batana oil and melting scalp butters to deeply moisturize and strengthen fragile hair strands.</p>',
    productIds: [15542795731129, 15542795894969]
  },
  {
    title: 'Curl & Coily Care',
    handle: 'zvhc-curl',
    body_html: '<p>Nutrient-rich botanical conditioners and defining creams to shape 2A to 4C curl patterns with soft touchable bounce.</p>',
    productIds: [15542795927737]
  },
  {
    title: 'Scalp & Edge Care',
    handle: 'zvhc-scalp',
    body_html: '<p>Targeted botanical elixirs, melting balms, and pure oils formulated to nourish the scalp barrier and fortify thinning edges.</p>',
    productIds: [15542795731129, 15542795894969, 15542795960505]
  },
  {
    title: 'Instant Hair Coverage',
    handle: 'zvhc-coverage',
    body_html: '<p>Instant cosmetic density: electrostatic keratin building fibers, root-lift styling powders, and precision hairline shadow compacts.</p>',
    productIds: [15542795763897, 15542795796665, 15542795862201]
  }
];

async function main() {
  const token = await getAccessToken();
  console.log('✅ Access Token acquired for store dsdujr-vn.myshopify.com');

  // Check existing custom collections
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/custom_collections.json`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const data = await res.json();
  const existingMap = new Map((data.custom_collections || []).map(c => [c.handle, c]));

  for (const col of COLLECTIONS) {
    let colId;
    if (existingMap.has(col.handle)) {
      colId = existingMap.get(col.handle).id;
      console.log(`Collection ${col.handle} already exists (ID: ${colId}).`);
    } else {
      console.log(`Creating collection ${col.handle} (Draft/Unpublished)...`);
      const createRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/custom_collections.json`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Shopify-Access-Token': token
        },
        body: JSON.stringify({
          custom_collection: {
            title: col.title,
            handle: col.handle,
            body_html: col.body_html,
            published: false // Staged draft collection - not published to live store
          }
        })
      });
      if (!createRes.ok) {
        console.error(`❌ Failed (${createRes.status}):`, await createRes.text());
        continue;
      }
      const cData = await createRes.json();
      colId = cData.custom_collection.id;
      console.log(`✅ Created collection: ${col.title} (ID: ${colId}, Handle: ${col.handle})`);
    }

    // Add collects for products
    for (const pid of col.productIds) {
      const collectRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/collects.json`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Shopify-Access-Token': token
        },
        body: JSON.stringify({
          collect: {
            collection_id: colId,
            product_id: pid
          }
        })
      });
      // 422 if already collected
      if (collectRes.ok) {
        console.log(`   + Linked Product ID ${pid} to Collection ${col.handle}`);
      }
      await new Promise(r => setTimeout(r, 200));
    }
  }

  console.log('\n🌟 All 5 Hair Care collections created and products linked!');
}

main().catch(console.error);

