/**
 * ZAVELYN HAIR CARE — Bold Botanical Core Theme Stylesheet (v2.0)
 * Scoped under .zvhc-wrapper and zvhc- namespace
 * Target: dsdujr-vn.myshopify.com (Zavelyn Hair Care)
 * Palette: Saturated Orange (#FD550A), Botanical Green (#015D47), Electric Lime (#E0F354), Warm Ivory (#FFF9EE), Deep Forest (#172D20)
 */

:root {
  /* Approved Bold Botanical Color Tokens */
  --zvhc-orange: #FD550A;
  --zvhc-green: #015D47;
  --zvhc-lime: #E0F354;
  --zvhc-ivory: #FFF9EE;
  --zvhc-forest: #172D20;

  /* Color Distribution:
     - 50% Warm Ivory: product pages, negative space, editorial backgrounds
     - 25% Botanical Green: headers, headings, section dividers, brand blocks
     - 15% Vibrant Orange: campaign hero, primary CTAs, promotional highlights
     - 10% Electric Lime: offer badges, statement graphics, selected editorial accents
  */
  --zvhc-bg: var(--zvhc-ivory);
  --zvhc-bg-alt: #F7EFE2;
  --zvhc-card-bg: #FFFFFF;
  --zvhc-espresso: var(--zvhc-forest);
  --zvhc-cocoa: #234030;
  --zvhc-muted: #4B6354;
  --zvhc-border: #E5D8C8;
  --zvhc-border-light: #F0E6D8;

  --zvhc-copper: var(--zvhc-orange);
  --zvhc-copper-dark: #D44302;
  --zvhc-copper-light: #FFF0E8;
  --zvhc-gold: var(--zvhc-lime);

  --zvhc-botanical: var(--zvhc-green);
  --zvhc-botanical-light: #E6F3EE;
  --zvhc-burgundy-cta: var(--zvhc-orange);
  --zvhc-burgundy-cta-hover: #D44302;

  --zvhc-font-serif: "Playfair Display", "Cormorant Garamond", Georgia, serif;
  --zvhc-font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  --zvhc-radius-sm: 6px;
  --zvhc-radius-md: 10px;
  --zvhc-radius-lg: 16px;
  --zvhc-radius-full: 9999px;

  --zvhc-shadow-sm: 0 2px 8px rgba(23, 45, 32, 0.05);
  --zvhc-shadow-md: 0 8px 24px rgba(23, 45, 32, 0.08);
  --zvhc-shadow-lg: 0 16px 40px rgba(23, 45, 32, 0.12);
}

/* ==========================================================================
   GLOBAL HAIR CARE SCOPED BASE
   ========================================================================== */
.zvhc-wrapper {
  background-color: var(--zvhc-bg);
  color: var(--zvhc-forest);
  font-family: var(--zvhc-font-sans);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.zvhc-container {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 20px;
}

@media (min-width: 768px) {
  .zvhc-container {
    padding: 0 32px;
  }
}

/* Typography Helpers */
.zvhc-serif {
  font-family: var(--zvhc-font-serif);
}

.zvhc-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--zvhc-green);
}

.zvhc-heading-lg {
  font-family: var(--zvhc-font-serif);
  font-size: clamp(2.2rem, 5vw, 3.8rem);
  font-weight: 700;
  line-height: 1.1;
  color: var(--zvhc-forest);
  letter-spacing: -0.015em;
}

.zvhc-heading-md {
  font-family: var(--zvhc-font-serif);
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  font-weight: 700;
  line-height: 1.25;
  color: var(--zvhc-forest);
}

.zvhc-heading-sm {
  font-family: var(--zvhc-font-serif);
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.35;
  color: var(--zvhc-forest);
}

/* Button & Pill Styles */
.zvhc-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--zvhc-font-sans);
  font-weight: 700;
  font-size: 0.95rem;
  letter-spacing: 0.04em;
  padding: 14px 28px;
  border-radius: var(--zvhc-radius-md);
  text-decoration: none;
  cursor: pointer;
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  border: 1px solid transparent;
}

.zvhc-btn-primary {
  background-color: var(--zvhc-forest);
  color: #FFFFFF;
}

.zvhc-btn-primary:hover {
  background-color: var(--zvhc-green);
  color: var(--zvhc-lime);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(1, 93, 71, 0.25);
}

.zvhc-btn-secondary {
  background-color: transparent;
  color: var(--zvhc-forest);
  border: 2px solid var(--zvhc-forest);
}

.zvhc-btn-secondary:hover {
  background-color: var(--zvhc-forest);
  color: #FFFFFF;
  transform: translateY(-2px);
}

/* Lime Statement Badges */
.zvhc-lime-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background-color: var(--zvhc-lime);
  color: var(--zvhc-forest);
  font-weight: 800;
  font-size: 0.8rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 6px 14px;
  border-radius: var(--zvhc-radius-full);
}

/* ==========================================================================
   1. ANNOUNCEMENT BAR
   ========================================================================== */
.zvhc-announcement {
  background-color: var(--zvhc-green);
  color: var(--zvhc-ivory);
  font-size: 0.84rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-align: center;
  padding: 10px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

/* ==========================================================================
   2. HEADER & NAVIGATION
   ========================================================================== */
.zvhc-header {
  background-color: var(--zvhc-ivory);
  border-bottom: 1px solid var(--zvhc-border);
  position: sticky;
  top: 0;
  z-index: 1000;
  transition: all 0.2s ease;
}

.zvhc-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 74px;
}

.zvhc-logo {
  display: flex;
  flex-direction: column;
  text-decoration: none;
  line-height: 1;
}

.zvhc-logo-title {
  font-family: var(--zvhc-font-serif);
  font-size: 1.55rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  color: var(--zvhc-forest);
}

.zvhc-logo-sub {
  font-size: 0.64rem;
  font-weight: 800;
  letter-spacing: 0.24em;
  color: var(--zvhc-orange);
  text-transform: uppercase;
  margin-top: 2px;
}

.zvhc-nav {
  display: none;
}

@media (min-width: 992px) {
  .zvhc-nav {
    display: flex;
    align-items: center;
    gap: 28px;
  }
}

.zvhc-nav-link {
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--zvhc-forest);
  text-decoration: none;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  transition: color 0.2s ease;
}

.zvhc-nav-link:hover,
.zvhc-nav-link.active {
  color: var(--zvhc-orange);
}

.zvhc-header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.zvhc-bag-btn {
  background: transparent;
  border: none;
  cursor: pointer;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--zvhc-forest);
  padding: 8px;
  border-radius: var(--zvhc-radius-sm);
  transition: transform 0.2s ease;
}

.zvhc-bag-btn:hover {
  transform: scale(1.05);
}

.zvhc-bag-count {
  position: absolute;
  top: 2px;
  right: 2px;
  background: var(--zvhc-orange);
  color: #FFFFFF;
  font-size: 0.72rem;
  font-weight: 800;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.zvhc-mobile-menu-toggle {
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--zvhc-forest);
  padding: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
}

@media (min-width: 992px) {
  .zvhc-mobile-menu-toggle {
    display: none;
  }
}

/* ==========================================================================
   3. SIGNATURE CAMPAIGN HERO (BOLD ORANGE BOTANICAL)
   ========================================================================== */
.zvhc-hero {
  padding: 56px 0 80px;
  background-color: var(--zvhc-orange);
  color: #FFFFFF;
  position: relative;
  overflow: hidden;
}

.zvhc-hero-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 40px;
  align-items: center;
}

@media (min-width: 992px) {
  .zvhc-hero-grid {
    grid-template-columns: 1.1fr 0.9fr;
    gap: 56px;
  }
}

.zvhc-hero-badge {
  margin-bottom: 20px;
}

.zvhc-hero-title {
  color: #FFFFFF;
  font-size: clamp(2.5rem, 6vw, 4.25rem);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -0.02em;
  margin-bottom: 20px;
}

.zvhc-hero-title span {
  display: inline-block;
  color: var(--zvhc-lime);
  font-style: italic;
}

.zvhc-hero-subtitle {
  font-size: clamp(1.05rem, 1.8vw, 1.25rem);
  line-height: 1.6;
  color: var(--zvhc-ivory);
  max-width: 540px;
  margin-bottom: 32px;
}

.zvhc-hero-cta-group {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 36px;
}

.zvhc-hero .zvhc-btn-primary {
  background-color: var(--zvhc-forest);
  color: #FFFFFF;
  font-size: 1.05rem;
  padding: 16px 36px;
  border-radius: var(--zvhc-radius-full);
}

.zvhc-hero .zvhc-btn-primary:hover {
  background-color: var(--zvhc-green);
  color: var(--zvhc-lime);
}

.zvhc-hero .zvhc-btn-secondary {
  border: 2px solid #FFFFFF;
  color: #FFFFFF;
  font-size: 1.05rem;
  padding: 16px 32px;
  border-radius: var(--zvhc-radius-full);
}

.zvhc-hero .zvhc-btn-secondary:hover {
  background-color: #FFFFFF;
  color: var(--zvhc-forest);
}

.zvhc-hero-proof {
  display: flex;
  align-items: center;
  gap: 16px;
}

.zvhc-hero-avatars {
  display: flex;
  align-items: center;
}

.zvhc-hero-avatars img {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid #FFFFFF;
  margin-left: -10px;
  object-fit: cover;
}

.zvhc-hero-avatars img:first-child {
  margin-left: 0;
}

.zvhc-hero-proof-text {
  font-size: 0.85rem;
  line-height: 1.4;
  color: var(--zvhc-ivory);
}

.zvhc-hero-proof-text span {
  display: block;
  font-weight: 800;
  color: var(--zvhc-lime);
  letter-spacing: 0.04em;
}

.zvhc-hero-media {
  position: relative;
}

.zvhc-hero-img-wrap {
  position: relative;
  border-radius: var(--zvhc-radius-lg);
  overflow: hidden;
  box-shadow: 0 20px 50px rgba(23, 45, 32, 0.3);
  background: var(--zvhc-ivory);
}

.zvhc-hero-img-wrap img {
  width: 100%;
  height: auto;
  aspect-ratio: 1;
  object-fit: cover;
  display: block;
}

.zvhc-hero-floating-card {
  position: absolute;
  bottom: 20px;
  left: 20px;
  background: rgba(23, 45, 32, 0.92);
  backdrop-filter: blur(8px);
  border-radius: var(--zvhc-radius-md);
  padding: 14px 18px;
  display: flex;
  align-items: center;
  gap: 12px;
  color: #FFFFFF;
  box-shadow: var(--zvhc-shadow-md);
  border: 1px solid rgba(255, 255, 255, 0.15);
}

.zvhc-floating-icon {
  background: var(--zvhc-lime);
  color: var(--zvhc-forest);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

/* ==========================================================================
   4. MARQUEE TICKER (DEEP FOREST & LIME)
   ========================================================================== */
.zvhc-marquee {
  background-color: var(--zvhc-forest);
  color: var(--zvhc-ivory);
  overflow: hidden;
  white-space: nowrap;
  padding: 16px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.zvhc-marquee-track {
  display: inline-flex;
  gap: 40px;
  animation: zvhcMarqueeScroll 28s linear infinite;
}

.zvhc-marquee-item {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-weight: 800;
  font-size: 0.88rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.zvhc-marquee-item span:first-child {
  color: var(--zvhc-lime);
}

@keyframes zvhcMarqueeScroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ==========================================================================
   5. SHOP BY CONCERN SECTION
   ========================================================================== */
.zvhc-concern-section {
  padding: 80px 0;
  background-color: var(--zvhc-ivory);
}

.zvhc-section-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 52px;
}

.zvhc-concern-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}

.zvhc-concern-card {
  background: #FFFFFF;
  border-radius: var(--zvhc-radius-lg);
  overflow: hidden;
  border: 1px solid var(--zvhc-border);
  box-shadow: var(--zvhc-shadow-sm);
  text-decoration: none;
  color: var(--zvhc-forest);
