import { spawn } from 'child_process';
import fs from 'fs';

const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const tempDir = 'C:\\Users\\Admin\\AppData\\Local\\Temp\\chrome_cdp_zvhc_v2';

if (!fs.existsSync(tempDir)) {
  fs.mkdirSync(tempDir, { recursive: true });
}

const chromeProc = spawn(chromePath, [
  '--headless=new',
  '--remote-debugging-port=9224',
  `--user-data-dir=${tempDir}`,
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check'
], { detached: false });

async function main() {
  await new Promise(r => setTimeout(r, 2500));

  let tabs;
  for (let i = 0; i < 5; i++) {
    try {
      const res = await fetch('http://127.0.0.1:9224/json');
      tabs = await res.json();
      break;
    } catch (e) {
      await new Promise(r => setTimeout(r, 1000));
    }
  }

  if (!tabs || tabs.length === 0) {
    console.error('No tabs found!');
    chromeProc.kill();
    return;
  }

  const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);
  let id = 1;
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const curId = id++;
      const handler = (evt) => {
        const msg = JSON.parse(evt.data.toString());
        if (msg.id === curId) {
          ws.removeEventListener('message', handler);
          if (msg.error) reject(msg.error);
          else resolve(msg.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id: curId, method, params }));
    });
  }

  ws.addEventListener('open', async () => {
    try {
      await send('Page.enable');
      await send('DOM.enable');
      await send('Network.enable');

      const THEME_ID = '189127983289';

      // 1. Initialize preview session on draft theme
      console.log('Navigating to draft preview theme init...');
      await send('Page.navigate', { url: `https://tryzavelyn.com/?preview_theme_id=${THEME_ID}` });
      await new Promise(r => setTimeout(r, 4000));

      // 2. Capture Desktop Homepage (1440px)
      console.log('Capturing Desktop Homepage (1440px)...');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 1440,
        height: 900,
        deviceScaleFactor: 1,
        mobile: false
      });
      await send('Page.navigate', { url: `https://tryzavelyn.com/` });
      await new Promise(r => setTimeout(r, 3500));
      const ssDesktopHome = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
      fs.writeFileSync('scratch/zvhc_v2_homepage_desktop.png', Buffer.from(ssDesktopHome.data, 'base64'));
      console.log('✅ Saved scratch/zvhc_v2_homepage_desktop.png');

      // 3. Capture Mobile Homepage (390px)
      console.log('Capturing Mobile Homepage (390px)...');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 390,
        height: 844,
        deviceScaleFactor: 2,
        mobile: true
      });
      await send('Emulation.setUserAgentOverride', {
        userAgent: 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.6 Mobile/15E148 Safari/604.1'
      });
      await send('Page.navigate', { url: `https://tryzavelyn.com/` });
      await new Promise(r => setTimeout(r, 3500));
      const ssMobileHome = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
      fs.writeFileSync('scratch/zvhc_v2_homepage_mobile.png', Buffer.from(ssMobileHome.data, 'base64'));
      console.log('✅ Saved scratch/zvhc_v2_homepage_mobile.png');

      // 4. Capture Mobile Scroll: 7 Products & 4-Step Ritual
      console.log('Capturing Mobile Sections (Products & Ritual)...');
      await send('Runtime.evaluate', { expression: 'window.scrollTo(0, 1600);' });
      await new Promise(r => setTimeout(r, 1500));
      const ssMobileProducts = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
      fs.writeFileSync('scratch/zvhc_v2_mobile_products.png', Buffer.from(ssMobileProducts.data, 'base64'));
      console.log('✅ Saved scratch/zvhc_v2_mobile_products.png');

      // 5. Capture Mobile Scroll: Bundles & Comparison
      console.log('Capturing Mobile Bundles & Comparison...');
      await send('Runtime.evaluate', { expression: 'window.scrollTo(0, 3200);' });
      await new Promise(r => setTimeout(r, 1500));
      const ssMobileBundles = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
      fs.writeFileSync('scratch/zvhc_v2_mobile_bundles.png', Buffer.from(ssMobileBundles.data, 'base64'));
      console.log('✅ Saved scratch/zvhc_v2_mobile_bundles.png');

      // 6. Capture Protected Legacy Product (Breakout Holster) Desktop
      console.log('Capturing Protected Legacy Holster Funnel (Desktop)...');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 1440,
        height: 900,
        deviceScaleFactor: 1,
        mobile: false
      });
      await send('Page.navigate', { url: `https://tryzavelyn.com/products/breakout-2-0-holster-built-for-maximum-concealment-copy` });
      await new Promise(r => setTimeout(r, 3500));
      const ssLegacyHolster = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
      fs.writeFileSync('scratch/zvhc_v2_legacy_holster.png', Buffer.from(ssLegacyHolster.data, 'base64'));
      console.log('✅ Saved scratch/zvhc_v2_legacy_holster.png');

      // 7. Capture Protected Legacy Rehabilitation Glove Desktop
      console.log('Capturing Protected Legacy Rehab Glove (Desktop)...');
      await send('Page.navigate', { url: `https://tryzavelyn.com/products/zavelyn-rehabilitation-glove` });
      await new Promise(r => setTimeout(r, 3500));
      const ssLegacyRehab = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
      fs.writeFileSync('scratch/zvhc_v2_legacy_rehab.png', Buffer.from(ssLegacyRehab.data, 'base64'));
      console.log('✅ Saved scratch/zvhc_v2_legacy_rehab.png');

      console.log('\n🎉 ALL SCREENSHOTS CAPTURED SUCCESSFULLY!');
    } catch (err) {
      console.error('Error during capture:', err);
    } finally {
      ws.close();
      chromeProc.kill();
    }
  });
}

main().catch(console.error);

