}
const docsV3Dir = 'docs/haircare/v3';
if (!fs.existsSync(docsV3Dir)) {
  fs.mkdirSync(docsV3Dir, { recursive: true });
}

const chromeProc = spawn(chromePath, [
  '--headless=new',
  '--remote-debugging-port=9226',
  `--user-data-dir=${tempDir}`,
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check'
], { detached: false });

async function main() {
  await new Promise(r => setTimeout(r, 2500));

  let tabs;
  for (let i = 0; i < 5; i++) {
    try {
      const res = await fetch('http://127.0.0.1:9226/json');
      tabs = await res.json();
      break;
    } catch (e) {
      await new Promise(r => setTimeout(r, 1000));
    }
  }

  if (!tabs || tabs.length === 0) {
    console.error('No tabs found!');
    chromeProc.kill();
    return;
  }

  const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);
  let id = 1;
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const curId = id++;
      const handler = (evt) => {
        const msg = JSON.parse(evt.data.toString());
        if (msg.id === curId) {
          ws.removeEventListener('message', handler);
          if (msg.error) reject(msg.error);
          else resolve(msg.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id: curId, method, params }));
    });
  }

  ws.addEventListener('open', async () => {
    try {
      await send('Page.enable');
      await send('DOM.enable');
      await send('Runtime.enable');

      const targetUrl = 'https://shopsidek.com/templates/t01/';
      console.log(`Navigating to ${targetUrl}...`);

      // 1. Desktop View (1440x900)
      await send('Emulation.setDeviceMetricsOverride', {
        width: 1440,
        height: 900,
        deviceScaleFactor: 1,
        mobile: false
      });

      await send('Page.navigate', { url: targetUrl });
      await new Promise(r => setTimeout(r, 5000));

      console.log('Capturing Desktop Viewport & Full Page...');
      const ssDesktop = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
      fs.writeFileSync(path.join(outDir, 't01_desktop_hero.png'), Buffer.from(ssDesktop.data, 'base64'));

      // Extract detailed computed styles, colors, layout metrics
      const auditResult = await send('Runtime.evaluate', {
        expression: `(() => {
          const bodyStyle = window.getComputedStyle(document.body);

          // Elements detection
          const header = document.querySelector('header') || document.querySelector('.header') || document.querySelector('[class*="header"]');
          const announcement = document.querySelector('[class*="announcement"]') || document.querySelector('[class*="banner"]');
          const buyBox = document.querySelector('[class*="buy"]') || document.querySelector('[class*="product-form"]') || document.querySelector('form[action*="/cart/add"]');
          const primaryBtn = document.querySelector('button[type="submit"]') || document.querySelector('[class*="btn-primary"]') || document.querySelector('[class*="add-to-cart"]');
          const bundleCards = Array.from(document.querySelectorAll('[class*="bundle"], [class*="tier"], [class*="offer-card"], [class*="variant-card"]'));
          const headings = Array.from(document.querySelectorAll('h1, h2, h3'));
          const container = document.querySelector('.container') || document.querySelector('[class*="container"]') || document.querySelector('main');

          function getStyleData(el) {
            if (!el) return null;
            const cs = window.getComputedStyle(el);
            return {
              tagName: el.tagName,
              className: el.className,
              color: cs.color,
              backgroundColor: cs.backgroundColor,
              fontFamily: cs.fontFamily,
              fontSize: cs.fontSize,
              fontWeight: cs.fontWeight,
              lineHeight: cs.lineHeight,
              letterSpacing: cs.letterSpacing,
              padding: cs.padding,
              margin: cs.margin,
              border: cs.border,
              borderRadius: cs.borderRadius,
              boxShadow: cs.boxShadow,
              maxWidth: cs.maxWidth,
              width: cs.width
            };
          }

          return {
            title: document.title,
            body: {
              backgroundColor: bodyStyle.backgroundColor,
              color: bodyStyle.color,
              fontFamily: bodyStyle.fontFamily,
              fontSize: bodyStyle.fontSize
            },
            header: getStyleData(header),
            announcement: getStyleData(announcement),
            primaryBtn: getStyleData(primaryBtn),
            bundleCardCount: bundleCards.length,
            sampleBundleCard: getStyleData(bundleCards[0]),
            container: getStyleData(container),
            headings: headings.slice(0, 5).map(h => ({
              tag: h.tagName,
              text: h.textContent.trim().slice(0, 50),
              fontFamily: window.getComputedStyle(h).fontFamily,
              fontSize: window.getComputedStyle(h).fontSize,
              fontWeight: window.getComputedStyle(h).fontWeight,
              color: window.getComputedStyle(h).color
            })),
            colorsFound: Array.from(new Set(
              Array.from(document.querySelectorAll('*')).flatMap(el => {
                const s = window.getComputedStyle(el);
                return [s.color, s.backgroundColor, s.borderColor];
              }).filter(c => c && c !== 'rgba(0, 0, 0, 0)' && c !== 'transparent')
            )).slice(0, 25),
            htmlSnippet: document.body.innerHTML.slice(0, 4000)
          };
        })()`,
        returnByValue: true
      });

      console.log('Audit Extracted from T01 Reference:');
      console.log(JSON.stringify(auditResult.result?.value, null, 2).slice(0, 1500));
      fs.writeFileSync(path.join(outDir, 't01_audit_data.json'), JSON.stringify(auditResult.result?.value, null, 2));

      // 2. Mobile View (390x844)
      console.log('Capturing Mobile View (390px)...');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 390,
        height: 844,
        deviceScaleFactor: 2,
        mobile: true
      });
      await send('Emulation.setUserAgentOverride', {
        userAgent: 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.6 Mobile/15E148 Safari/604.1'
      });
      await send('Page.navigate', { url: targetUrl });
      await new Promise(r => setTimeout(r, 4000));

      const ssMobile = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
      fs.writeFileSync(path.join(outDir, 't01_mobile_hero.png'), Buffer.from(ssMobile.data, 'base64'));

      console.log('✅ Reference audit and screenshots completed successfully!');
    } catch (err) {
      console.error('Error during T01 audit:', err);
    } finally {
      ws.close();
      chromeProc.kill();
    }
  });
}

main().catch(console.error);

