          // Find ATC button
          const atcBtn = document.querySelector('button.kc-atc-btn, [class*="atc"], [class*="add-to-cart"], button[type="submit"]');
          const atcStyle = atcBtn ? window.getComputedStyle(atcBtn) : null;

          // Find Buy Box container
          const buyBox = document.querySelector('.kc-product, [class*="product-form"], [class*="main-product"]');
          const buyBoxStyle = buyBox ? window.getComputedStyle(buyBox) : null;

          // Find Gallery
          const gallery = document.querySelector('.kc-gallery, [class*="gallery"]');
          const galleryStyle = gallery ? window.getComputedStyle(gallery) : null;

          // Find Sticky Bar
          const sticky = document.querySelector('[class*="sticky"]');
          const stickyStyle = sticky ? window.getComputedStyle(sticky) : null;

          // Find all sections
          const sections = Array.from(document.querySelectorAll('section, [class*="sec-"]')).map(s => ({
            className: s.className,
            id: s.id,
            heading: s.querySelector('h1, h2, h3')?.textContent.trim() || '',
            bg: window.getComputedStyle(s).backgroundColor
          }));

          // Find bundle card details
          const tiers = Array.from(document.querySelectorAll('.kc-tier, [class*="tier"]')).map(t => {
