          return {
            atcButton: atcStyle ? {
              text: atcBtn.textContent.trim(),
              backgroundColor: atcStyle.backgroundColor,
              color: atcStyle.color,
              borderRadius: atcStyle.borderRadius,
              padding: atcStyle.padding,
              fontSize: atcStyle.fontSize,
              fontWeight: atcStyle.fontWeight,
              boxShadow: atcStyle.boxShadow,
              height: atcStyle.height
            } : null,
            sections: sections,
            tiers: tiers,
            upsell: upsellStyle ? {
              bg: upsellStyle.backgroundColor,
              border: upsellStyle.border,
              radius: upsellStyle.borderRadius
            } : null
          };
        })()`,
        returnByValue: true
      });

      console.log('Detailed Audit:', JSON.stringify(detailedAudit.result?.value, null, 2));
      fs.writeFileSync('scratch/t01_reference/t01_detailed_audit.json', JSON.stringify(detailedAudit.result?.value, null, 2));

    } catch (e) {
      console.error(e);
    } finally {
      ws.close();
      chromeProc.kill();
    }
  });
}

main().catch(console.error);

