# SHOPSIDEK T01 — DESIGN TOKENS SPECIFICATION

This document outlines the official design tokens extracted directly from `https://shopsidek.com/templates/t01/` to serve as the single source of truth for the Zavelyn Hair Care V3 design reset.

---

## 1. COLOR TOKENS

```css
:root {
  /* Canvas & Backgrounds */
  --zvhc-t01-bg: #E9E4E6;              /* Main page background */
  --zvhc-t01-bg-alt: #FBEDE8;          /* Warm peach/rose secondary section background */
  --zvhc-t01-bg-card: #FFFFFF;         /* White card & container background */
  --zvhc-t01-header-bg: #1B1418;       /* Deep obsidian/plum header */

  /* Text & Typography */
  --zvhc-t01-text-main: #2B1B24;       /* Primary dark plum text */
  --zvhc-t01-text-muted: #5A4651;      /* Secondary descriptive text */
  --zvhc-t01-text-subtle: #7A6670;     /* Tertiary captions & labels */
  --zvhc-t01-text-light: #FFFFFF;      /* Inverted white text */

  /* Primary Action & Brand Accents */
  --zvhc-t01-cta-bg: #6B1E46;          /* Deep berry / plum CTA button */
  --zvhc-t01-cta-hover: #521636;       /* CTA hover state */
  --zvhc-t01-cta-shadow: rgba(107, 30, 70, 0.45);
  --zvhc-t01-accent-rose: #B0476E;     /* Rose active borders & badges */
  --zvhc-t01-card-sel-bg: #FDF2F6;     /* Selected bundle card tint */
  --zvhc-t01-pill-bg: #F8E4EB;         /* Offer & discount pill background */

  /* Borders & Dividers */
  --zvhc-t01-border: #EAD7DD;          /* Default soft card/input border */
  --zvhc-t01-border-subtle: #F0E6E9;   /* Subtle divider lines */

  /* Status & Functional */
  --zvhc-t01-star-gold: #E0A33A;       /* Verified star rating gold */
  --zvhc-t01-trust-green: #3F8F6B;     /* Free shipping & verified check green */
}
```

---

## 2. TYPOGRAPHY TOKENS

```css
:root {
  /* Font Families */
  --zvhc-font-serif: 'Fraunces', Georgia, serif;
  --zvhc-font-sans: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;

  /* Font Sizes */
  --zvhc-fs-h1: clamp(2rem, 3.5vw, 2.4rem);   /* 32px - 38px */
  --zvhc-fs-h2: clamp(1.8rem, 3vw, 2.6rem);     /* 28px - 42px */
  --zvhc-fs-h3: clamp(1.2rem, 2vw, 1.5rem);     /* 19px - 24px */
  --zvhc-fs-body: 1rem;                         /* 16px */
  --zvhc-fs-sm: 0.875rem;                       /* 14px */
  --zvhc-fs-xs: 0.75rem;                        /* 12px */
}
```

---

## 3. GEOMETRY & ELEVATION

```css
:root {
  /* Radii */
  --zvhc-radius-btn: 12px;
  --zvhc-radius-card: 14px;
  --zvhc-radius-pill: 9999px;
  --zvhc-radius-img: 16px;

  /* Shadows */
  --zvhc-shadow-btn: 0 10px 24px -10px var(--zvhc-t01-cta-shadow);
  --zvhc-shadow-card: 0 4px 16px rgba(43, 27, 36, 0.04);
  --zvhc-shadow-sticky: 0 -4px 20px rgba(43, 27, 36, 0.08);

  /* Container */
  --zvhc-container-max: 1180px;
  --zvhc-container-pad: 20px;
}
```

/**
 * ZAVELYN HAIR CARE — T01 Design Tokens Specification
 * Directly extracted from ShopSideK T01 reference (https://shopsidek.com/templates/t01/)
 */

:root {
  /* Canvas & Backgrounds */
  --zvhc-t01-bg: #E9E4E6;              /* Main page background */
  --zvhc-t01-bg-alt: #FBEDE8;          /* Warm peach/rose secondary section background */
  --zvhc-t01-bg-card: #FFFFFF;         /* Pure white card & container background */
  --zvhc-t01-header-bg: #1B1418;       /* Deep obsidian/plum header */

  /* Text & Typography */
  --zvhc-t01-text-main: #2B1B24;       /* Primary dark plum text */
  --zvhc-t01-text-muted: #5A4651;      /* Secondary descriptive text */
  --zvhc-t01-text-subtle: #7A6670;     /* Tertiary captions & labels */
  --zvhc-t01-text-light: #FFFFFF;      /* Inverted white text */

  /* Primary Action & Brand Accents */
  --zvhc-t01-cta-bg: #6B1E46;          /* Deep berry / plum CTA button */
  --zvhc-t01-cta-hover: #521636;       /* CTA hover state */
  --zvhc-t01-cta-shadow: rgba(107, 30, 70, 0.45);
  --zvhc-t01-accent-rose: #B0476E;     /* Rose active borders & badges */
  --zvhc-t01-card-sel-bg: #FDF2F6;     /* Selected bundle card tint */
  --zvhc-t01-pill-bg: #F8E4EB;         /* Offer & discount pill background */

  /* Borders & Dividers */
  --zvhc-t01-border: #EAD7DD;          /* Default soft card/input border */
  --zvhc-t01-border-subtle: #F0E6E9;   /* Subtle divider lines */

  /* Status & Functional */
  --zvhc-t01-star-gold: #E0A33A;       /* Verified star rating gold */
  --zvhc-t01-trust-green: #3F8F6B;     /* Free shipping & verified check green */

  /* Typography Families */
  --zvhc-font-serif: 'Fraunces', Georgia, serif;
  --zvhc-font-sans: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;

  /* Elevation & Geometry */
  --zvhc-radius-btn: 12px;
  --zvhc-radius-card: 14px;
  --zvhc-radius-pill: 9999px;
  --zvhc-radius-img: 16px;

  --zvhc-container-max: 1180px;
}

/**
 * ZAVELYN HAIR CARE — T01 Core Stylesheet
 * Scoped strictly to .zvhc-wrapper
 */

@import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400..900;1,9..144,400..900&family=Inter:wght@300;400;500;600;700;800&display=swap');

.zvhc-wrapper {
  background-color: var(--zvhc-t01-bg, #E9E4E6);
  color: var(--zvhc-t01-text-main, #2B1B24);
  font-family: var(--zvhc-font-sans, 'Inter', system-ui, -apple-system, sans-serif);
  font-size: 16px;
  line-height: 1.5;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.zvhc-wrapper * {
  box-sizing: border-box;
}

.zvhc-container {
  width: 100%;
  max-width: var(--zvhc-container-max, 1180px);
  margin-left: auto;
  margin-right: auto;
  padding-left: 20px;
  padding-right: 20px;
}

/* Headings */
.zvhc-wrapper h1,
.zvhc-wrapper h2,
.zvhc-wrapper h3,
.zvhc-wrapper .zvhc-h1,
.zvhc-wrapper .zvhc-h2,
.zvhc-wrapper .zvhc-h3 {
  font-family: var(--zvhc-font-serif, 'Fraunces', Georgia, serif);
  color: var(--zvhc-t01-text-main, #2B1B24);
  font-weight: 600;
  margin: 0 0 16px;
  line-height: 1.18;
}

.zvhc-wrapper h1,
.zvhc-wrapper .zvhc-h1 {
  font-size: clamp(2rem, 3.8vw, 2.5rem);
  letter-spacing: -0.02em;
}

.zvhc-wrapper h2,
.zvhc-wrapper .zvhc-h2 {
  font-size: clamp(1.8rem, 3.2vw, 2.6rem);
  letter-spacing: -0.01em;
}

.zvhc-wrapper h3,
.zvhc-wrapper .zvhc-h3 {
  font-size: clamp(1.2rem, 2vw, 1.5rem);
}

.zvhc-wrapper p {
  color: var(--zvhc-t01-text-muted, #5A4651);
  margin: 0 0 16px;
  line-height: 1.55;
}

.zvhc-wrapper a {
  color: inherit;
  text-decoration: none;
  transition: opacity 0.2s ease;
}

.zvhc-wrapper a:hover {
  opacity: 0.85;
}

/* Base Buttons */
.zvhc-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background-color: var(--zvhc-t01-cta-bg, #6B1E46);
  color: #FFFFFF !important;
  font-family: var(--zvhc-font-sans, 'Inter', sans-serif);
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  height: 56px;
  padding: 0 32px;
  border-radius: var(--zvhc-radius-btn, 12px);
  border: none;
  cursor: pointer;
  box-shadow: 0 10px 24px -10px rgba(107, 30, 70, 0.55);
  transition: all 0.2s ease;
  width: 100%;
  text-align: center;
}

.zvhc-btn-primary:hover {
  background-color: var(--zvhc-t01-cta-hover, #521636);
  transform: translateY(-1px);
  box-shadow: 0 14px 28px -10px rgba(107, 30, 70, 0.65);
}

.zvhc-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background-color: transparent;
  color: var(--zvhc-t01-text-main, #2B1B24);
  font-family: var(--zvhc-font-sans, 'Inter', sans-serif);
  font-size: 15px;
  font-weight: 700;
  height: 52px;
  padding: 0 28px;
  border-radius: var(--zvhc-radius-btn, 12px);
  border: 1.5px solid var(--zvhc-t01-border, #EAD7DD);
  cursor: pointer;
  transition: all 0.2s ease;
}

.zvhc-btn-secondary:hover {
  background-color: #FFFFFF;
  border-color: var(--zvhc-t01-accent-rose, #B0476E);
}

/**
 * ZAVELYN HAIR CARE — T01 PDP Stylesheet
 * Faithfully reproduces ShopSideK T01 Product Buy Box and PDP Sections
 */

.zvhc-pdp-section {
  padding: 32px 0 64px;
  background-color: var(--zvhc-t01-bg, #E9E4E6);
}

@media (min-width: 992px) {
  .zvhc-pdp-section {
    padding: 48px 0 80px;
  }
}

.zvhc-pdp-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 32px;
}

@media (min-width: 992px) {
  .zvhc-pdp-grid {
    grid-template-columns: 1.1fr 0.9fr;
    gap: 52px;
    align-items: start;
  }
}

/* Gallery */
.zvhc-gallery {
  position: relative;
}

@media (min-width: 992px) {
  .zvhc-gallery {
    position: sticky;
    top: 96px;
  }
}

.zvhc-main-image-wrap {
  position: relative;
  border-radius: var(--zvhc-radius-img, 16px);
  overflow: hidden;
  background-color: var(--zvhc-t01-bg-card, #FFFFFF);
  border: 1px solid var(--zvhc-t01-border, #EAD7DD);
  aspect-ratio: 1/1;
  box-shadow: 0 4px 20px rgba(43, 27, 36, 0.05);
}

.zvhc-main-image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.zvhc-thumbs-row {
  display: flex;
  gap: 10px;
  margin-top: 14px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.zvhc-thumb-item {
  width: 72px;
  height: 72px;
  flex-shrink: 0;
  border-radius: 12px;
  overflow: hidden;
  cursor: pointer;
  border: 1.5px solid var(--zvhc-t01-border, #EAD7DD);
  background: #FFFFFF;
  transition: all 0.2s ease;
}

.zvhc-thumb-item.is-active,
.zvhc-thumb-item:hover {
  border-color: var(--zvhc-t01-accent-rose, #B0476E);
}

.zvhc-thumb-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Buy Box Column */
.zvhc-buybox {
  display: flex;
  flex-direction: column;
}

.zvhc-reviews-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--zvhc-t01-text-muted, #5A4651);
}

.zvhc-stars {
  color: var(--zvhc-t01-star-gold, #E0A33A);
  letter-spacing: 2px;
  font-size: 1.1rem;
}

.zvhc-pdp-title {
  font-family: var(--zvhc-font-serif, 'Fraunces', serif);
  font-size: clamp(2rem, 3.2vw, 2.45rem);
  color: var(--zvhc-t01-text-main, #2B1B24);
  font-weight: 600;
  line-height: 1.15;
  margin: 0 0 12px;
  letter-spacing: -0.02em;
}

.zvhc-pdp-subtitle {
  font-size: 0.95rem;
  color: var(--zvhc-t01-text-muted, #5A4651);
  line-height: 1.5;
  margin-bottom: 20px;
}

/* Bullet Benefits */
.zvhc-benefits-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 24px;
}

.zvhc-benefit-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.92rem;
  font-weight: 500;
  color: var(--zvhc-t01-text-main, #2B1B24);
}

.zvhc-benefit-item svg {
  color: var(--zvhc-t01-trust-green, #3F8F6B);
  flex-shrink: 0;
}

/* Shade Swatches (for Fibers & Hairline Compact) */
.zvhc-shade-box {
  background: #FFFFFF;
  border: 1px solid var(--zvhc-t01-border, #EAD7DD);
  border-radius: var(--zvhc-radius-card, 14px);
  padding: 16px 18px;
  margin-bottom: 18px;
}

.zvhc-shade-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
  font-size: 0.85rem;
}

.zvhc-shade-header span:first-child {
  font-weight: 700;
  color: var(--zvhc-t01-text-main, #2B1B24);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.zvhc-shade-header span:last-child {
  font-weight: 700;
  color: var(--zvhc-t01-accent-rose, #B0476E);
}

.zvhc-swatches-grid {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.zvhc-swatch-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 9999px;
  background: var(--zvhc-t01-bg, #E9E4E6);
  border: 1.5px solid transparent;
  cursor: pointer;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--zvhc-t01-text-main, #2B1B24);
  transition: all 0.2s ease;
}

.zvhc-swatch-btn.is-active,
.zvhc-swatch-btn:hover {
  border-color: var(--zvhc-t01-accent-rose, #B0476E);
  background: #FFFFFF;
}

.zvhc-swatch-dot {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  display: inline-block;
  box-shadow: inset 0 0 0 1px rgba(0,0,0,0.15);
}

/* T01 BUNDLE CARDS (.kc-tier) */
.zvhc-bundle-group {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 22px;
}

.zvhc-bundle-card {
  position: relative;
  background: var(--zvhc-t01-bg-card, #FFFFFF);
  border: 1px solid var(--zvhc-t01-border, #EAD7DD);
  border-radius: var(--zvhc-radius-card, 14px);
  padding: 18px 20px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.zvhc-bundle-card:hover {
  border-color: var(--zvhc-t01-accent-rose, #B0476E);
}

.zvhc-bundle-card.is-selected {
  border: 2px solid var(--zvhc-t01-accent-rose, #B0476E);
  background: var(--zvhc-t01-card-sel-bg, #FDF2F6);
}

.zvhc-tier-badge {
  position: absolute;
  top: -11px;
  right: 18px;
  background: var(--zvhc-t01-accent-rose, #B0476E);
  color: #FFFFFF;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  padding: 3px 12px;
  border-radius: 9999px;
  text-transform: uppercase;
}

.zvhc-tier-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.zvhc-tier-left {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-grow: 1;
}

.zvhc-radio-circle {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid var(--zvhc-t01-border, #EAD7DD);
  display: flex;
