import fs from 'fs';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || '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';

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const data = await res.json();
  return data.access_token;
}

async function main() {
  const token = await getAccessToken();
  const headers = {
    'X-Shopify-Access-Token': token,
    'Content-Type': 'application/json'
  };

  // 1. Fetch all products
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/products.json?limit=250`, { headers });
  const data = await res.json();
  const products = data.products;

  console.log(`Fetched ${products.length} products total.`);

  // 2. Identify 7 Hair Care products
  const haircareProducts = products.filter(p => p.handle.startsWith('zvhc-'));
  console.log(`\nFound ${haircareProducts.length} Hair Care products:`);
  haircareProducts.forEach(p => {
    console.log(`\n=== [${p.id}] ${p.title} (${p.handle}) ===`);
    console.log(`Status: ${p.status} | Template suffix: "${p.template_suffix}" | Options: ${JSON.stringify(p.options)}`);
    p.variants.forEach(v => {
      console.log(`  Variant ID: ${v.id} | SKU: "${v.sku}" | Title: "${v.title}" | Price: $${v.price} | CompareAt: ${v.compare_at_price ? '$' + v.compare_at_price : 'null'} | Opts: [${v.option1}, ${v.option2}, ${v.option3}]`);
    });
  });

  // 3. Identify legacy products
  const testHandles = [
    'breakout-2-0-holster-built-for-maximum-concealment-copy',
    'zavelyn-rehabilitation-glove',
    'babiguard-protection',
    'babiguard-head-protector',
    'yeoman-tactical-belt',
    'the-yeoman-sweep',
    'botanaroots-growth-oil',
    'zavelyn-botanaroots-organic-batana-hair-growth-oil'
  ];

  console.log('\n--- Checking Specific Legacy Handles ---');
  testHandles.forEach(h => {
    const found = products.find(p => p.handle === h);
    if (found) {
      console.log(`✅ MATCH FOUND: "${h}" -> ID: ${found.id}, Title: "${found.title}", Status: ${found.status}`);
    } else {
      console.log(`❌ NOT FOUND: "${h}"`);
    }
  });

  console.log('\n--- Fuzzy search all legacy products in store ---');
  products.forEach(p => {
    const lower = (p.title + ' ' + p.handle).toLowerCase();
    if (lower.includes('babi') || lower.includes('yeoman') || lower.includes('botana') || lower.includes('holster') || lower.includes('rehab')) {
      console.log(`* Product [${p.id}]: "${p.title}" | handle: "/products/${p.handle}" | status: ${p.status} | template_suffix: "${p.template_suffix}"`);
    }
  });

  fs.writeFileSync('scratch/v3_1_products_audit.json', JSON.stringify({
    haircareProducts,
    allProducts: products.map(p => ({ id: p.id, title: p.title, handle: p.handle, status: p.status, variants_count: p.variants.length, variants: p.variants.map(v => ({ id: v.id, title: v.title, price: v.price, compare_at_price: v.compare_at_price, option1: v.option1, option2: v.option2, option3: v.option3 })) }))
  }, null, 2));

  console.log('\nSaved audit to scratch/v3_1_products_audit.json');
}

main().catch(console.error);

