}

// 1. Load store product audit
const auditData = JSON.parse(fs.readFileSync('scratch/v3_1_products_audit.json', 'utf8'));
const haircareProducts = auditData.haircareProducts;

console.log(`Loaded ${haircareProducts.length} Hair Care products from audit.`);

// 2. Unit test the zvhcFindVariant logic across all variants
function mockZvhcFindVariant(productData, tier, shade) {
  if (!productData || !productData.variants || productData.variants.length === 0) return null;
  var options = productData.options || [];
  var shadeOptPos = -1;
  var tierOptPos = -1;

  options.forEach(function(opt, idx) {
    var name = (typeof opt === 'string' ? opt : (opt.name || '')).toLowerCase();
    if (name === 'shade' || name === 'color') {
      shadeOptPos = idx + 1;
    } else if (name === 'treatment course' || name === 'title' || name === 'quantity' || name === 'pack') {
      tierOptPos = idx + 1;
    }
  });

  if (tierOptPos === -1) {
    tierOptPos = (shadeOptPos === 1) ? 2 : 1;
  }

