        lowerTierVal.indexOf(tierPrefix2.toLowerCase()) !== -1 ||
        lowerTierVal.indexOf(tierPrefix3.toLowerCase()) !== -1 ||
        lowerTierVal.indexOf('(' + tier + 'x') !== -1) {
      tierMatches = true;
    }

    if (!tierMatches) return false;

    if (shadeKey && shade) {
      var vShadeVal = v[shadeKey];
