  let tabs;
  for (let i = 0; i < 5; i++) {
    try {
      const res = await fetch('http://127.0.0.1:9230/json');
      tabs = await res.json();
      break;
    } catch (e) {
      await new Promise(r => setTimeout(r, 1000));
    }
  }

  if (!tabs || tabs.length === 0) {
    chromeProc.kill();
    return;
  }

  const ws = new WebSocket(tabs[0].webSocketDebuggerUrl);
  let id = 1;
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const curId = id++;
      const handler = (evt) => {
        const msg = JSON.parse(evt.data.toString());
        if (msg.id === curId) {
          ws.removeEventListener('message', handler);
          if (msg.error) reject(msg.error);
          else resolve(msg.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id: curId, method, params }));
    });
  }

  ws.addEventListener('open', async () => {
    try {
      await send('Page.enable');
      await send('DOM.enable');
      await send('Network.enable');

      const THEME_ID = '189127983289';

      console.log('Navigating to Batana Oil active PDP on draft preview...');
      await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false });
      await send('Page.navigate', { url: `https://tryzavelyn.com/products/zvhc-batana-hair-growth-oil?preview_theme_id=${THEME_ID}` });
      await new Promise(r => setTimeout(r, 3500));
      const ssBatana = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/zvhc_active_batana_pdp.png', Buffer.from(ssBatana.data, 'base64'));
      console.log('✅ Saved scratch/zvhc_active_batana_pdp.png');

      console.log('Navigating to Fibers active PDP (with shades) on draft preview...');
      await send('Page.navigate', { url: `https://tryzavelyn.com/products/zvhc-keratin-hair-building-fibers?preview_theme_id=${THEME_ID}` });
      await new Promise(r => setTimeout(r, 3500));
      const ssFibers = await send('Page.captureScreenshot', { format: 'png' });
      fs.writeFileSync('scratch/zvhc_active_fibers_pdp.png', Buffer.from(ssFibers.data, 'base64'));
      console.log('✅ Saved scratch/zvhc_active_fibers_pdp.png');

      console.log('🎉 Active product PDP screenshots captured successfully!');
    } catch (err) {
      console.error('CDP error:', err);
    } finally {
      ws.close();
      chromeProc.kill();
      process.exit(0);
    }
  });
}

main().catch(err => {
  console.error(err);
  chromeProc.kill();
  process.exit(1);
});

