#!/usr/bin/env node
/**
 * BROWSER PROCESS SAFETY GUARD (PreToolUse Hook)
 * 
 * Intercepts run_command tool calls before execution.
 * Blocks any global/unconstrained browser termination commands (e.g. Stop-Process, taskkill /IM)
 * that could inadvertently kill personal Google Chrome windows.
 */

import fs from 'fs';

function isUnsafeBrowserCommand(cmd) {
  if (!cmd || typeof cmd !== 'string') return false;

  const unsafePatterns = [
    // PowerShell: Stop-Process targeting chrome
    /Stop-Process\s+.*(?:-Name|-ProcessName|\s+)?["']?\*?chrome\*?["']?/i,
    /Get-Process\s+.*chrome.*\|.*Stop-Process/i,
    /Stop-Process.*\(Get-Process.*chrome.*\)/i,

    // Windows: taskkill targeting chrome by image name
    /taskkill(?:\.exe)?\s+.*(?:\/IM|\/im|-im)\s+["']?\*?chrome(?:\.exe)?\*?["']?/i,

    // Linux/macOS/Git Bash: pkill or killall targeting chrome
    /(?:pkill|killall)\s+.*chrome/i,

    // Broader wildcard termination on browser executables
    /Stop-Process\s+.*(?:-Name|-ProcessName|\s+)?["']?\*?(?:msedge|brave|firefox|opera)\*?["']?/i,
    /taskkill(?:\.exe)?\s+.*(?:\/IM|\/im|-im)\s+["']?\*?(?:msedge|brave|firefox|opera)(?:\.exe)?\*?["']?/i
  ];

  return unsafePatterns.some(pattern => pattern.test(cmd));
}

async function main() {
  let rawInput = '';

  try {
    rawInput = fs.readFileSync(0, 'utf8');
  } catch (err) {
    // If stdin cannot be read, allow execution safely
    console.log(JSON.stringify({ decision: 'allow' }));
    process.exit(0);
  }

  let parsed = null;
  try {
    parsed = JSON.parse(rawInput);
  } catch (e) {
    // If not JSON, check if raw string contains unsafe command
    if (isUnsafeBrowserCommand(rawInput)) {
      console.log(JSON.stringify({
        decision: 'deny',
        reason: 'CRITICAL SAFETY GUARD: Unconstrained browser termination command detected and blocked.'
      }));
      process.exit(0);
    }
    console.log(JSON.stringify({ decision: 'allow' }));
    process.exit(0);
  }

  const toolCall = parsed.toolCall || parsed;
  const toolName = toolCall.name || parsed.toolName;
  const args = toolCall.args || parsed.args || {};
  const cmd = args.CommandLine || args.commandLine || args.command || '';

  if (toolName === 'run_command' && isUnsafeBrowserCommand(cmd)) {
    const response = {
      decision: 'deny',
      reason: `SAFETY GUARD BLOCKED EXECUTION:\nCommand: "${cmd}"\nReason: Global browser process termination is strictly prohibited. Killing browsers by executable name (e.g. 'chrome.exe') risks closing the user's personal browser sessions and tabs. You must only terminate specific child PIDs spawned and owned by the current automation session.`
    };
    console.log(JSON.stringify(response));
    process.exit(0);
  }

  // Default: Allow safe tool execution
  console.log(JSON.stringify({ decision: 'allow' }));
  process.exit(0);
}

main().catch(() => {
  console.log(JSON.stringify({ decision: 'allow' }));
  process.exit(0);
});

{
  "browser-process-guard": {
    "enabled": true,
    "PreToolUse": [
      {
        "matcher": "run_command",
        "hooks": [
          {
            "type": "command",
            "command": "node ./scripts/guard_browser_process.mjs",
            "timeout": 10
          }
        ]
      }
    ]
  },
  "chat-auto-backup": {
    "enabled": true,
    "Stop": [
      {
        "type": "command",
        "command": "node ./scripts/backup_chat_session.mjs --hook",
        "timeout": 60
      }
    ]
  }
}

/**
 * Safe Browser Session Manager
 * Ensures 100% process isolation, dynamic port selection without killing port owners,
 * and verified single-PID cleanup.
 */

import net from 'net';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { spawn } from 'child_process';

/**
 * Checks if a TCP port is free without modifying any process.
 */
export function isPortFree(port) {
  return new Promise((resolve) => {
    const server = net.createServer();
    server.once('error', () => {
      resolve(false);
    });
    server.once('listening', () => {
      server.close(() => resolve(true));
    });
    server.listen(port, '127.0.0.1');
  });
}

/**
 * Finds the first free port in a range.
 * If preferred port is busy, increments safely. NEVER kills the process holding the port!
 */
export async function findFreePort(startPort = 9230, maxAttempts = 20) {
  for (let p = startPort; p < startPort + maxAttempts; p++) {
    const free = await isPortFree(p);
    if (free) return p;
  }
  throw new Error(`No free port found between ${startPort} and ${startPort + maxAttempts}`);
}

/**
 * Launches an isolated headless Chrome instance.
 */
export async function launchSafeBrowser({
  chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
  preferredPort = 9230,
  width = 1440,
  height = 900
} = {}) {
  // 1. Find an available port safely
  const port = await findFreePort(preferredPort);

  // 2. Create isolated unique temporary profile
  const sessionDir = path.join(os.tmpdir(), `zvhc_safe_browser_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`);
  fs.mkdirSync(sessionDir, { recursive: true });

  // 3. Spawn process
  const args = [
    '--headless=new',
    `--remote-debugging-port=${port}`,
    `--user-data-dir=${sessionDir}`,
    '--disable-gpu',
    '--no-first-run',
    '--no-default-browser-check',
    `--window-size=${width},${height}`
  ];

  const proc = spawn(chromePath, args, { detached: false });
  const pid = proc.pid;

  if (!pid) {
    throw new Error('Failed to spawn browser process');
  }

  // 4. Return session object with safe targeted cleanup
  return {
    proc,
    pid,
    port,
    userDataDir: sessionDir,
    async close() {
      // ONLY kill the exact PID spawned by this session
      try {
        if (proc && !proc.killed) {
          proc.kill();
        }
      } catch (err) {
        console.error(`Error closing browser PID ${pid}:`, err);
      }

      // Safe clean up of temp dir
      try {
        if (fs.existsSync(sessionDir)) {
          fs.rmSync(sessionDir, { recursive: true, force: true, maxRetries: 3 });
        }
      } catch {}
    }
  };
}

/**
 * STATIC & MOCKED TEST SUITE FOR BROWSER SAFETY GUARD
 * Verifies that all dangerous termination patterns are blocked and safe automation runs isolated.
 * Does NOT terminate or restart any real external browsers.
 */

import { spawnSync } from 'child_process';
import net from 'net';
import os from 'os';
import path from 'path';
import { isPortFree, findFreePort } from './lib/safe_browser_session.mjs';

function runGuard(inputObj) {
  const inputStr = JSON.stringify(inputObj);
  const res = spawnSync('node', ['./scripts/guard_browser_process.mjs'], {
    input: inputStr,
    encoding: 'utf8'
  });
  try {
    return JSON.parse(res.stdout.trim());
  } catch (e) {
    return { error: e.message, stdout: res.stdout, stderr: res.stderr };
  }
}

async function runTests() {
  console.log('=== STARTING BROWSER SAFETY GUARD TEST SUITE ===\n');
  let passed = 0;
  let failed = 0;

  function assert(condition, message) {
    if (condition) {
      console.log(`✅ PASS: ${message}`);
      passed++;
    } else {
      console.error(`❌ FAIL: ${message}`);
      failed++;
    }
  }

  // TEST 1: All known browser-wide termination commands are detected and prohibited
  console.log('--- Test Suite 1: Prohibited Command Detection ---');

  const dangerousCommands = [
    'Get-Process chrome | Stop-Process',
    'Get-Process chrome -ErrorAction SilentlyContinue | Stop-Process -Force',
    'Stop-Process -Name "chrome" -Force',
    'Stop-Process -Name chrome',
    'Stop-Process -ProcessName chrome -Force',
    'taskkill /F /IM chrome.exe',
    'taskkill /im chrome.exe /f',
    'taskkill.exe /IM *chrome* /F',
    'pkill chrome',
    'killall chrome',
    'Stop-Process -Name "msedge"',
    'taskkill /IM brave.exe /F'
  ];

  dangerousCommands.forEach(cmd => {
    const result = runGuard({
      toolCall: {
        name: 'run_command',
        args: { CommandLine: cmd }
      }
    });
    assert(result.decision === 'deny', `Blocked unsafe command: "${cmd}"`);
  });

  // TEST 2: Safe and legitimate commands are permitted
  console.log('\n--- Test Suite 2: Legitimate Commands Permitted ---');

  const safeCommands = [
    'git status',
    'node scratch/test.mjs',
    'taskkill /PID 12345 /T /F',
    'Stop-Process -Id 12345',
    'Get-Process -Id 12345',
    'Get-NetTCPConnection -LocalPort 9226',
    'echo "hello world"'
  ];

  safeCommands.forEach(cmd => {
    const result = runGuard({
      toolCall: {
        name: 'run_command',
        args: { CommandLine: cmd }
      }
    });
    assert(result.decision === 'allow', `Allowed safe command: "${cmd}"`);
  });

  // TEST 3: Port Conflict Never Triggers Process Termination
  console.log('\n--- Test Suite 3: Port Conflict Non-Interference ---');

  const testPort = 19876;
  const dummyServer = net.createServer();

  await new Promise((resolve) => {
    dummyServer.listen(testPort, '127.0.0.1', () => {
      console.log(`Mock server listening on port ${testPort} (simulating occupied port)`);
      resolve();
    });
  });

  // Check that testPort is reported as not free
  const portFreeBefore = await isPortFree(testPort);
  assert(portFreeBefore === false, `Port ${testPort} correctly detected as occupied`);

  // Call findFreePort starting at testPort
  const chosenPort = await findFreePort(testPort);
  assert(chosenPort > testPort, `Safely shifted to alternate port ${chosenPort} without touching ${testPort}`);

  // Verify dummy server is still alive and running (was NOT terminated!)
  assert(dummyServer.listening === true, `Occupied port ${testPort} remained completely untouched and active`);

  dummyServer.close();

  // TEST 4: Isolated Temporary Directory Security
  console.log('\n--- Test Suite 4: Profile Isolation & Path Confinement ---');

  const tempBase = os.tmpdir();
  const personalProfilePath = path.join(process.env.LOCALAPPDATA || '', 'Google', 'Chrome', 'User Data');

  const simulatedSessionDir = path.join(tempBase, `zvhc_safe_browser_${Date.now()}`);
  assert(simulatedSessionDir.startsWith(tempBase), 'Browser session directory resides strictly in system temp directory');
  assert(!simulatedSessionDir.includes(personalProfilePath), 'Browser session directory is 100% isolated from personal Chrome profile');

  console.log(`\n=== TEST SUMMARY: ${passed} PASSED | ${failed} FAILED ===`);
  if (failed > 0) {
    process.exit(1);
  }
}

runTests().catch(err => {
  console.error('Test execution failed:', err);
  process.exit(1);
});

