import fs from 'fs';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || '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';
const DRAFT_THEME_ID = 189127983289;

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const data = await res.json();
  return data.access_token;
}

async function putAsset(token, key, content) {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${DRAFT_THEME_ID}/assets.json`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({ asset: { key, value: content } })
  });
  if (!res.ok) {
    const text = await res.text();
    console.error(`❌ Failed ${key} (${res.status}): ${text}`);
    return false;
  }
  const data = await res.json();
  console.log(`✅ Uploaded: ${key} (${data.asset?.size} bytes) to Theme ${DRAFT_THEME_ID}`);
  return true;
}

async function verifyStorefrontHtml() {
  const initRes = await fetch(`https://tryzavelyn.com/?preview_theme_id=${DRAFT_THEME_ID}`, { redirect: 'manual' });
  const raw = initRes.headers.getSetCookie ? initRes.headers.getSetCookie() : [initRes.headers.get('set-cookie')];
  const cookie = raw && raw[0] ? raw[0].split(';')[0] : '';

  const handles = [
    'zvhc-batana-hair-growth-oil',
    'zvhc-keratin-hair-building-fibers',
    'zvhc-root-lift-styling-powder',
    'zvhc-precision-hairline-compact',
    'zvhc-raw-batana-scalp-balm',
    'zvhc-botanical-curl-cream',
    'zvhc-7-in-1-growth-elixir'
  ];

  console.log('\n--- Verifying Rendered HTML for All 7 Products ---');
  let allPass = true;
  for (const h of handles) {
    const res = await fetch(`https://tryzavelyn.com/products/${h}?preview_theme_id=${DRAFT_THEME_ID}`, {
      headers: { 'Cookie': cookie }
    });
    const html = await res.text();
    const hasPaymentSection = html.includes('zvhc-payment-methods');
    const hasVisa = html.includes('aria-labelledby="pi-visa"') || html.includes('title="Visa"') || html.includes('visa');
    const hasMaster = html.includes('title="Master"');
    const hasAmex = html.includes('title="American express"');
    const hasApplePay = html.includes('title="Apple pay"');
    const hasGooglePay = html.includes('title="Google pay"');
    const hasShopifyPay = html.includes('title="Shopify pay"');
    const hasDiscover = html.includes('title="Discover"');
    const hasPaypal = html.includes('title="Paypal"');

    const pass = hasPaymentSection && hasVisa && hasMaster && hasAmex && hasApplePay && hasGooglePay && hasShopifyPay;
    console.log(`Product [${h}]: ${pass ? '✅ PASS' : '❌ FAIL'} | hasPaymentSection: ${hasPaymentSection} | Visa: ${hasVisa} | Amex: ${hasAmex} | ApplePay: ${hasApplePay} | ShopPay: ${hasShopifyPay}`);
    if (!pass) allPass = false;
  }
  return allPass;
}

async function main() {
  const token = await getAccessToken();
  console.log('Access token acquired. Deploying payment icons to Draft Theme:', DRAFT_THEME_ID);

  const pdpMain = fs.readFileSync('sections/zvhc-pdp-main.liquid', 'utf8');
  await putAsset(token, 'sections/zvhc-pdp-main.liquid', pdpMain);

  const pdpCss = fs.readFileSync('assets/zvhc-t01-pdp.css', 'utf8');
  await putAsset(token, 'assets/zvhc-t01-pdp.css', pdpCss);

  const verified = await verifyStorefrontHtml();
  if (verified) {
    console.log('\n🎉 ALL 7 PRODUCTS CONFIRMED TO RENDER SHOPIFY PAYMENT ICONS SUCCESSFULLY!');
  } else {
    console.error('\n⚠️ Verification failed for some products.');
  }
}

main().catch(console.error);

