import fs from 'fs';
import path from 'path';
import { launchSafeBrowser } from '../scripts/lib/safe_browser_session.mjs';

const ARTIFACT_DIR = 'C:\\Users\\Admin\\.gemini\\antigravity\\brain\\2f3e6b33-be3a-4971-95cb-b168e69dafef';
const THEME_ID = '189127983289';

async function main() {
  console.log('Launching safe isolated browser session...');
  const session = await launchSafeBrowser({ preferredPort: 9245, width: 1440, height: 1000 });
  console.log(`Browser launched on port ${session.port} with isolated PID ${session.pid}`);

  try {
    await new Promise(r => setTimeout(r, 2000));
    const resTabs = await fetch(`http://127.0.0.1:${session.port}/json`);
    const tabs = await resTabs.json();
    const pageTab = tabs.find(t => t.type === 'page');
    if (!pageTab) throw new Error('No page tab found in Chrome session');

    const ws = new WebSocket(pageTab.webSocketDebuggerUrl);
    await new Promise((resolve, reject) => {
      ws.addEventListener('open', resolve);
      ws.addEventListener('error', reject);
    });

    let id = 1;
    function send(method, params = {}) {
      return new Promise((resolve, reject) => {
        const curId = id++;
        const handler = (evt) => {
          const msg = JSON.parse(evt.data.toString());
          if (msg.id === curId) {
            ws.removeEventListener('message', handler);
            if (msg.error) reject(msg.error);
            else resolve(msg.result);
          }
        };
        ws.addEventListener('message', handler);
        ws.send(JSON.stringify({ id: curId, method, params }));
      });
    }

    await send('Page.enable');
    await send('DOM.enable');
    await send('Network.enable');

    // 1. Initialize draft theme preview session
    console.log('Navigating to preview theme init...');
    await send('Page.navigate', { url: `https://tryzavelyn.com/?preview_theme_id=${THEME_ID}` });
    await new Promise(r => setTimeout(r, 3500));

    // 2. Navigate to Batana Hair Growth Oil PDP
    console.log('Navigating to Batana Hair Growth Oil PDP on Draft Theme...');
    await send('Page.navigate', { url: `https://tryzavelyn.com/products/zvhc-batana-hair-growth-oil?preview_theme_id=${THEME_ID}` });
    await new Promise(r => setTimeout(r, 4000));

    // 3. Desktop screenshot of the Buy Box & Payment Icons
    await send('Emulation.setDeviceMetricsOverride', {
      width: 1440,
      height: 1000,
      deviceScaleFactor: 2,
      mobile: false
    });
    await new Promise(r => setTimeout(r, 1000));

    // Scroll to the trust strip / payment icons area
    const evalRes = await send('Runtime.evaluate', {
      expression: `(() => {
        const btn = document.querySelector('#zvhcAddToCartBtn');
        const pay = document.querySelector('.zvhc-payment-methods');
        if (btn) {
          btn.scrollIntoView({ behavior: 'instant', block: 'center' });
        }
        const rect = pay ? pay.getBoundingClientRect() : null;
        return {
          hasPay: !!pay,
          iconsCount: pay ? pay.querySelectorAll('.zvhc-payment-badge').length : 0,
          rect
        };
      })()`,
      returnByValue: true
    });
    console.log('DOM Evaluation:', evalRes.result?.value);
    await new Promise(r => setTimeout(r, 1500));

    const desktopShot = await send('Page.captureScreenshot', { format: 'png' });
    const desktopPath = path.join(ARTIFACT_DIR, 'evidence_pdp_payment_icons_desktop.png');
    fs.writeFileSync(desktopPath, Buffer.from(desktopShot.data, 'base64'));
    console.log(`✅ Saved Desktop screenshot: ${desktopPath}`);

    // 4. Mobile screenshot (375x812)
    console.log('Configuring mobile viewport (375x812)...');
    await send('Emulation.setDeviceMetricsOverride', {
      width: 375,
      height: 812,
      deviceScaleFactor: 2,
      mobile: true
    });
    await new Promise(r => setTimeout(r, 1000));

    await send('Runtime.evaluate', {
      expression: `(() => {
        const strip = document.querySelector('.zvhc-trust-strip');
        if (strip) {
          strip.scrollIntoView({ behavior: 'instant', block: 'center' });
        }
      })()`
    });
    await new Promise(r => setTimeout(r, 1500));

    const mobileShot = await send('Page.captureScreenshot', { format: 'png' });
    const mobilePath = path.join(ARTIFACT_DIR, 'evidence_pdp_payment_icons_mobile.png');
    fs.writeFileSync(mobilePath, Buffer.from(mobileShot.data, 'base64'));
    console.log(`✅ Saved Mobile screenshot: ${mobilePath}`);

    ws.close();
  } finally {
    console.log('Closing safe browser session cleanly...');
    await session.close();
    console.log('Safe browser session closed.');
  }
}

main().catch(err => {
  console.error('Fatal error in capture script:', err);
  process.exit(1);
});

