import fs from 'fs';
import path from 'path';
import { launchSafeBrowser } from '../scripts/lib/safe_browser_session.mjs';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || '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';
const DRAFT_THEME_ID = 189127983289;
const ARTIFACT_DIR = 'C:\\Users\\Admin\\.gemini\\antigravity\\brain\\2f3e6b33-be3a-4971-95cb-b168e69dafef';

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const data = await res.json();
  return data.access_token;
}

async function putAsset(token, key, content) {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${DRAFT_THEME_ID}/assets.json`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({ asset: { key, value: content } })
  });
  if (!res.ok) {
    const text = await res.text();
    console.error(`❌ Failed ${key} (${res.status}): ${text}`);
    return false;
  }
  const data = await res.json();
  console.log(`✅ Uploaded: ${key} (${data.asset?.size} bytes) to Theme ${DRAFT_THEME_ID}`);
  return true;
}

async function verifyHtml() {
  const initRes = await fetch(`https://tryzavelyn.com/?preview_theme_id=${DRAFT_THEME_ID}`, { redirect: 'manual' });
  const raw = initRes.headers.getSetCookie ? initRes.headers.getSetCookie() : [initRes.headers.get('set-cookie')];
  const cookie = raw && raw[0] ? raw[0].split(';')[0] : '';

  const handles = [
    'zvhc-batana-hair-growth-oil',
    'zvhc-keratin-hair-building-fibers',
    'zvhc-root-lift-styling-powder',
    'zvhc-precision-hairline-compact',
    'zvhc-raw-batana-scalp-balm',
    'zvhc-botanical-curl-cream',
    'zvhc-7-in-1-growth-elixir'
  ];

  console.log('\n--- Verifying Rendered HTML for All 7 Products ---');
  let allPass = true;
  for (const h of handles) {
    const res = await fetch(`https://tryzavelyn.com/products/${h}?preview_theme_id=${DRAFT_THEME_ID}`, {
      headers: { 'Cookie': cookie }
    });
    const html = await res.text();
    const hasShipping = html.includes('zvhc-doorstep-delivery') || html.includes('Doorstep Delivery Guarantee');
    const shippingIdx = html.indexOf('zvhc-doorstep-delivery');
    const footerIdx = html.indexOf('zvhc-t01-footer');
    const isBeforeFooter = shippingIdx > 0 && footerIdx > 0 && shippingIdx < footerIdx;

    const pass = hasShipping && isBeforeFooter;
    console.log(`Product [${h}]: ${pass ? '✅ PASS' : '❌ FAIL'} | hasShipping: ${hasShipping} | isBeforeFooter: ${isBeforeFooter} (pos: ${shippingIdx} < ${footerIdx})`);
    if (!pass) allPass = false;
  }
  return allPass;
}

async function captureEvidence() {
  console.log('\n--- Capturing Safe Browser Visual Evidence ---');
  const session = await launchSafeBrowser({ preferredPort: 9248, width: 1440, height: 1000 });
  console.log(`Browser launched on port ${session.port} with isolated PID ${session.pid}`);

  try {
    await new Promise(r => setTimeout(r, 2000));
    const resTabs = await fetch(`http://127.0.0.1:${session.port}/json`);
    const tabs = await resTabs.json();
    const pageTab = tabs.find(t => t.type === 'page');
    if (!pageTab) throw new Error('No page tab found');

    const ws = new WebSocket(pageTab.webSocketDebuggerUrl);
    await new Promise((resolve, reject) => {
      ws.addEventListener('open', resolve);
      ws.addEventListener('error', reject);
    });

    let id = 1;
    function send(method, params = {}) {
      return new Promise((resolve, reject) => {
        const curId = id++;
        const handler = (evt) => {
          const msg = JSON.parse(evt.data.toString());
          if (msg.id === curId) {
            ws.removeEventListener('message', handler);
            if (msg.error) reject(msg.error);
            else resolve(msg.result);
          }
        };
        ws.addEventListener('message', handler);
        ws.send(JSON.stringify({ id: curId, method, params }));
      });
    }

    await send('Page.enable');
    await send('DOM.enable');
    await send('Network.enable');

    // 1. Initialize draft theme preview session
    await send('Page.navigate', { url: `https://tryzavelyn.com/?preview_theme_id=${DRAFT_THEME_ID}` });
    await new Promise(r => setTimeout(r, 3500));

    // 2. Navigate to Batana Hair Growth Oil PDP
    await send('Page.navigate', { url: `https://tryzavelyn.com/products/zvhc-batana-hair-growth-oil?preview_theme_id=${DRAFT_THEME_ID}` });
    await new Promise(r => setTimeout(r, 4500));

    // 3. Desktop screenshot
    await send('Emulation.setDeviceMetricsOverride', {
      width: 1440,
      height: 1000,
      deviceScaleFactor: 2,
      mobile: false
    });
    await new Promise(r => setTimeout(r, 1000));

    // Scroll to the Doorstep Delivery section
    await send('Runtime.evaluate', {
      expression: `(() => {
        const sec = document.querySelector('#zvhc-doorstep-delivery');
        if (sec) {
          sec.scrollIntoView({ behavior: 'instant', block: 'center' });
        }
      })()`
    });
    await new Promise(r => setTimeout(r, 1500));

    const desktopShot = await send('Page.captureScreenshot', { format: 'png' });
    const desktopPath = path.join(ARTIFACT_DIR, 'evidence_doorstep_delivery_desktop.png');
    fs.writeFileSync(desktopPath, Buffer.from(desktopShot.data, 'base64'));
    console.log(`✅ Saved Desktop screenshot: ${desktopPath}`);

    // 4. Mobile screenshot (375x812)
    await send('Emulation.setDeviceMetricsOverride', {
      width: 375,
      height: 812,
      deviceScaleFactor: 2,
      mobile: true
    });
    await new Promise(r => setTimeout(r, 1000));

    await send('Runtime.evaluate', {
      expression: `(() => {
        const sec = document.querySelector('#zvhc-doorstep-delivery');
        if (sec) {
          sec.scrollIntoView({ behavior: 'instant', block: 'start' });
        }
      })()`
    });
    await new Promise(r => setTimeout(r, 1500));

    const mobileShot = await send('Page.captureScreenshot', { format: 'png' });
    const mobilePath = path.join(ARTIFACT_DIR, 'evidence_doorstep_delivery_mobile.png');
    fs.writeFileSync(mobilePath, Buffer.from(mobileShot.data, 'base64'));
    console.log(`✅ Saved Mobile screenshot: ${mobilePath}`);

    ws.close();
  } finally {
    console.log('Closing safe browser session cleanly...');
    await session.close();
    console.log('Safe browser session closed.');
  }
}

async function main() {
  const token = await getAccessToken();
  console.log('Access token acquired. Deploying Doorstep Delivery section to Draft Theme:', DRAFT_THEME_ID);

  // 1. Upload section
  const sectionContent = fs.readFileSync('sections/zvhc-pdp-shipping.liquid', 'utf8');
  await putAsset(token, 'sections/zvhc-pdp-shipping.liquid', sectionContent);

  // 2. Upload all 7 product templates
  const templates = [
    'templates/product.zvhc-batana.json',
    'templates/product.zvhc-fibers.json',
    'templates/product.zvhc-powder.json',
    'templates/product.zvhc-hairline.json',
    'templates/product.zvhc-balm.json',
    'templates/product.zvhc-curl.json',
    'templates/product.zvhc-7in1.json'
  ];

  for (const t of templates) {
    const content = fs.readFileSync(t, 'utf8');
    await putAsset(token, t, content);
  }

  // 3. Verify HTML on storefront
  const verified = await verifyHtml();
  if (verified) {
    console.log('\n🎉 ALL 7 PRODUCTS CONFIRMED TO RENDER DOORSTEP DELIVERY SECTION BEFORE FOOTER!');
  } else {
    console.error('\n⚠️ HTML verification failed for some products.');
  }

  // 4. Capture visual evidence
  await captureEvidence();
}

main().catch(console.error);

import fs from 'fs';
import path from 'path';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || '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';
const DRAFT_THEME_ID = 189127983289;
const LIVE_THEME_ID = 187597717689;

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const data = await res.json();
  return data.access_token;
}

async function main() {
  const token = await getAccessToken();
  console.log('Access token acquired. Auditing Draft Theme:', DRAFT_THEME_ID);

  // 1. Verify Draft Theme and Live Theme existence and names
  const themeRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes.json`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const themes = (await themeRes.json()).themes;
  const draftTheme = themes.find(t => t.id === DRAFT_THEME_ID);
  const liveTheme = themes.find(t => t.role === 'main');
  console.log(`Live Theme: ID ${liveTheme.id} ("${liveTheme.name}") - ${liveTheme.id === LIVE_THEME_ID ? 'PROTECTED ID CONFIRMED' : 'WARNING MISMATCH'}`);
  console.log(`Target Draft Theme: ID ${draftTheme.id} ("${draftTheme.name}") - role: ${draftTheme.role}`);

  // 2. Fetch list of all assets on Draft Theme
  const assetsRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${DRAFT_THEME_ID}/assets.json`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const assets = (await assetsRes.json()).assets;
  console.log(`Total assets on Draft Theme: ${assets.length}`);

  // Sort assets by updated_at descending
  assets.sort((a, b) => new Date(b.updated_at) - new Date(a.updated_at));
  console.log('\nTop 20 most recently updated assets on Draft Theme:');
  for (let i = 0; i < Math.min(20, assets.length); i++) {
    console.log(`- ${assets[i].key} (updated: ${assets[i].updated_at}, size: ${assets[i].size})`);
  }

  // 3. Create backup directory for draft theme
  const backupDir = path.join(process.cwd(), 'backups', `draft_theme_pre_v3_2_${Date.now()}`);
  fs.mkdirSync(backupDir, { recursive: true });

  // 4. Specifically check key files that we might touch or that owner may have edited
  const keysToCheck = [
    'sections/zvhc-header.liquid',
    'sections/zvhc-footer.liquid',
    'sections/zavelyn-track-order.liquid',
    'sections/zvhc-pdp-main.liquid',
    'sections/zvhc-pdp-shipping.liquid',
    'templates/index.json',
    'templates/page.track-order.json',
    'templates/page.our-story.json',
    'layout/theme.liquid',
    'config/settings_data.json'
  ];

  console.log('\nComparing key theme assets with local repository...');
  const diffReport = [];

  for (const key of keysToCheck) {
    const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${DRAFT_THEME_ID}/assets.json?asset[key]=${encodeURIComponent(key)}`, {
      headers: { 'X-Shopify-Access-Token': token }
    });
    if (!res.ok) {
      console.log(`- ${key}: Remote does not exist (${res.status})`);
      continue;
    }
    const assetData = (await res.json()).asset;
    const remoteValue = assetData.value || '';

    // Save to backup
    const backupFilePath = path.join(backupDir, key.replace(/\//g, '__'));
    fs.writeFileSync(backupFilePath, remoteValue, 'utf8');

    // Compare with local if exists
    if (fs.existsSync(key)) {
      const localValue = fs.readFileSync(key, 'utf8');
      if (remoteValue.trim() === localValue.trim()) {
        console.log(`- ${key}: 100% MATCH with local`);
      } else {
        console.log(`- ${key}: ⚠️ DIFFERENCE DETECTED! (Remote size: ${remoteValue.length}, Local size: ${localValue.length})`);
        diffReport.push({ key, remoteSize: remoteValue.length, localSize: localValue.length });
      }
    } else {
      console.log(`- ${key}: Exists remotely, not present locally (backed up)`);
    }
  }

  // Also check if any page named "our-story" or "track-order" exists in Shopify Admin Pages API
  const pagesRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/pages.json?limit=250`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const pages = (await pagesRes.json()).pages || [];
  console.log(`\nTotal Shopify Pages found: ${pages.length}`);
  for (const p of pages) {
    if (p.handle.includes('story') || p.handle.includes('track') || p.handle.includes('hair') || p.handle.includes('zvhc')) {
      console.log(`Page: ID ${p.id} | title: "${p.title}" | handle: "${p.handle}" | template_suffix: "${p.template_suffix}" | published_at: "${p.published_at}"`);
    }
  }

  // Check existing navigation menus (Linklists)
  const navRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/link_lists.json`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const linkLists = (await navRes.json()).link_lists || [];
  console.log(`\nShopify Navigation Menus (Link Lists): ${linkLists.length}`);
  for (const ll of linkLists) {
    console.log(`Menu: ID ${ll.id} | handle: "${ll.handle}" | title: "${ll.title}" | links: ${ll.links?.length}`);
  }

  console.log(`\n✓ Audit complete. Backup saved to ${backupDir}`);
}

main().catch(console.error);

