    body: JSON.stringify({ asset: { key: 'sections/zvhc-our-story.liquid', value: sectionContent } })
  });
  console.log('Uploaded sections/zvhc-our-story.liquid to Draft Theme');

  // Test storefront HTTP response
  const initRes = await fetch(`https://tryzavelyn.com/?preview_theme_id=${DRAFT_THEME_ID}`, { redirect: 'manual' });
  const raw = initRes.headers.getSetCookie ? initRes.headers.getSetCookie() : [initRes.headers.get('set-cookie')];
  const cookie = raw && raw[0] ? raw[0].split(';')[0] : '';

  const pageRes = await fetch(`https://tryzavelyn.com/pages/our-story?preview_theme_id=${DRAFT_THEME_ID}`, {
    headers: { 'Cookie': cookie }
  });
  console.log('Unpublished page storefront HTTP status:', pageRes.status);
  const html = await pageRes.text();
  console.log('HTML snippet contains "Care for Every Strand":', html.includes('Care for Every Strand'));
}

main().catch(console.error);

