const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || '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';

async function checkPublication() {
  const tokenRes = await fetch('https://' + SHOP_DOMAIN + '/admin/oauth/access_token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const { access_token } = await tokenRes.json();

  const query = `
    query {
      page(id: "gid://shopify/Page/169297248441") {
        id
        title
        handle
        isPublished
        templateSuffix
        body
      }
      publications(first: 10) {
        nodes {
          id
          name
        }
      }
    }
  `;

  const gqlRes = await fetch('https://' + SHOP_DOMAIN + '/admin/api/2024-01/graphql.json', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': access_token
    },
    body: JSON.stringify({ query })
  });

  const data = await gqlRes.json();
  console.log('GQL Result:', JSON.stringify(data, null, 2));

  // Let's also check if page publishes are attached to publications
  const pubQuery = `
    query {
      page(id: "gid://shopify/Page/169297248441") {
        id
        resourcePublicationsV2(first: 10) {
          nodes {
            isPublished
            publication {
              id
              name
            }
          }
        }
      }
    }
  `;
  const pubRes = await fetch('https://' + SHOP_DOMAIN + '/admin/api/2024-01/graphql.json', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': access_token
    },
    body: JSON.stringify({ query: pubQuery })
  });
  const pubData = await pubRes.json();
  console.log('Resource Publications:', JSON.stringify(pubData, null, 2));
}
checkPublication();

