import fs from 'fs';
import path from 'path';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || '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';
const MAIN_THEME_ID = 189127983289;

const filesToVerify = [
  'sections/zvhc-header.liquid',
  'assets/zvhc-t01-components.css',
  'sections/zvhc-our-story.liquid',
  'templates/page.zvhc-our-story.json',
  'sections/zavelyn-track-order.liquid',
  'sections/zvhc-track-order.liquid',
  'templates/page.track-order.json',
  'templates/page.zvhc-track-order.json',
  'sections/zvhc-footer.liquid',
  'layout/theme.liquid'
];

async function verifyAll() {
  const tokenRes = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const { access_token } = await tokenRes.json();

  console.log(`Checking MAIN Theme ID: ${MAIN_THEME_ID}`);
  let allMatched = true;

  for (const file of filesToVerify) {
    const localContent = fs.readFileSync(path.resolve(file), 'utf-8');
    const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${MAIN_THEME_ID}/assets.json?asset[key]=${encodeURIComponent(file)}`, {
      headers: { 'X-Shopify-Access-Token': access_token }
    });
    const data = await res.json();
    if (!data.asset) {
      console.log(`❌ ${file} NOT FOUND on Shopify!`);
      allMatched = false;
      continue;
    }
    const remoteContent = data.asset.value;
    const localTrimmed = localContent.replace(/\r\n/g, '\n').trim();
    const remoteTrimmed = remoteContent.replace(/\r\n/g, '\n').trim();
    if (localTrimmed === remoteTrimmed) {
      console.log(`✅ ${file}: EXACT MATCH (${data.asset.size} bytes)`);
    } else {
      console.log(`⚠️ ${file}: MISMATCH (local: ${localTrimmed.length} vs remote: ${remoteTrimmed.length})`);
      allMatched = false;
    }
  }

  console.log(`\nOverall Parity: ${allMatched ? '✅ 100% SYNCHRONIZED' : '⚠️ DISCREPANCIES FOUND'}`);
}
verifyAll();

