import fs from 'fs';
import path from 'path';
import { launchSafeBrowser } from '../scripts/lib/safe_browser_session.mjs';

const ARTIFACT_DIR = 'C:\\Users\\Admin\\.gemini\\antigravity\\brain\\2f3e6b33-be3a-4971-95cb-b168e69dafef';

async function cdpCall(ws, method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = Math.floor(Math.random() * 100000);
    const handler = (data) => {
      try {
        const msg = JSON.parse(data.toString());
        if (msg.id === id) {
          ws.off('message', handler);
          if (msg.error) reject(new Error(msg.error.message));
          else resolve(msg.result);
        }
      } catch (e) {}
    };
    ws.on('message', handler);
    ws.send(JSON.stringify({ id, method, params }));
  });
}

async function capture() {
  console.log('--- Launching Safe Isolated Browser Session ---');
  const session = await launchSafeBrowser({ preferredPort: 9256, width: 1440, height: 900 });
  console.log(`Safe Browser PID: ${session.pid} on port: ${session.port}`);

  try {
    await new Promise(r => setTimeout(r, 2000));
    const tabsRes = await fetch(`http://127.0.0.1:${session.port}/json`);
    const tabs = await tabsRes.json();
    const pageTab = tabs.find(t => t.type === 'page');
    if (!pageTab) throw new Error('No page tab found');

    const { default: WebSocket } = await import('ws');
    const ws = new WebSocket(pageTab.webSocketDebuggerUrl);
    await new Promise(r => ws.once('open', r));

    await cdpCall(ws, 'Page.enable');
    await cdpCall(ws, 'DOM.enable');

    const saveScreenshot = async (filename) => {
      const { data } = await cdpCall(ws, 'Page.captureScreenshot', { format: 'png' });
      const outPath = path.join(ARTIFACT_DIR, filename);
      fs.writeFileSync(outPath, Buffer.from(data, 'base64'));
      console.log(`📸 Saved: ${filename}`);
    };

    const navigate = async (url, waitMs = 2500) => {
      await cdpCall(ws, 'Page.navigate', { url });
      await new Promise(r => setTimeout(r, waitMs));
    };

    const setViewport = async (width, height, isMobile = false) => {
      await cdpCall(ws, 'Emulation.setDeviceMetricsOverride', {
        width,
        height,
        deviceScaleFactor: 1,
        mobile: isMobile
      });
      await new Promise(r => setTimeout(r, 500));
    };

    // 1. Live Homepage Desktop Header (1440px)
    console.log('\nCapturing Live Homepage Desktop (1440px)...');
    await setViewport(1440, 900, false);
    await navigate('https://tryzavelyn.com/');
    await saveScreenshot('evidence_live_header_desktop_1440.png');

    // 2. Open Shop Dropdown
    console.log('Opening Shop Dropdown on Live...');
    await cdpCall(ws, 'Runtime.evaluate', {
      expression: `
        const btn = document.getElementById('zvhcShopBtn');
        if (btn) btn.click();
      `
    });
    await new Promise(r => setTimeout(r, 600));
    await saveScreenshot('evidence_live_shop_dropdown.png');

    // 3. Live Mobile Header & Drawer (375px)
    console.log('\nCapturing Live Mobile Header & Drawer (375px)...');
    await setViewport(375, 812, true);
    await navigate('https://tryzavelyn.com/');
    await cdpCall(ws, 'Runtime.evaluate', {
      expression: `
        if (typeof toggleZvhcMobileDrawer === 'function') {
          toggleZvhcMobileDrawer(true);
        } else {
          const btn = document.getElementById('zvhcMobileMenuBtn');
          if (btn) btn.click();
        }
      `
    });
    await new Promise(r => setTimeout(r, 800));
    await saveScreenshot('evidence_live_mobile_drawer.png');

    // 4. Live Our Story Page Desktop (1440px)
    console.log('\nCapturing Live Our Story Desktop (1440px)...');
    await setViewport(1440, 900, false);
    await navigate('https://tryzavelyn.com/pages/our-story');
    await saveScreenshot('evidence_live_our_story_desktop.png');

    // 5. Live Our Story Page Mobile (375px)
    console.log('Capturing Live Our Story Mobile (375px)...');
    await setViewport(375, 812, true);
    await navigate('https://tryzavelyn.com/pages/our-story');
    await saveScreenshot('evidence_live_our_story_mobile.png');

    // 6. Live Track Order Desktop (1440px)
    console.log('\nCapturing Live Track Order Desktop (1440px)...');
    await setViewport(1440, 900, false);
    await navigate('https://tryzavelyn.com/pages/track-order');
    await saveScreenshot('evidence_live_track_order_desktop.png');

    // 7. Live Track Order Mobile (375px)
    console.log('Capturing Live Track Order Mobile (375px)...');
    await setViewport(375, 812, true);
    await navigate('https://tryzavelyn.com/pages/track-order');
    await saveScreenshot('evidence_live_track_order_mobile.png');

    // 8. Live Batana PDP Desktop (1440px)
    console.log('\nCapturing Live Batana PDP Desktop (1440px)...');
    await setViewport(1440, 900, false);
    await navigate('https://tryzavelyn.com/products/zvhc-batana-hair-growth-oil');
    await saveScreenshot('evidence_live_batana_pdp_desktop.png');

    // 9. Live Legacy Funnel (Holster) Desktop (1440px)
    console.log('\nCapturing Live Legacy Funnel (Holster) (1440px)...');
    await setViewport(1440, 900, false);
    await navigate('https://tryzavelyn.com/products/breakout-2-0-holster-built-for-maximum-concealment-copy');
    await saveScreenshot('evidence_live_legacy_holster_desktop.png');

    ws.close();
    console.log('\nClosing safe browser session...');
    await session.close();
    console.log('✅ Safe browser session cleanly closed.');
  } catch (err) {
    console.error('Error during capture:', err);
    await session.close();
  }
}
