const LIVE_THEME_ID = 189127983289;
const DRAFT_THEME_ID = 189175955641;

async function copyAsset(key) {
  const tokenRes = await fetch('https://' + SHOP_DOMAIN + '/admin/oauth/access_token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const { access_token } = await tokenRes.json();

  const getRes = await fetch('https://' + SHOP_DOMAIN + '/admin/api/2024-01/themes/' + LIVE_THEME_ID + '/assets.json?asset[key]=' + encodeURIComponent(key), {
    headers: { 'X-Shopify-Access-Token': access_token }
  });
  const getData = await getRes.json();
  if (!getData.asset) {
    console.log('Get failed:', getData);
    return;
  }

  const putBody = { asset: { key } };
  if (getData.asset.value) putBody.asset.value = getData.asset.value;
  else if (getData.asset.attachment) putBody.asset.attachment = getData.asset.attachment;

  const putRes = await fetch('https://' + SHOP_DOMAIN + '/admin/api/2024-01/themes/' + DRAFT_THEME_ID + '/assets.json', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', 'X-Shopify-Access-Token': access_token },
    body: JSON.stringify(putBody)
  });
  const putData = await putRes.json();
  console.log('Copied ' + key + ':', putRes.status, putData.asset ? 'OK' : putData);
}
copyAsset('config/settings_schema.json');
"

