  });
  const { access_token } = await tokenRes.json();
  return access_token;
}

async function putAsset(token, key, value, attachment = null) {
  const body = { asset: { key } };
  if (value) body.asset.value = value;
  if (attachment) body.asset.attachment = attachment;

  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${TARGET_DRAFT_ID}/assets.json`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
