async function syncTheme() {
  const token = await getAccessToken();
  console.log('Access token acquired. Syncing live theme to Draft Theme ID:', TARGET_DRAFT_ID);

  // 1. Fetch live theme assets list
  const listRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${LIVE_THEME_ID}/assets.json`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const listData = await listRes.json();
  const allAssets = listData.assets || [];
  console.log(`Total live theme assets to process: ${allAssets.length}`);

  // Categorize assets by type
  const configs = allAssets.filter(a => a.key.startsWith('config/'));
  const snippets = allAssets.filter(a => a.key.startsWith('snippets/'));
  const sections = allAssets.filter(a => a.key.startsWith('sections/'));
  const assets = allAssets.filter(a => a.key.startsWith('assets/'));
  const layouts = allAssets.filter(a => a.key.startsWith('layout/'));
  const locales = allAssets.filter(a => a.key.startsWith('locales/'));
  const templates = allAssets.filter(a => a.key.startsWith('templates/'));

  async function copyBatch(batch, label) {
    console.log(`\n--- Copying ${label} (${batch.length} files) ---`);
    let success = 0;
    // Concurrency limit 4
    for (let i = 0; i < batch.length; i += 4) {
      const slice = batch.slice(i, i + 4);
      await Promise.all(slice.map(async (item) => {
        // Check if file exists locally first
        const localPath = path.resolve(item.key);
        let val = null;
        if (fs.existsSync(localPath)) {
          val = fs.readFileSync(localPath, 'utf-8');
        } else {
          // Fetch from live theme
          const getRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${LIVE_THEME_ID}/assets.json?asset[key]=${encodeURIComponent(item.key)}`, {
            headers: { 'X-Shopify-Access-Token': token }
          });
          const getData = await getRes.json();
          val = getData.asset?.value;
        }

        if (val) {
          const ok = await putAsset(token, item.key, val);
          if (ok) success++;
        }
      }));
      process.stdout.write(`.`);
    }
    console.log(`\n${label}: ${success}/${batch.length} copied.`);
  }

  // Upload in strict dependency order:
  await copyBatch(configs, 'Config');
  await copyBatch(locales, 'Locales');
  await copyBatch(layouts, 'Layout');
  await copyBatch(snippets, 'Snippets');
  await copyBatch(sections, 'Sections');
  await copyBatch(assets.filter(a => a.key.endsWith('.css') || a.key.endsWith('.js')), 'CSS & JS Assets');
  await copyBatch(templates, 'Templates');

  // Verify previewable
  const checkRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${TARGET_DRAFT_ID}.json`, {
    headers: { 'X-Shopify-Access-Token': token }
