async function putAssetWithRetry(token, key, value, retries = 3) {
  for (let attempt = 1; attempt <= retries; attempt++) {
    const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${TARGET_DRAFT_ID}/assets.json`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
