    headers: { 'X-Shopify-Access-Token': token }
  });
  const listData = await listRes.json();
  const allAssets = listData.assets || [];

  const existingRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${TARGET_DRAFT_ID}/assets.json`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const existingData = await existingRes.json();
  const existingKeys = new Set((existingData.assets || []).map(a => a.key));
  console.log(`Already uploaded in Draft Theme: ${existingKeys.size} assets.`);

  const filterAndSort = (prefix) => {
    return allAssets
      .filter(a => a.key.startsWith(prefix) && !existingKeys.has(a.key))
      .map(a => a.key);
  };

  const categories = [
    { name: 'Config', keys: filterAndSort('config/') },
    { name: 'Locales', keys: filterAndSort('locales/') },
    { name: 'Layout', keys: filterAndSort('layout/') },
    { name: 'Snippets', keys: filterAndSort('snippets/') },
    { name: 'Sections', keys: filterAndSort('sections/') },
    { name: 'Assets (CSS/JS)', keys: allAssets.filter(a => a.key.startsWith('assets/') && (a.key.endsWith('.css') || a.key.endsWith('.js')) && !existingKeys.has(a.key)).map(a => a.key) },
    { name: 'Templates', keys: filterAndSort('templates/') }
  ];

  for (const cat of categories) {
