          headers: { 'X-Shopify-Access-Token': token }
        });
        const getData = await getRes.json();
        val = getData.asset?.value;
        await sleep(250);
      }

      if (val) {
        const ok = await putAssetWithRetry(token, key, val);
        if (ok) count++;
      }
      await sleep(250); // respect 4 calls/second
    }
    console.log(`✅ ${cat.name}: ${count}/${cat.keys.length} uploaded.`);
  }

  // Check theme status
  const themeRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${TARGET_DRAFT_ID}.json`, {
    headers: { 'X-Shopify-Access-Token': token }
