import fs from 'fs';
import path from 'path';
import { launchSafeBrowser } from '../scripts/lib/safe_browser_session.mjs';

const ARTIFACT_DIR = 'C:\\Users\\Admin\\.gemini\\antigravity\\brain\\2f3e6b33-be3a-4971-95cb-b168e69dafef';
const DRAFT_THEME_ID = 189175955641;

async function captureDraftReview() {
  console.log('--- Launching Safe Isolated Browser Session for Draft Visual Review ---');
  const session = await launchSafeBrowser({ preferredPort: 9260, width: 1440, height: 900 });
  console.log(`Safe Browser PID: ${session.pid} on port: ${session.port}`);

  try {
    await new Promise(r => setTimeout(r, 2000));
    const tabsRes = await fetch(`http://127.0.0.1:${session.port}/json`);
    const tabs = await tabsRes.json();
    const pageTab = tabs.find(t => t.type === 'page');
    if (!pageTab) throw new Error('No page tab found');

    const ws = new WebSocket(pageTab.webSocketDebuggerUrl);
    await new Promise((resolve, reject) => {
      ws.addEventListener('open', resolve);
      ws.addEventListener('error', reject);
    });

    let reqId = 1;
    function send(method, params = {}) {
      return new Promise((resolve, reject) => {
        const curId = reqId++;
        const handler = (evt) => {
          try {
            const msg = JSON.parse(evt.data.toString());
            if (msg.id === curId) {
              ws.removeEventListener('message', handler);
              if (msg.error) reject(new Error(msg.error.message || JSON.stringify(msg.error)));
              else resolve(msg.result);
            }
          } catch (e) {}
        };
        ws.addEventListener('message', handler);
        ws.send(JSON.stringify({ id: curId, method, params }));
      });
    }

    await send('Page.enable');
    await send('DOM.enable');

    const saveScreenshot = async (filename, clip = null) => {
      const params = { format: 'png' };
      if (clip) params.clip = clip;
      const result = await send('Page.captureScreenshot', params);
      const outPath = path.join(ARTIFACT_DIR, filename);
      fs.writeFileSync(outPath, Buffer.from(result.data, 'base64'));
      console.log(`📸 Saved: ${filename}`);
    };

    const navigate = async (url, waitMs = 3500) => {
      await send('Page.navigate', { url });
      await new Promise(r => setTimeout(r, waitMs));
    };

    const setViewport = async (width, height, isMobile = false) => {
      await send('Emulation.setDeviceMetricsOverride', {
        width,
        height,
        deviceScaleFactor: 2,
        mobile: isMobile
      });
      await new Promise(r => setTimeout(r, 600));
    };

    // 1. Initialize draft preview session cookie
    console.log('\nNavigating to Draft Theme Homepage...');
    await setViewport(1440, 900, false);
    await navigate(`https://tryzavelyn.com/?preview_theme_id=${DRAFT_THEME_ID}`);

    // 2. Capture Desktop Hero (1440px)
    console.log('Capturing Draft Desktop Hero...');
    await saveScreenshot('draft_creative_v4_hero_desktop_1440.png', { x: 0, y: 0, width: 1440, height: 750, scale: 2 });

    // 3. Scroll and capture Concerns Section Desktop
    console.log('Capturing Draft Concerns Section...');
    await send('Runtime.evaluate', {
      expression: `
        const el = document.getElementById('concerns');
        if (el) el.scrollIntoView();
      `
    });
