import fs from 'fs';
import path from 'path';
import { launchSafeBrowser } from '../scripts/lib/safe_browser_session.mjs';

const ARTIFACT_DIR = 'C:\\Users\\Admin\\.gemini\\antigravity\\brain\\2f3e6b33-be3a-4971-95cb-b168e69dafef';

async function main() {
  console.log('Launching safe isolated browser session...');
  const session = await launchSafeBrowser({ preferredPort: 9270, width: 1440, height: 1000 });
  console.log(`Browser launched on port ${session.port} with isolated PID ${session.pid}`);

  try {
    await new Promise(r => setTimeout(r, 2000));
    const resTabs = await fetch(`http://127.0.0.1:${session.port}/json`);
    const tabs = await resTabs.json();
    const pageTab = tabs.find(t => t.type === 'page');
    if (!pageTab) throw new Error('No page tab found in Chrome session');

    const ws = new WebSocket(pageTab.webSocketDebuggerUrl);
    await new Promise((resolve, reject) => {
      ws.addEventListener('open', resolve);
      ws.addEventListener('error', reject);
    });

    let id = 1;
    function send(method, params = {}) {
      return new Promise((resolve, reject) => {
        const curId = id++;
        const handler = (evt) => {
          const msg = JSON.parse(evt.data.toString());
          if (msg.id === curId) {
            ws.removeEventListener('message', handler);
            if (msg.error) reject(msg.error);
            else resolve(msg.result);
          }
        };
        ws.addEventListener('message', handler);
        ws.send(JSON.stringify({ id: curId, method, params }));
      });
    }

    await send('Page.enable');
    await send('DOM.enable');

    // 1. Batana Oil - Desktop (1440px)
    console.log('Capturing Batana Oil (Desktop)...');
    await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 950, deviceScaleFactor: 2, mobile: false });
    await send('Page.navigate', { url: 'https://tryzavelyn.com/products/zvhc-batana-hair-growth-oil' });
    await new Promise(r => setTimeout(r, 4000));

    // Scroll to buybox
    await send('Runtime.evaluate', {
      expression: `document.querySelector('.zvhc-buybox')?.scrollIntoView({ behavior: 'instant', block: 'start' });`
    });
    await new Promise(r => setTimeout(r, 1000));

    const shot1 = await send('Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync(path.join(ARTIFACT_DIR, 'trustpilot_batana_oil_desktop_1440.png'), Buffer.from(shot1.data, 'base64'));
    console.log('Saved trustpilot_batana_oil_desktop_1440.png');

    // 2. Scalp Balm - Desktop (1440px)
    console.log('Capturing Scalp Balm (Desktop)...');
    await send('Page.navigate', { url: 'https://tryzavelyn.com/products/zvhc-raw-batana-scalp-balm' });
    await new Promise(r => setTimeout(r, 4000));
    await send('Runtime.evaluate', {
      expression: `document.querySelector('.zvhc-buybox')?.scrollIntoView({ behavior: 'instant', block: 'start' });`
    });
    await new Promise(r => setTimeout(r, 1000));
    const shot2 = await send('Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync(path.join(ARTIFACT_DIR, 'trustpilot_scalp_balm_desktop_1440.png'), Buffer.from(shot2.data, 'base64'));
    console.log('Saved trustpilot_scalp_balm_desktop_1440.png');

    // 3. Hairline Compact - Mobile (390px)
    console.log('Capturing Hairline Compact (Mobile 390px)...');
    await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 3, mobile: true });
    await send('Page.navigate', { url: 'https://tryzavelyn.com/products/zvhc-precision-hairline-compact' });
    await new Promise(r => setTimeout(r, 4000));
    await send('Runtime.evaluate', {
      expression: `document.querySelector('.zvhc-trustpilot-row')?.scrollIntoView({ behavior: 'instant', block: 'center' });`
    });
    await new Promise(r => setTimeout(r, 1000));
    const shot3 = await send('Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync(path.join(ARTIFACT_DIR, 'trustpilot_hairline_compact_mobile_390.png'), Buffer.from(shot3.data, 'base64'));
    console.log('Saved trustpilot_hairline_compact_mobile_390.png');

    // 4. Botanical Curl Cream - Mobile (390px)
    console.log('Capturing Botanical Curl Cream (Mobile 390px)...');
    await send('Page.navigate', { url: 'https://tryzavelyn.com/products/zvhc-botanical-curl-cream' });
    await new Promise(r => setTimeout(r, 4000));
    await send('Runtime.evaluate', {
      expression: `document.querySelector('.zvhc-trustpilot-row')?.scrollIntoView({ behavior: 'instant', block: 'center' });`
    });
    await new Promise(r => setTimeout(r, 1000));
    const shot4 = await send('Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync(path.join(ARTIFACT_DIR, 'trustpilot_curl_cream_mobile_390.png'), Buffer.from(shot4.data, 'base64'));
    console.log('Saved trustpilot_curl_cream_mobile_390.png');

    ws.close();
  } finally {
    console.log('Cleaning up isolated browser session...');
    await session.close();
    console.log('Browser closed safely.');
  }
}

main().catch(console.error);

