// 4. Parse transcript and build clean markdown conversation history
async function buildMarkdown() {
  const fileStream = fs.createReadStream(transPath);
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  const turns = [];
  let currentTurn = null;

  for await (const line of rl) {
    if (!line.trim()) continue;
    try {
      const step = JSON.parse(line);

      if (step.type === 'USER_INPUT') {
        if (currentTurn) {
          turns.push(currentTurn);
        }
        currentTurn = {
          stepIndex: step.step_index,
          createdAt: step.created_at,
          userContent: step.content || '',
          assistantResponses: [],
          toolCallsCount: 0
        };
      } else if (step.type === 'PLANNER_RESPONSE' && currentTurn) {
        if (step.tool_calls && step.tool_calls.length) {
          currentTurn.toolCallsCount += step.tool_calls.length;
        }
        if (step.content && step.content.trim()) {
          currentTurn.assistantResponses.push(step.content);
        }
      }
    } catch (e) {
      // ignore
    }
  }

  if (currentTurn) {
    turns.push(currentTurn);
  }

  let md = `# Zavelyn Shopify Storefront Optimization, Creative Direction & Full Architecture Session\n\n`;
  md += `**Store:** \`dsdujr-vn.myshopify.com\` / \`https://tryzavelyn.com\`\n`;
  md += `**Repository:** \`DarkTutemi/clone-shopify\`\n`;
  md += `**Branch:** \`feature/zavelyn-haircare-v1\`\n`;
  md += `**Conversation ID:** \`2f3e6b33-be3a-4971-95cb-b168e69dafef\`\n`;
  md += `**Total Conversation Turns:** ${turns.length}\n`;
  md += `**Export Date:** ${new Date().toISOString()}\n\n`;
  md += `---\n\n`;

  turns.forEach((turn, idx) => {
    md += `## Turn ${idx + 1} (${turn.createdAt || 'N/A'})\n\n`;

    // Extract user request clean
    let userText = turn.userContent;
    const reqMatch = userText.match(/<USER_REQUEST>([\s\S]*?)<\/USER_REQUEST>/);
    if (reqMatch) {
      userText = reqMatch[1].trim();
    } else {
      userText = userText.trim();
    }

    // Extract attached images (jpg, png, webp, jpeg)
    const imgMatches = [...turn.userContent.matchAll(/media_[0-9]+_[a-f0-9]+\.(?:jpg|png|webp|jpeg)/g)];
    const uniqueImgs = [...new Set(imgMatches.map(m => m[0]))];

    md += `### 👤 User Request:\n\n`;
    md += `${userText}\n\n`;

    if (uniqueImgs.length > 0) {
      md += `**Attached Images:**\n\n`;
      uniqueImgs.forEach(img => {
        md += `![User Reference](user_uploads/${img})\n\n`;
      });
    }

    if (turn.toolCallsCount > 0) {
      md += `*⚡ Execution: Ran ${turn.toolCallsCount} tool/system operations in this turn.*\n\n`;
    }

    md += `### 🤖 Assistant Response:\n\n`;
    if (turn.assistantResponses.length > 0) {
      const finalReply = turn.assistantResponses[turn.assistantResponses.length - 1];
      md += `${finalReply}\n\n`;
    } else {
      md += `*(Executed operations and synchronized store themes)*\n\n`;
    }

    md += `---\n\n`;
  });

  fs.writeFileSync(path.join(TARGET_DIR, 'FULL_CONVERSATION_HISTORY.md'), md, 'utf8');
  console.log(`Generated FULL_CONVERSATION_HISTORY.md with ${turns.length} turns.`);
}

