import fs from 'fs';

const ITEM_ID = '3256810083831556';
const URL = `https://www.aliexpress.com/item/${ITEM_ID}.html`;

async function fetchDirect() {
  console.log(`Fetching direct from ${URL}...`);
  try {
    const res = await fetch(URL, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
        'Accept-Language': 'en-US,en;q=0.9',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8',
        'Cache-Control': 'no-cache'
      }
    });

    console.log(`HTTP status: ${res.status}`);
    const html = await res.text();
    fs.writeFileSync(`scratch/raw_${ITEM_ID}.html`, html, 'utf8');
    console.log(`Saved raw HTML (${html.length} bytes) to scratch/raw_${ITEM_ID}.html`);

    // Quick regex checks
    const titleMatch = html.match(/<meta\s+(?:property|name)="og:title"\s+content="([^"]+)"/i) || html.match(/<title>([^<]+)<\/title>/i);
    console.log('Title:', titleMatch ? titleMatch[1] : 'N/A');

    const descMatch = html.match(/<meta\s+(?:property|name)="og:description"\s+content="([^"]+)"/i) || html.match(/<meta\s+name="description"\s+content="([^"]+)"/i);
    console.log('Description:', descMatch ? descMatch[1] : 'N/A');

    const imgMatches = [...html.matchAll(/"(https:\/\/[^"]+\.(?:jpg|png|webp|jpeg)[^"]*)"/g)];
    const aliImages = [...new Set(imgMatches.map(m => m[1]).filter(url => url.includes('ae01.alicdn.com')))];
    console.log(`Found ${aliImages.length} alicdn images.`);
    if (aliImages.length > 0) {
      console.log('Sample images:', aliImages.slice(0, 5));
    }

    // Check if runParams or dataModule exists
    const hasRunParams = html.includes('window.runParams') || html.includes('window._d_c_');
    console.log('Has runParams/DCData:', hasRunParams);

    return { success: true, htmlLength: html.length, title: titleMatch?.[1], imagesCount: aliImages.length };
  } catch (err) {
    console.error('Fetch error:', err.message);
    return { success: false, error: err.message };
  }
}

fetchDirect();

import fs from 'fs';

const html = fs.readFileSync('scratch/raw_3256810083831556.html', 'utf8');

console.log('--- Checking Scripts in HTML ---');
const scripts = html.match(/<script\b[^>]*>([\s\S]*?)<\/script>/gi) || [];
console.log(`Total script tags: ${scripts.length}`);

let runParamsFound = false;
for (const s of scripts) {
  if (s.includes('window.runParams') || s.includes('runParams')) {
    runParamsFound = true;
    console.log('Found runParams script tag! Length:', s.length);
    fs.writeFileSync('scratch/runParams_3256810083831556.txt', s, 'utf8');
  }
  if (s.includes('imagePathList') || s.includes('skuModule') || s.includes('specsModule') || s.includes('descriptionModule')) {
    console.log('Found product modules script tag! Length:', s.length);
    fs.writeFileSync('scratch/productModules_3256810083831556.txt', s, 'utf8');
  }
}

if (!runParamsFound) {
  console.log('No direct window.runParams script tag found.');
}

