import fs from 'fs';
import path from 'path';

const images = [
  "https://ae-pic-a1.aliexpress-media.com/kf/Sad62ea29ce5e49b6b280058b956c1b05c.jpg",
  "https://ae-pic-a1.aliexpress-media.com/kf/Se73bd05eea95455dab08529126ce54faG.jpg",
  "https://ae-pic-a1.aliexpress-media.com/kf/S8eaeda0b669942eb81943478e6d7a6140.jpg",
  "https://ae-pic-a1.aliexpress-media.com/kf/S7eaf178945184678a6bb13c0f3971826m.jpg",
  "https://ae-pic-a1.aliexpress-media.com/kf/S94767c9d3d024617bb531ab5236c0424G.jpg",
  "https://ae-pic-a1.aliexpress-media.com/kf/S0072585e605d4ad7bd565d9ce40ef8bci.jpg"
];

const DIR = path.resolve('scratch/ali_item_08_images');
if (!fs.existsSync(DIR)) fs.mkdirSync(DIR, { recursive: true });

async function downloadAll() {
  for (let i = 0; i < images.length; i++) {
    const url = images[i];
    console.log(`Downloading ${i + 1}/${images.length}: ${url}`);
    const res = await fetch(url);
    const buf = Buffer.from(await res.arrayBuffer());
    const file = path.join(DIR, `img_0${i + 1}.jpg`);
    fs.writeFileSync(file, buf);
    console.log(`Saved ${file} (${buf.length} bytes)`);
  }
}

downloadAll();

import fs from 'fs';

const html = fs.readFileSync('scratch/raw_3256810083831556.html', 'utf8');

// Look for description URL
const descUrlMatch = html.match(/"descriptionUrl":\s*"([^"]+)"/i) || html.match(/"detailDesc":\s*"([^"]+)"/i);
if (descUrlMatch) {
  console.log('Found description URL:', descUrlMatch[1]);
} else {
  console.log('No direct descriptionUrl match in HTML.');
}

// Search for any other alicdn / media links in html
const allUrls = [...html.matchAll(/https:\/\/[^"'\s\\]+\.(?:jpg|png|webp|jpeg)/gi)];
const uniqueUrls = [...new Set(allUrls.map(m => m[0]))];
console.log(`Found ${uniqueUrls.length} total image URLs in HTML.`);
uniqueUrls.forEach(u => console.log(' -', u));

import fs from 'fs';
import path from 'path';
import { launchSafeBrowser } from '../scripts/lib/safe_browser_session.mjs';

const ITEM_ID = '3256810083831556';
const URL = `https://www.aliexpress.us/item/${ITEM_ID}.html`;

async function main() {
  console.log('Launching safe isolated browser to inspect AliExpress item...');
  const session = await launchSafeBrowser({ preferredPort: 9285, width: 1440, height: 1000 });
  console.log(`Browser launched on port ${session.port} with isolated PID ${session.pid}`);

  try {
    await new Promise(r => setTimeout(r, 2000));
    const resTabs = await fetch(`http://127.0.0.1:${session.port}/json`);
    const tabs = await resTabs.json();
    const pageTab = tabs.find(t => t.type === 'page');
    if (!pageTab) throw new Error('No page tab found in Chrome session');

    const ws = new WebSocket(pageTab.webSocketDebuggerUrl);
    await new Promise((resolve, reject) => {
      ws.addEventListener('open', resolve);
      ws.addEventListener('error', reject);
    });

    let id = 1;
    function send(method, params = {}) {
      return new Promise((resolve, reject) => {
        const curId = id++;
        const handler = (evt) => {
          const msg = JSON.parse(evt.data.toString());
          if (msg.id === curId) {
            ws.removeEventListener('message', handler);
            if (msg.error) reject(msg.error);
            else resolve(msg.result);
          }
        };
        ws.addEventListener('message', handler);
        ws.send(JSON.stringify({ id: curId, method, params }));
      });
    }

    await send('Page.enable');
    await send('DOM.enable');
    await send('Runtime.enable');

    console.log(`Navigating to ${URL}...`);
    await send('Page.navigate', { url: URL });
    await new Promise(r => setTimeout(r, 6000));

    // Scroll down to trigger lazy loading of description & specs
    console.log('Scrolling down page...');
    for (let scroll = 0; scroll < 4; scroll++) {
      await send('Runtime.evaluate', {
        expression: `window.scrollBy(0, 1000);`
      });
      await new Promise(r => setTimeout(r, 1500));
    }

    // Extract product data from live DOM
    const evalResult = await send('Runtime.evaluate', {
      expression: `(() => {
        const title = document.querySelector('h1')?.innerText || document.title;
        const price = document.querySelector('.product-price-value, [class*="price--current--"]')?.innerText;

        // Specs table
        const specs = [];
        document.querySelectorAll('[class*="specification--prop--"] li, [class*="specs-list"] li, [class*="detail-desc-decorate-specifications"] tr').forEach(el => {
          specs.push(el.innerText.trim());
        });

        // Description text & images
        const descContainer = document.querySelector('#product-description, [class*="detail-desc-decorate-content"]');
        const descText = descContainer?.innerText || '';
        const descImages = Array.from(descContainer?.querySelectorAll('img') || []).map(img => img.src);

        // SKU / Variants
        const skus = [];
        document.querySelectorAll('[class*="sku-item"], [class*="sku-property-item"]').forEach(el => {
          skus.push(el.innerText.trim() || el.getAttribute('title'));
        });

        return {
          title,
          price,
          specs,
          descText: descText.slice(0, 2000),
          descImages,
          skus
        };
      })()`,
      returnByValue: true
    });

    console.log('--- Extracted Browser Data ---');
    console.log(JSON.stringify(evalResult.result.value, null, 2));
    fs.writeFileSync('scratch/browser_extracted_3256810083831556.json', JSON.stringify(evalResult.result.value, null, 2), 'utf8');

    ws.close();
  } finally {
    console.log('Cleaning up isolated browser session...');
    await session.close();
    console.log('Browser closed safely.');
  }
}

main().catch(console.error);

