    console.log('Template Suffix:', d.product.template_suffix);
    console.log('Tags:', d.product.tags);
    console.log('Options:', JSON.stringify(d.product.options, null, 2));
    console.log('Variants:');
    d.product.variants.forEach(v => {
      console.log(` - ID: ${v.id} | Title: "${v.title}" | Option1: "${v.option1}" | Price: ${v.price} | Compare: ${v.compare_at_price} | SKU: ${v.sku}`);
    });
    console.log('Images count:', d.product.images.length);
    fs.writeFileSync(`scratch/sample_product_${id}.json`, JSON.stringify(d.product, null, 2), 'utf8');
  }
}

inspectProducts().catch(console.error);

