async function generate() {
  fs.writeFileSync('scratch/card_07.html', htmlCard7, 'utf8');
  fs.writeFileSync('scratch/card_08.html', htmlCard8, 'utf8');

  console.log('Launching browser to capture cards...');
  const session = await launchSafeBrowser({ preferredPort: 9290, width: 1000, height: 1000 });

  try {
    await new Promise(r => setTimeout(r, 2000));
    const resTabs = await fetch(`http://127.0.0.1:${session.port}/json`);
    const tabs = await resTabs.json();
    const pageTab = tabs.find(t => t.type === 'page');

    const ws = new WebSocket(pageTab.webSocketDebuggerUrl);
    await new Promise((resolve, reject) => {
      ws.addEventListener('open', resolve);
      ws.addEventListener('error', reject);
    });

    let id = 1;
    function send(method, params = {}) {
      return new Promise((resolve, reject) => {
        const curId = id++;
        const handler = (evt) => {
          const msg = JSON.parse(evt.data.toString());
          if (msg.id === curId) {
            ws.removeEventListener('message', handler);
            if (msg.error) reject(msg.error);
            else resolve(msg.result);
          }
        };
        ws.addEventListener('message', handler);
        ws.send(JSON.stringify({ id: curId, method, params }));
      });
    }

    await send('Page.enable');
    await send('Emulation.setDeviceMetricsOverride', { width: 1000, height: 1000, deviceScaleFactor: 2, mobile: false });

    // Card 7
    const filePath7 = 'file:///' + path.resolve('scratch/card_07.html').replace(/\\/g, '/');
    await send('Page.navigate', { url: filePath7 });
    await new Promise(r => setTimeout(r, 1500));
    const shot7 = await send('Page.captureScreenshot', { format: 'jpeg', quality: 95 });
    fs.writeFileSync(path.join(DIR, 'img_07.jpg'), Buffer.from(shot7.data, 'base64'));
    console.log('Saved img_07.jpg');

    // Card 8
    const filePath8 = 'file:///' + path.resolve('scratch/card_08.html').replace(/\\/g, '/');
    await send('Page.navigate', { url: filePath8 });
    await new Promise(r => setTimeout(r, 1500));
    const shot8 = await send('Page.captureScreenshot', { format: 'jpeg', quality: 95 });
    fs.writeFileSync(path.join(DIR, 'img_08.jpg'), Buffer.from(shot8.data, 'base64'));
    console.log('Saved img_08.jpg');

    ws.close();
  } finally {
    await session.close();
  }
}

