import fs from 'fs';

const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = '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';
const SHOP = 'dsdujr-vn.myshopify.com';
const TARGET_THEMES = ['189127983289', '189175955641'];

async function getAccessToken() {
  const res = await fetch(`https://${SHOP}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      client_id: CLIENT_ID,
      client_secret: CLIENT_SECRET,
      grant_type: 'client_credentials'
    })
  });
  const d = await res.json();
  return d.access_token;
}

function sleep(ms) {
  return new Promise(r => setTimeout(r, ms));
}

async function uploadAsset(token, themeId, key, content) {
  for (let attempt = 1; attempt <= 4; attempt++) {
    await sleep(350);
    const res = await fetch(`https://${SHOP}/admin/api/2024-10/themes/${themeId}/assets.json`, {
      method: 'PUT',
      headers: {
        'X-Shopify-Access-Token': token,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        asset: { key, value: content }
      })
    });
    if (res.status === 200 || res.status === 201) {
      console.log(`SUCCESS: [Theme ${themeId}] ${key}`);
      return true;
    }
    if (res.status === 429) {
      console.log(`Rate limited on ${key}, retrying...`);
      await sleep(1500 * attempt);
      continue;
    }
    const err = await res.text();
    console.error(`FAILED: [Theme ${themeId}] ${key} - status: ${res.status} - err: ${err}`);
    return false;
  }
}

async function main() {
  const token = await getAccessToken();
  console.log('Obtained token.');

  const files = [
    { key: 'templates/product.zvhc-mask.json', path: 'templates/product.zvhc-mask.json' },
    { key: 'sections/zvhc-pdp-main.liquid', path: 'sections/zvhc-pdp-main.liquid' }
  ];

  for (const themeId of TARGET_THEMES) {
    console.log(`\n--- Uploading to Theme: ${themeId} ---`);
    for (const f of files) {
      const content = fs.readFileSync(f.path, 'utf8');
      await uploadAsset(token, themeId, f.key, content);
    }
  }

  console.log('\n=== THEME ASSETS SYNCED SUCCESSFULLY ===');
}

main().catch(console.error);

