async function getAccessToken() {
  const res = await fetch(`https://${SHOP}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      client_id: CLIENT_ID,
      client_secret: CLIENT_SECRET,
      grant_type: 'client_credentials'
    })
  });
  const d = await res.json();
  return d.access_token;
}

async function activateProduct() {
  const token = await getAccessToken();
  console.log('Updating product 08 to active status...');

  // 1. Update product status to active
  const res = await fetch(`https://${SHOP}/admin/api/2024-10/products/${PRODUCT_ID}.json`, {
    method: 'PUT',
    headers: {
      'X-Shopify-Access-Token': token,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      product: {
        id: PRODUCT_ID,
        status: 'active',
        published: true
      }
    })
  });

  const d = await res.json();
  console.log(`Product status is now: ${d.product?.status}`);

  // 2. Publish to all available publications/sales channels via GraphQL
  console.log('\nQuerying available publications for sales channels...');
  const pubQuery = `
    query {
      publications(first: 20) {
        edges {
          node {
            id
            name
          }
        }
      }
    }
  `;

  const pubRes = await fetch(`https://${SHOP}/admin/api/2024-10/graphql.json`, {
    method: 'POST',
    headers: {
      'X-Shopify-Access-Token': token,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ query: pubQuery })
  });

  const pubData = await pubRes.json();
  const publications = pubData.data?.publications?.edges?.map(e => e.node) || [];
  console.log('Available publications:');
  publications.forEach(p => console.log(` - ID: ${p.id} | Name: ${p.name}`));

  // Publish product 08 to each publication
  for (const pub of publications) {
    const publishMutation = `
      mutation publishablePublish($id: ID!, $input: [PublicationInput!]!) {
        publishablePublish(id: $id, input: $input) {
          publishable {
            availablePublicationCount
          }
          userErrors {
            field
            message
          }
        }
      }
    `;

    const pRes = await fetch(`https://${SHOP}/admin/api/2024-10/graphql.json`, {
      method: 'POST',
      headers: {
        'X-Shopify-Access-Token': token,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        query: publishMutation,
        variables: {
          id: `gid://shopify/Product/${PRODUCT_ID}`,
          input: [{ publicationId: pub.id }]
        }
      })
    });

    const pData = await pRes.json();
    console.log(`Published to ${pub.name}:`, pData.data?.publishablePublish?.userErrors?.length === 0 ? 'SUCCESS' : pData.data?.publishablePublish?.userErrors);
  }

  console.log('\n=== PRODUCT 08 IS NOW ACTIVE AND FULLY PUBLISHED ===');
}

