  console.log('Launching safe isolated browser session to capture Product 08 evidence...');
  const session = await launchSafeBrowser({ preferredPort: 9295, width: 1440, height: 1000 });
  console.log(`Browser launched on port ${session.port} with isolated PID ${session.pid}`);

  try {
    await new Promise(r => setTimeout(r, 2000));
    const resTabs = await fetch(`http://127.0.0.1:${session.port}/json`);
    const tabs = await resTabs.json();
    const pageTab = tabs.find(t => t.type === 'page');
    if (!pageTab) throw new Error('No page tab found in Chrome session');

    const ws = new WebSocket(pageTab.webSocketDebuggerUrl);
    await new Promise((resolve, reject) => {
      ws.addEventListener('open', resolve);
      ws.addEventListener('error', reject);
    });

    let id = 1;
    function send(method, params = {}) {
      return new Promise((resolve, reject) => {
        const curId = id++;
        const handler = (evt) => {
          const msg = JSON.parse(evt.data.toString());
          if (msg.id === curId) {
            ws.removeEventListener('message', handler);
            if (msg.error) reject(msg.error);
            else resolve(msg.result);
          }
        };
        ws.addEventListener('message', handler);
        ws.send(JSON.stringify({ id: curId, method, params }));
      });
    }

    await send('Page.enable');
    await send('DOM.enable');

    // 1. Desktop 1440px - Buy Box
    console.log('Capturing Desktop Buy Box (1440px)...');
